COLLDATA("sh5818","ar",[[1,"وَقَالَ يحيى بن معيد إِسْمَاعِيل بن مُسلم المَخْزُومِي ثِقَة يروي عَنهُ وَكِيع يحدث عَن عبد الله بن عبيد بن عُمَيْر"],[2,"وَقَالَ بن معِين إِسْمَاعِيل بن مُسلم الْعَبْدي ثِقَة وَهُوَ بَصرِي روى عَنهُ بن معن"],[3,"إِسْمَاعِيل بن أُميَّة إِذا حدث عَن الثِّقَات فَهُوَ ثِقَة قَالَه بن معِين"],[4,"إِسْمَاعِيل بن سميع كُوفِي ثِقَة وَقَالَ مرّة أُخْرَى ثِقَة مَأْمُون"],[5,"نَا مُحَمَّد بن مخلد نَا صَالح بن أَحْمد بن حَنْبَل نَا عَليّ بن الْمَدِينِيّ قيل ليحيى بن سعيد فالسدي يَعْنِي إِسْمَاعِيل بن عبد الرَّحْمَن قَالَ السّديّ عندنَا لَا بَأْس بِهِ"],[6,"نَا يحيى بن مُحَمَّد بن صاعد وَمُحَمّد بن هَارُون الْحَضْرَمِيّ قَالَا نَا هِشَام الرِّفَاعِي نَا إِسْمَاعِيل بن شُعَيْب السمان وَكَانَ ثِقَة"],[7,"وَقَالَ أَحْمد بن صَالح الْمصْرِيّ إِسْمَاعِيل بن أبي حَكِيم عَن عُبَيْدَة بن سُفْيَان هَذَا من أثبت أَسَانِيد أهل الْمَدِينَة إِسْمَاعِيل لَهُ شَأْن وَقَالَ يحيى بن معِين إِسْمَاعِيل بن أبي حَكِيم صَالح"],[8,"نَا عبد الله بن مُحَمَّد الْبَغَوِيّ قَالَ ثَنَا مُحَمَّد بن غيلَان ثَنَا بن معِين إِسْمَاعِيل بن عَيَّاش ثِقَة وَفِي رِوَايَة أُخْرَى لَيْسَ بِهِ بَأْس وَقَالَ احْمَد بن حَنْبَل كَانَ إِسْمَاعِيل بن عَيَّاش صَاحب حَدِيث"],[9,"وَقَالَ عَليّ بن الْمَدِينِيّ إِسْمَاعِيل بن شروس ثِقَة من أهل الْيمن"],[10,"وَقَالَ بن معِين قد سَمِعت من إِسْمَاعِيل بن مُحَمَّد بن جحادة وَكَانَ أعمى وَلم يكن بِهِ بَأْس"],[11,"وَقَالَ أَحْمد بن حَنْبَل إِسْمَاعِيل بن أبان الْوراق ثِقَة وَقَالَ فِيهِ عُثْمَان بن أبي شيبَة إِسْمَاعِيل بن أبان الْوراق ثِقَة صَحِيح الحَدِيث ورع مُسلم قيل لعُثْمَان فان إِسْمَاعِيل بن أبان الْوراق عندنَا غير مَحْمُود فَقَالَ كَانَ هَاهُنَا إِسْمَاعِيل آخر يُقَال لَهُ بن أبان غير الْوراق وَكَانَ كذابا الَّذِي كَانَ يروي عَن بن عجلَان"],[12,"وَسُئِلَ يحيى بن معِين عَن إِسْمَاعِيل بن زَكَرِيَّا الخلقاني أَبُو زِيَاد فَقَالَ ثِقَة"],[13,"وَإِسْمَاعِيل بن مُحَمَّد بن سعد ثِقَة"],[14,"وَإِسْمَاعِيل بن مجَالد صَالح وَقَالَ عُثْمَان بن أبي شيبَة كَانَ إِسْمَاعِيل بن مجَالد ثِقَة وصدوقا وليتني كنت كتبت عَنهُ كَانَ يحدث عَن أبي إِسْحَاق وَسماك وَبَيَان وَلَيْسَ بِهِ بَأْس وَقَالَ احْمَد بن حَنْبَل مَا أرَاهُ إِلَّا صَدُوقًا"],[15,"حَدثنَا مُحَمَّد بن مخلد ثَنَا الْعَبَّاس بن مُحَمَّد قَالَ ثَنَا أَبُو بكر بن أبي الْأسود قَالَ سَمِعت غنْدر يَقُول نشأت فِي الحَدِيث يَوْم نشأت وَلَيْسَ أحد يقدم فِي الحَدِيث على إِسْمَاعِيل بن علية نَا مُحَمَّد بن الْحسن قَالَ نَا الْحُسَيْن بن إِدْرِيس قَالَ سَمِعت عُثْمَان بن أبي شيبَة يَقُول بن علية أثبت من حَمَّاد بن زيد وَحَمَّاد بن سَلمَة وَلَا أقدم على بن علية أحدا من الْبَصرِيين وَلَا يحيى وَلَا عبد الرَّحْمَن وَلَا بشر بن الْمفضل"],[16,"وَقَالَ بن معِين إِسْمَاعِيل بن جَعْفَر الْمدنِي وأخوة ثقتان جَمِيعًا"],[17,"إِسْمَاعِيل بن إِبْرَاهِيم بن عقبَة مديني ثِقَة"],[18,"قَالَ أَبُو مسْهر نَا إِسْمَاعِيل بن عبد الله بن سَمَاعه أَبُو مُحَمَّد وَكَانَ من الفاضلين مولى عمر بن الْخطاب"],[19,"قَالَ بن معِين إِسْمَاعِيل بن سَالم الْأَسدي ثِقَة قَالَ بن أبي خَيْثَمَة أَصله كُوفِي نزل بَغْدَاد"],[20,"قَالَ بن معِين إِسْمَاعِيل بن الرّبيع الْكُوفِي ثِقَة"],[21,"وَإِسْمَاعِيل بن أَوسط صَالح"],[22,"أَبُو إِبْرَاهِيم الترجماني لَيْسَ بِهِ بَأْس واسْمه إِسْمَاعِيل بن إِبْرَاهِيم الْهُذلِيّ"],[23,"أَبُو إِسْمَاعِيل الْملَائي ثِقَة إِسْمَاعِيل بن إِسْحَاق كَذَا قَالَ من اسْمه أَيُّوب"],[24,"نَا عبد الله بن مُحَمَّد قَالَ حَدثنِي الصَّلْت بن مَسْعُود قَالَ سَمِعت بن عُيَيْنَة يَقُول مَا رَأَيْت بِالْبَصْرَةِ مثل أَيُّوب نَا عبد الله بن مُحَمَّد الْبَغَوِيّ نَا عَليّ بن مُسلم ثَنَا أَبُو دَاوُد عَن شُعْبَة قَالَ مَا رَأَيْت قطّ مثل أَيُّوب وَيُونُس وَابْن عون وَفِي رِوَايَة أُخْرَى قَالَ شُعْبَة حَدثنَا أَيُّوب سيد الْفُقَهَاء نَا أَحْمد بن عَليّ بن الْعَلَاء نَا أَبُو يُوسُف القلوسي قَالَ نَا أَبُو همام الخازكي قَالَ سَمِعت مَالك بن أنس يَقُول مَا بالعراق أحد أقدمه على أَيُّوب وَمُحَمّد بن سِيرِين هَذَا فِي زَمَانه وَهَذَا فِي زَمَانه وَقَالَ بن معِين أَيُّوب السّخْتِيَانِيّ بَصرِي ثِقَة"],[25,"قَالَ أَحْمد بن حَنْبَل أَيُّوب بن مُوسَى ثِقَة"],[26,"أَيُّوب بن أبي مِسْكين أَبُو الْعَلَاء رجل صَالح ثِقَة وَكَانَ قضايا قَالَه احْمَد"],[27,"حَدثنَا عبد الرَّحْمَن بن مُحَمَّد الزُّهْرِيّ نَا إِسْمَاعِيل بن إِسْحَاق قَالَ نَا عَليّ بن الْمَدِينِيّ قَالَ نَا سُفْيَان بن عَائِذ الطَّائِي وَكَانَ ثِقَة"],[28,"وَقَالَ أَحْمد أَيُّوب بن النجار شيخ ثِقَة عفيف رجل صَالح وَقَالَ بن معِين أَيُّوب بن النجار ثِقَة وهوه يمامي"],[29,"أَيُّوب بن منقذ لم أسمع أحدا روى عَنهُ غير مُعْتَمر وَهُوَ شيخ بَصرِي أَرْجُو أَن لَا يكون بِهِ بَأْس قَالَه بن معِين"],[30,"أَيُّوب بن يزِيد الديلِي من أُسَمِّهِ إِبْرَاهِيم"],[31,"قَالَ الْهَيْثَم بن عدي لِابْنِ جريد ولعَبْد الْعَزِيز بن أبي رواد كَيفَ إِبْرَاهِيم عنْدكُمْ فِي الحَدِيث فَقَالَا ثِقَة"],[32,"وَقَالَ أَحْمد بن حَنْبَل إِبْرَاهِيم بن نشيط ثِقَة ثِقَة روى عَنهُ بن الْمُبَارك"],[33,"وَإِبْرَاهِيم بن سعد ثِقَة"],[34,"وَإِبْرَاهِيم بن مهَاجر لَيْسَ بِهِ بَأْس"],[35,"وَإِبْرَاهِيم بن عقبَة ثِقَة"],[36,"وَقَالَ بن معِين إِبْرَاهِيم بن أبي عبلة ثِقَة"],[37,"إِبْرَاهِيم بن طهْمَان ثِقَة وَقَالَ مرّة أُخْرَى صَالح"],[38,"وَقَالَ احْمَد بن صَالح إِبْرَاهِيم بن طريف ثِقَة"],[39,"وَقَالَ يحيى عَن إِبْرَاهِيم بن عبد الْأَعْلَى الَّذِي روى عَنهُ إِسْرَائِيل صَالح وَقَالَ أَحْمد بن حَنْبَل فِي إِبْرَاهِيم بن عبد الْأَعْلَى ثِقَة"],[40,"وَعَن يحيى بن معِين فِي إِبْرَاهِيم بن خَالِد الصَّنْعَانِيّ قَالَ كَانَ صديقا لي وَكَانَ ثِقَة وَمَا كتبت عَنهُ حَدِيث قَالَ أَحْمد بن حَنْبَل فِي إِبْرَاهِيم بن خَالِد ثِقَة وَأثْنى عَلَيْهِ خيرا"],[41,"إِبْرَاهِيم بن ميسرَة طائفي كسن مَكَّة ثِقَة وَقَالَ سُفْيَان حَدثنِي إِبْرَاهِيم بن مسيرَة من لم تَرَ عَيْنَاك مثله"],[42,"وَقَالَ يحيى بن معِين أَبُو هَارُون الغنوي إِبْرَاهِيم بن الْعَلَاء ثِقَة سمع من شُيُوخ الْبَصرِيين"],[43,"إِبْرَاهِيم بن مُحَمَّد بن الْمُنْتَشِر ثِقَة"],[44,"إِبْرَاهِيم بن الزبْرِقَان يروي عَنهُ أَبُو غَسَّان وَيحيى بن يمَان لَيْسَ بِهِ بَأْس"],[45,"وَقَالَ أَحْمد بن حَنْبَل إِبْرَاهِيم بن نَافِع ثِقَة"],[46,"وَإِبْرَاهِيم بن أبي حرَّة من أهل نَصِيبين ثِقَة حدث عَنهُ بن عُيَيْنَة وَابْن شَوْذَب"],[47,"وَقَالَ بن مهْدي كَانَ إِبْرَاهِيم بن نَافِع أوثق شيخ بِمَكَّة"],[48,"وَقَالَ يحيى بن معِين إِبْرَاهِيم بن بردَان مديني ثِقَة وَهُوَ إِبْرَاهِيم بن أبي النَّضر"],[49,"وَقَالَ بن معِين رَأَيْت إِبْرَاهِيم بن الْمُخْتَار يقدمهُ الرازيون على جمَاعَة"],[50,"إِبْرَاهِيم بن حميد الرُّؤَاسِي ثِقَة"],[51,"وَقَالَ بن عُيَيْنَة حَدثنَا إِبْرَاهِيم بن مسيرَة وَكَانَ من أصدق النَّاس وأوثقهم"],[52,"وَقَالَ بن معِين إِبْرَاهِيم بن عمر بن كيسَان يماني ثِقَة"],[53,"وَإِبْرَاهِيم بن سُوَيْد ثِقَة"],[54,"وَإِبْرَاهِيم مولى بجير ثِقَة"],[55,"وَإِبْرَاهِيم بن عبد الْأَعْلَى لَيْسَ بِهِ بَأْس"],[56,"وَقَالَ مُحَمَّد بن عبد الله بن نمير فِي إِبْرَاهِيم بن هراسة صَدُوق يحدث عَن ضعفاء"],[57,"قَالَ بن معِين إِبْرَاهِيم بن مَيْمُون مولى لآل سَمُرَة ثِقَة يروي عَنهُ وَكِيع وَأَبُو حَامِد الزبيرِي من اسْمه إِسْحَاق"],[58,"قَالَ إِسْحَاق بن رَاشد ثِقَة"],[59,"إِسْحَاق بن سُوَيْد ثِقَة"],[60,"وَقَالَ أَحْمد بن حَنْبَل إِسْحَاق بن حَازِم شيخ ثِقَة"],[61,"إِسْحَاق بن أبي بكر ثِقَة ثِقَة"],[62,"وَإِسْحَاق بن الْمُغيرَة هُوَ الَّذِي يُقَال لَهُ إِسْحَاق بن شرفى ثِقَة"],[63,"وَقَالَ بن عُثْمَان بن أبي شيبَة إِسْحَاق بن مَنْصُور ثِقَة صَدُوق وَكَأن غيرَة أثبت مِنْهُ"],[64,"وَقَالَ بن معِين إِسْحَاق بن عبد الله بن أبي طَلْحَة ثِقَة"],[65,"وَإِسْحَاق بن أبي بكر صَالح"],[66,"إِسْحَاق بن أبي إِسْرَائِيل ثِقَة وَأَبُو إِسْرَائِيل اسْمه إِبْرَاهِيم بن كامجرا"],[67,"نَا مُحَمَّد بن مخلد نَا مُحَمَّد بن إِسْحَاق الصَّنْعَانِيّ قَالَ قَالَ يحيى بن معِين أَشْعَث بن أبي الشعْثَاء هُوَ أَشْعَث بن سليم يكني أَبَا يزِيد الْمحَاربي ثِقَة وَقَالَ بن معِين الْأَشْعَث بن سليم بن الْأسود كُوفِي ثِقَة وسليم أَخُو أَبُو الشعْثَاء أَشْعَث بن أبي الشعْثَاء ثِقَة وَقَالَ أَحْمد بن حَنْبَل الْأَشْعَث بن سليم بن الْأسود الْمحَاربي ثِقَة"],[68,"وَقَالَ بن معِين أَشْعَث بن عبد الْملك الحمراني ثِقَة وَقَالَ بن الْمَدِينِيّ كلمت يحيى بن سعيد فِي الْأَشْعَث بن عبد الْملك فَقَالَ هُوَ عِنْدِي ثِقَة مَأْمُون"],[69,"وَسُئِلَ عُثْمَان بن أبي شيبَة عَن أَشْعَث بن سوار فَقَالَ ثِقَة صَدُوق قيل هُوَ حجَّة قَالَ أما حجَّة فَلَا وَقَالَ أَشْعَث بن سوار وَأَشْعَث بن عبد الْملك ثقتان"],[70,"وَقَالَ أَحْمد بن حَنْبَل أَشْعَث بن جَابر الْحدانِي مَا أعلم إِلَّا خيرا وَقَالَ بن معِين أَشْعَث بن جَابر الْحدانِي بَصرِي ثِقَة"],[71,"وَأَشْعَث بن أسلم الْعجلِيّ ثِقَة يروي عَنهُ سعيد بن أبي عرُوبَة"],[72,"والأشعث بن أسلم بَصرِي ثِقَة"],[73,"وَأَشْعَث بن دِرْهَم ثِقَة"],[74,"وَأَشْعَث بن عبد الرَّحْمَن الْخُرَاسَانِي ثِقَة"],[75,"وَأَشْعَث بن إِسْحَاق القمي ثِقَة روى عَنهُ يحيى بن يمَان وَغَيره وَقَالَ فِيهِ أَحْمد بن حَنْبَل صَالح روى عَنهُ جرير بن عبد الحميد"],[76,"وَقَالَ يحيى بن معِين أَشْعَث بن طلق النَّهْدِيّ ثِقَة"],[77,"قَالَ بن معِين إِسْرَائِيل ثِقَة وَقَالَ عبد الرَّحْمَن بن مهْدي قلت لِسُفْيَان الثَّوْريّ أكتب عَن إِسْرَائِيل قَالَ نعم اكْتُبْ عَنهُ فَإِنَّهُ صَدُوق أَحمَق حَدثنَا بذلك عُثْمَان بن جَعْفَر حَدثنَا مُحَمَّد بن مهْرَان أخبرنَا مُحَمَّد بن عبد الرَّحْمَن الصَّيْرَفِي قَالَ قَالَ عبد الرَّحْمَن بن مهْدي وَذكره"],[78,"قَالَ بن أبي خَيْثَمَة سُئِلَ يحيى بن معِين عَن أصبغ بن زيد فَقَالَ ثِقَة وَفِي رِوَايَة إِسْحَاق عَن يحيى أَن أصبغ بن زيد الْجُهَنِيّ ثِقَة كنت أرى أَن اصبغ بن زيد ضَعِيف فَقَالَ هُوَ ثِقَة"],[79,"روى عَبَّاس بن مُحَمَّد قَالَ سَمِعت يحيى يَقُول أُسَامَة بن زيد اللَّيْثِيّ هُوَ الَّذِي روى عَنهُ جَعْفَر بن عون وَأَبُو نعيم وَهُوَ ثِقَة وَقَالَ مرّة فِي رِوَايَة أُخْرَى صَالح"],[80,"نَا عبد الله بن سُلَيْمَان ثَنَا عبد الله بن أَحْمد بن حَنْبَل قَالَ سُئِلَ أبي عَن أبان بن تغلب فَقَالَ أبان ثِقَة كَانَ شُعْبَة يحدث عَنهُ قيل لَهُ أبان وَإِدْرِيس الأودي فَقَالَ أبان أكبر"],[81,"وَقَالَ يحيى بن معِين فِي رِوَايَة عَبَّاس زيد بن الْهَيْثَم عَنهُ أبان بن صمعة ثِقَة"],[82,"حَدثنَا عبد الله بن سُلَيْمَان انا عبد الله بن أَحْمد سَمِعت أبي يَقُول أبان بن أبي حَازِم هُوَ أبان بن عبد الله البَجلِيّ صَالح الحَدِيث"],[83,"قَالَ وَسمعت أبي يَقُول أبان الْعَطَّار أثبت من عمرَان الْقطَّان"],[84,"وَفِي رِوَايَة عَبَّاس قَالَ سَمِعت يحيى يَقُول أبان السراج لَيْسَ بِهِ بَأْس وَهُوَ سهل بن أبي الصَّلْت"],[85,"حَدثنَا عبد الله بن سُلَيْمَان نَا عبد الله بن أَحْمد بن حَنْبَل قَالَ وَقلت ليحيى شيخ حدث عَنهُ مُعْتَمر يُقَال لَهُ أبان الصريمي أَبُو مسعر فَقَالَ لَيْسَ بِهِ بَأْس خَاصم إِلَى عبد الْملك بن يعلى وَفِي رِوَايَة إِسْحَاق الكوسج عَن يحيى بن معِين قَالَ أبان الصريمي ثِقَة من أُسَمِّهِ إِيَاس"],[86,"حَدثنَا عبد الله بن سُلَيْمَان ثَنَا عبد الله بن أَحْمد قَالَ سَمِعت أبي يَقُول إِيَاس بن دَغْفَل شيخ ثِقَة"],[87,"وَإيَاس بن أبي تَمِيمَة شيخ ثِقَة البصريون يروون عَنهُ وَقَالَ بن معِين هُوَ صَالح"],[88,"وَإيَاس بن بيهس الْبَاهِلِيّ ثِقَة"],[89,"حَدثنَا عبد الله بن سُلَيْمَان ثَنَا عبد الله بن أَحْمد قَالَ قَالَ أبي الْأَخْضَر بن عجلَان مَا أرى بَأْسا وَفِي رِوَايَة الْعَبَّاس عَن يحيى أَخْضَر بن عجلَان لَيْسَ بِهِ بَأْس وَفِي رِوَايَة إِسْحَاق عَنهُ صَالح"],[90,"حَدثنَا مُحَمَّد بن مُحَمَّد بن سُلَيْمَان الباغندي نَا مُحَمَّد بن عُثْمَان بن أبي صَفْوَان ثَنَا بهز بن أَسد قَالَ كَانَ حَمَّاد بن زيد يَأْمُرنَا بِالْكتاب عَن أَزْهَر نَا عبد الله بن سُلَيْمَان نَا عبد الله بن أَحْمد قَالَ سَأَلت أبي عَن أَزْهَر بن الْقَاسِم فَقَالَ بَصرِي سكن مَكَّة وَكَانَ ثِقَة"],[91,"حَدثنَا عبد الله بن سُلَيْمَان نَا عبد الله بن أَحْمد قَالَ سَأَلت يحيى بن معِين عَن أسلم الْمنْقري بن من قَالَ لَا أَدْرِي هُوَ ثِقَة عندنَا"],[92,"قَالَ يحيى بن معِين فِي رِوَايَة عَبَّاس عَنهُ آدم بن عَليّ ثِقَة"],[93,"نَا مُحَمَّد بن مَحْمُود السراج أَنا مُحَمَّد بن سهل بن عَسْكَر قَالَ سَمِعت أَحْمد بن حَنْبَل يَقُول آدم بن أبي إِيَاس من السِّتَّة أَو السَّبْعَة الَّذين كَانُوا يضبطون الحَدِيث عِنْد شُعْبَة"],[94,"وَقَالَ يحيى فِي رِوَايَة إِسْحَاق عَنهُ آدم بن الحكم لَا بَأْس بِهِ"],[95,"قَالَ بن معِين فِي رِوَايَة الْعَبَّاس عَنهُ أَيمن بن نابل ثِقَة وَكَانَ لَا يفصح وَكَانَت فِيهِ لكنه"],[96,"أَحْمد بن يُونُس كَانَ ثِقَة لَيْسَ بِحجَّة قَالَه عُثْمَان بن أبي شيبَة"],[97,"أَحْمد بن جميل الْمروزِي قَالَ بن معِين فِي رِوَايَة عبد الله بن أَحْمد عَنهُ لَيْسَ بِهِ بَأْس قَالَ عبد الله وَرَأَيْت أبي يسمع مِنْهُ وَأَنا شَاهد مَعَه"],[98,"قَالَ عبد الله وَسَأَلت يحيى عَن أَحْمد بن إِبْرَاهِيم الْموصِلِي فَقَالَ لَيْسَ بِهِ بَأْس حدث عَن حَمَّاد بن زيد"],[99,"قَالَ بن معِين فِي رِوَايَة أَحْمد بن أبي خَيْثَمَة عَنهُ إِدْرِيس بن يزِيد الأودي ثِقَة"],[100,"قَالَ يحيى فِي رِوَايَة الْعَبَّاس بن مُحَمَّد عَنهُ أَسْبَاط بن نصر ثِقَة"],[101,"أَسْبَاط بن مُحَمَّد قَالَ فِيهِ بن أبي شيبَة أَرْجُو أَن يكون صَدُوقًا"],[102,"قَالَ بن معِين فِي رِوَايَة الْعَبَّاس عَنهُ أَبُو ضَمرَة أنس بن عِيَاض ثِقَة قَالَ بن شاهين حَدثنَا عَليّ بن مُحَمَّد الْمصْرِيّ ثَنَا عمر بن عبد الْعَزِيز بن مِقْلَاص ثَنَا يُوسُف بن عدي حَدثنِي إِسْمَاعِيل بن رشيد قَالَ كُنَّا عِنْد مَالك فِي الْمَسْجِد مَسْجِد الْمَدِينَة فَأقبل أنس بن عِيَاض أَبُو ضَمرَة فَأقبل مَالك يثني عَلَيْهِ وَيَقُول فِيهِ الْخَيْر وَأَنه وَأَنه وَقد سمع وَكتب"],[103,"أسيد بن عبد الرَّحْمَن الْخَثْعَمِي قَالَ فِيهِ أَحْمد بن صَالح فِي رِوَايَة بن رشدين عَنهُ أسيد من وُجُوه أهل خثعم من أهل الرملة من ثِقَات أهل الشَّام"],[104,"أَسد بن عَمْرو القَاضِي ثِقَة قَالَه يحيى فِي رِوَايَة عَبَّاس عَنهُ وَقَالَ أَحْمد فِي رِوَايَة ابْنه عبد الله عَنهُ كَانَ صَدُوقًا"],[105,"أحوص بن جَوَاب قَالَ يحيى فِي رِوَايَة عَبَّاس عَنهُ أَبُو جَوَاب ثِقَة وَهُوَ أحوص بن جَوَاب"],[106,"أَزْرَق بن قيس ثِقَة قَالَه بن معِين فِي رِوَايَة عَبَّاس عَنهُ"],[107,"أُمِّي بن ربيعَة الصَّيْرَفِي وثقة أَحْمد وَيحيى"],[108,"وَقَالَ يحيى فِي رِوَايَة إِسْحَاق عَنهُ أُميَّة شبْل ثِقَة"],[109,"وأشرس بن عبيد بن صُهَيْب صَالح وَقَالَ فِي رِوَايَة عَبَّاس عَنهُ أَشْرَس مولى سعيد بن الْعَاصِ ثِقَة يروي عَنهُ أَبُو نعيم"],[110,"وأنيس بن أبي يحيى ثِقَة"],[111,"وَقَالَ أَحْمد فِي أَفْلح بن حميد صَالح"],[112,"وأدهم بن طريف ثِقَة ثِقَة"],[113,"قَالَ بن معِين فِي رِوَايَة بن أبي خَيْثَمَة عَنهُ الْبَراء بن نَوْفَل أَبُو هنيدة بَصرِي ثِقَة"],[114,"وَقَالَ يحيى فِي رِوَايَة عَبَّاس عَنهُ الْبَراء بن يزِيد الْهَمدَانِي يحدث عَنهُ وَكِيع ثِقَة"],[115,"والبراء بن يزِيد الغنوي صَاحب أبي نَضرة ضَعِيف"],[116,"وَقَالَ فِي رِوَايَة عبد الله بن أَحْمد عَنهُ فِي الْبَراء بن سليم كُوفِي حَدثنَا عَنهُ وَكِيع مَا أرى بِهِ بَأْسا"],[117,"بديل بن مسيرَة قَالَ فِيهِ يحيى بَصرِي ثِقَة"],[118,"وَقَالَ بشير بن يسَار ثِقَة وَلَيْسَ هُوَ أَخُو سُلَيْمَان"],[119,"قَالَ أَحْمد وَقد سَأَلَهُ ابْنه عبد الله عَن أبي عقيل الدَّوْرَقِي فَقَالَ اسْمه بشير إِن عقبَة ثِقَة وَقَالَ يحيى أَبُو عقيل الدَّوْرَقِي ثِقَة"],[120,"بشير بن كثير أَبُو طَلْحَة الْأَسدي قَالَ أَحْمد هَذَا ثِقَة ثِقَة"],[121,"وَقَالَ فِي بشير بن طَلْحَة لَيْسَ بِهِ بَأْس حدث عَنهُ ضَمرَة"],[122,"وَقَالَ يحيى بشير بن سلمَان ثِقَة"],[123,"وَبشر بن الْمفضل وَابْن علية وَيزِيد بن زُرَيْع وَعبد الْوَهَّاب ثِقَات"],[124,"باذام قَالَ يحيى لم أجد من النَّاس يَقُول فِيهِ شَيْئا وَلم يتْركهُ شُعْبَة وَلَا زَائِدَة وَلَا عبد الله بن عُثْمَان وَاخْتلف فِي اسْمه فَقَالَ أَحْمد بن حَنْبَل باذام وَهُوَ مولى أم هاني رضي الله عنها وَأما وَكِيع وَأَبُو نعيم فَقَالَ أَحدهمَا باذام وَقَالَ الآخر باذان وَهُوَ مولى أم هَانِئ رضي الله عنها"],[125,"بكر بن مُضر ثِقَة قَالَ أَحْمد فِي رِوَايَة ابْنه عبد الله عَنهُ قَالَ ثِقَة لَيْسَ بِهِ بَأْس"],[126,"بكير بن عَامر قَالَ أَحْمد صَالح الحَدِيث لَيْسَ بِهِ بَأْس"],[127,"بكير بن ربيعَة ثِقَة"],[128,"بكير بن الأشجع قَالَ أَحْمد بن صَالح روى عَن سعيد بن نَافِع وَإِذا روى بكير عَن رجل فَلَا تسْأَل عَنهُ وَقَالَ بن معِين بكير بن عبد الله الْأَشَج ثِقَة"],[129,"بكار بن عبد الله عَن وهب ثِقَة قَالَه أَبُو عبد الله أَحْمد بن حَنْبَل وَيحيى بن معِين"],[130,"قَالَ بن معِين أَبُو عُبَيْدَة النَّاجِي صَاحب الْحسن الَّذِي يروي المواعظ اسْمه بكر بن أبي الْأسود لَيْسَ بِهِ بَأْس"],[131,"بكر ربن عَمْرو أَبُو الصّديق النَّاجِي ثِقَة"],[132,"وَبكر الْأَعْنَق لَيْسَ بِهِ بَأْس"],[133,"بكر بن حبيب ثِقَة قَالَه يحيى بن معِين"],[134,"بدر بن خَلِيل يروي عَنهُ أَبُو أُسَامَة وَهُوَ صَالح الحَدِيث قَالَه يحيى وَفِي رِوَايَة أُخْرَى عَنهُ بدر بن الْخَلِيل ثِقَة روى عَنهُ شريك"],[135,"بسام الصَّيْرَفِي قَالَ يحيى ثِقَة لَا أَدْرِي بن من هُوَ"],[136,"بهز بن حَكِيم ثِقَة"],[137,"وَقَالَ أَحْمد فِي برد بن سِنَان صَالح الحَدِيث"],[138,"وَسُئِلَ أَحْمد بن حَنْبَل عَن إِسْمَاعِيل بن عَيَّاش وَبَقِيَّة فَقَالَ كَانَ إِسْمَاعِيل صَاحب حَدِيث وَكَانَ بَقِيَّة وَكَانَ وَكَانَ وفخم أمره وَكَانَ بَقِيَّة أذكاهما أَي كَأَنَّهُ يَشْتَهِي الحَدِيث وَقَالَ عبد الله بن الْمُبَارك بَقِيَّة بن الْوَلِيد صَدُوق اللِّسَان وَلكنه يَأْخُذ عَمَّن أقبل وَأدبر"],[139,"بهز بن أَسد ثِقَة بَصرِي قَالَه يحيى"],[140,"بسطَام بن مُسلم لَيْسَ بِهِ بَأْس صَالح الحَدِيث قَالَه أَحْمد"],[141,"وَقَالَ يحيى فِي رِوَايَة إِسْحَاق عَنهُ بكير بن أبي السميط صَالح"],[142,"قَالَ يحيى بن معِين تَمام بن نجيح ثِقَة"],[143,"حَدثنَا الْحسن بن أَحْمد بن بسطَام نَا مُحَمَّد بن مُوسَى الجرسي ثَنَا أَحْمد بن زيد قَالَ ثَنَا أبي عَن أنس بن مَالك قَالَ إِن للخير مَفَاتِيح وَإِن ثَابت بن أسلم من مَفَاتِيح الْخَيْر وَقَالَ يحيى بن معِين ثَابت الْبنانِيّ بَصرِي ثِقَة وَكَذَا قَالَ أَحْمد ثَابت بن أسلم الْبنانِيّ ثِقَة"],[144,"وَقَالَ يحيى بن سعيد فِي رِوَايَة عَليّ بن الْمَدِينِيّ عَنهُ وَقد سُئِلَ عَن ثَابت بن عمَارَة فَقَالَ عبد الْمُؤمن وَعبد ربه أقوى مِنْهُ ثَابت بن عمَارَة الْحَنَفِيّ ثِقَة قَالَه يحيى فِي رِوَايَة الْعَبَّاس عَنهُ"],[145,"وَقَالَ أَحْمد وَقد سَأَلَهُ عبد الله أبنه عَن ثَابت بن عبيد الْأنْصَارِيّ فَقَالَ هَذَا رجل ثِقَة يسئل عَنهُ حدث عَنهُ الْأَعْمَش ومسعر"],[146,"قَالَ وَسَأَلته عَن ثَابت بن يزِيد بن أبي زيد فَقَالَ شُعْبَة دلهم عَلَيْهِ وَهُوَ ثِقَة"],[147,"قَالَ وَسَأَلته عَن ثَابت الْحداد فَقَالَ بن هُرْمُز وَيُقَال ثَابت بن هُرْمُز روى عَنهُ الحكم ثِقَة"],[148,"قَالَ وَسَأَلته عَن ثَابت بن ثَوْبَان فَقَالَ هَذَا شَامي وَلَيْسَ بِهِ بَأْس"],[149,"قَالَ وَسَأَلته عَن ثَابت بن ذرْوَة فَقلت هُوَ ثِقَة فَقَالَ حدث عَنهُ حَمَّاد بن زيد وَقَالَ يحيى فِي رِوَايَة إِسْحَاق بن مَنْصُور عَنهُ ثَابت بن ذرْوَة ثِقَة"],[150,"ثَوْر بن زيد الديلِي ثِقَة قَالَه يحيى الْقطَّان فِي رِوَايَة عَليّ بن الْمَدِينِيّ عَنهُ وَقَالَ أَحْمد بن صَالح وَذكر ثَوْر بن زيد الديلِي فَقَالَ لَهُ شَأْن روى عَنهُ مَالك وَسليمَان بن بِلَال وَأهل الْمَدِينَة"],[151,"ثَوَاب بن عتبَة ثِقَة قَالَه يحيى"],[152,"ثُمَامَة بن عبد الله بن أنس ثِقَة قَالَه أَحْمد"],[153,"ثَوْر بن يزِيد الكلَاعِي ثِقَة"],[154,"وَقَالَ يحيى ثَعْلَبَة قمي حدث عَنهُ إِسْحَاق الرَّازِيّ وَأَبُو مُعَاوِيَة وَجَرِير"],[155,"جبلة بن سحيم ثِقَة قَالَه يحيى الْقطَّان وَابْن معِين وَقد وَثَّقَهُ شُعْبَة وسُفْيَان"],[156,"جبلة بن عَطِيَّة ثِقَة قَالَه بن معِين"],[157,"جَعْفَر بن مُحَمَّد الصَّادِق ثِقَة مَأْمُون قَالَه يحيى وَسُئِلَ عُثْمَان بن أبي شيبَة عَنهُ فَقَالَ مثل جَعْفَر يسْأَل عَنهُ هُوَ ثِقَة إِذا روى عَنهُ الثِّقَات"],[158,"وَقَالَ يحيى فِي رِوَايَة عَنهُ كَانَ جَعْفَر بن برْقَان أُمِّيا لَا يقْرَأ وَلَا يكْتب وَكَانَ رجل صدق وَقَالَ أَحْمد فِي جَعْفَر بن برْقَان إِذا حدث عَن غير الزُّهْرِيّ فَلَا بَأْس بِهِ ثمَّ قَالَ يُخطئ فِي حَدِيثه عَن الزُّهْرِيّ"],[159,"وَقَالَ أَحْمد أَبُو بشر جَعْفَر بن أبي وحشية وَهُوَ جَعْفَر بن إِيَاس"],[160,"وَقَالَ جَعْفَر بن ربيعَة ثِقَة"],[161,"جَعْفَر الْأَحْمَر صَالح الحَدِيث"],[162,"وَقَالَ يحيى جَعْفَر بن مَيْمُون صَالح قَالَ أَحْمد حدث عَنهُ يحيى وَالثَّوْري وَأَبُو عُبَيْدَة الْحداد أخْشَى أَن يكون ضَعِيف الحَدِيث"],[163,"وَقَالَ بن أبي شيبَة جَعْفَر بن زِيَاد الْأَحْمَر ثِقَة صَدُوق"],[164,"جَعْفَر بن خَالِد بن سارة المَخْزُومِي قَالَ أَحْمد أرَاهُ مديني حدث عَنهُ بن جريج مكي قَالَ وَحدثنَا عَنهُ بن عُيَيْنَة ثِقَة وثقة بن معِين أَيْضا"],[165,"جَعْفَر بن سُلَيْمَان الضبعِي ثِقَة يتشيع لَيْسَ بِهِ بَأْس قَالَه يحيى بن معِين وَقَالَ كَانَ يحيى بن سعيد لَا يكْتب عَنهُ"],[166,"جَعْفَر بن أبي الْمُغيرَة القمي ثِقَة قَالَه أَحْمد"],[167,"أَبُو الشهب جَعْفَر بن حَيَّان من الثِّقَات قَالَه أَحْمد"],[168,"جَعْفَر بن عون لَيْسَ بِهِ بَأْس كَانَ رجلا صَالحا"],[169,"حَدثنَا عبد الله بن مُحَمَّد قَالَ ثَنَا مَحْمُود بن غيلَان قَالَ سَمِعت أَبَا دَاوُد الطَّيَالِسِيّ قَالَ ثَنَا عبد الرَّحْمَن بن مهْدي قَالَ سَمِعت سُفْيَان يَقُول مَا رَأَيْت أحدا قطّ أورع فِي الحَدِيث من جَابر يَعْنِي الْجعْفِيّ وَفِي رِوَايَة أُخْرَى من جَابر وَلَا مَنْصُور"],[170,"أَبُو الشعْثَاء جَابر بن زيد روى عَنهُ قَتَادَة وَهُوَ ثِقَة قَالَه يحيى بن معِين فِي رِوَايَة عَبَّاس عَنهُ"],[171,"جرير بن حَازِم كَانَ يحيى بن سعيد الْقطَّان يَقُول هُوَ ثِقَة وَكَانَ يرضاه وَسُئِلَ أَحْمد عَن جرير بن حَازِم وَأبي الْأَشْهب أَيهمَا أحب إِلَيْك فَقَالَ جرير زينته خِصَال كَانَ صَاحب سنة عِنْد جرير من الحَدِيث أَمر عَظِيم"],[172,"جرير بن عبد الحميد صَدُوق ثِقَة قَالَه يحيى بن معِين"],[173,"جَامع بن أبي رَاشد شيخ ثِقَة قَالَه أَحْمد"],[174,"جَامع بن مطر الحبطي لَيْسَ بِهِ بَأْس قَالَه أَحْمد جَامع بن مطر ثِقَة قَالَه بن معِين"],[175,"جميل بن مرّة بَصرِي قَالَ أَحْمد مَا أعلم إِلَّا خيرا"],[176,"وَأَبُو الوداك جبر بن نوف ثِقَة قَالَه يحيى"],[177,"جبر بن حبيب ثِقَة قَالَه يحيى"],[178,"الْجراح بن مليح بن فرس أَبُو وَكِيع ثِقَة قَالَه بن معِين"],[179,"الْجراح بن مليح الشَّامي لَيْسَ بِهِ بَأْس قَالَه يحيى"],[180,"جهير بن يزِيد ثِقَة وَقَالَ يحيى الْقطَّان لَيْسَ بِهِ بَأْس"],[181,"جِبْرِيل بن أَحْمَر ثِقَة كُوفِي قَالَه يحيى"],[182,"جُنَيْد بن أبي دهرة ثِقَة يروي عَنهُ أَبُو أُسَامَة قَالَه بن معِين فِي رِوَايَة الْعَبَّاس عَنهُ"],[183,"جرثومة مولى بِلَال بن أبي بردة ثِقَة قَالَه يحيى"],[184,"جوَيْرِية بن أَسمَاء لَيْسَ بِهِ بَأْس قَالَه يحيى"],[185,"جوَيْرِية بن بشير قَالَ يحيى بن معِين صَالح"],[186,"الجعيد بن عبد الرَّحْمَن صَالح ثِقَة قَالَه يحيى"],[187,"الْحسن العرني لَيْسَ بِهِ بَأْس وَهُوَ صَدُوق وانما يُقَال انه لم يسمع من بن عَبَّاس"],[188,"وَالْحسن بن ذكْوَان بَصرِي ثِقَة لَيْسَ بَينه وَبَين الْحُسَيْن بن ذكْوَان قرَابَة"],[189,"وَالْحسن بن الحكم كُوفِي ثِقَة"],[190,"وَالْحسن بن مُسلم مكي ثِقَة"],[191,"وَحسن بن ثَابت ثِقَة كُوفِي يحدث عَن الْأَعْمَش وَغَيره قَالَ كُله بن معِين"],[192,"الْحسن بن عبد الرَّحْمَن الْكَاتِب روى عَنهُ وَكِيع وَقد كَانَ ثِقَة"],[193,"حسن بن صَالح ثِقَة لَيْسَ بِهِ باس قَالَه يحيى"],[194,"الْحسن بن الحكم كُوفِي ثِقَة قَالَه يحيى قَالَ أَحْمد فِي الْحسن بن الحكم وَهُوَ النَّخعِيّ ثِقَة"],[195,"حسن بن حُسَيْن صَاحب بن عون صَالح حسن الْهَيْئَة قَالَه أَحْمد"],[196,"وَقَالَ يحيى أَبُو كيران اسْمه الْحسن بن عقبَة الْمرَادِي ثِقَة"],[197,"وَالْحسن بن عَيَّاش أَخُو أبي بكر بن عَيَّاش ثِقَة"],[198,"قَالَ يحيى أَبُو يُونُس الْقوي اسْمه الْحسن بن يزِيد كُوفِي ثِقَة وَلَيْسَ هُوَ الْحسن الَّذِي يروي عَن الشّعبِيّ ان مَسْجِد الْكُوفَة تِسْعَة أجربة وأقفزة ذَاك الْحسن بن يزِيد"],[199,"وَقَالَ أَحْمد فِي الْحسن بن يزِيد الْأَصَم الَّذِي يحدث عَن السّديّ عَن أَوْس بن ضمعج ثِقَة لَيْسَ بِهِ بَأْس إِلَّا انه حدث عَن السّديّ عَن أَوْس بن ضمعج وَقَالَ يحيى هُوَ ثِقَة"],[200,"الْحسن بن سوار لَيْسَ بِهِ بَأْس قَالَه يحيى"],[201,"وَقَالَ عُثْمَان بن أبي شيبَة الْحسن بن الرّبيع صَدُوق وَلَيْسَ بِحجَّة"],[202,"وَقَالَ يحيى الْحسن بن عَطِيَّة الْعَوْفِيّ لم يكن بِهِ بَأْس"],[203,"وَقَالَ أَحْمد الْحسن بن ندبة مَا كَانَ بِهِ بَأْس"],[204,"الْحسن بن حَيّ ثِقَة قَالَه بن معِين"],[205,"وَقَالَ الْحسن بن أبي بكر الْبَاهِلِيّ ثِقَة"],[206,"وَالْحسن بن عبيد ثِقَة"],[207,"وَالْحسن بن أبي الْحَسْنَاء ثِقَة"],[208,"وَالْحسن بن حَكِيم أَبُو حَكِيم ثِقَة"],[209,"وَالْحسن بن عَليّ الهزاني ثِقَة"],[210,"الْحُسَيْن بن ذكْوَان هُوَ الْمعلم ثِقَة"],[211,"الْحُسَيْن بن سَالم بن أبي الْجَعْد صَالح قَالَه يحيى"],[212,"الْحُسَيْن بن وَاقد ثِقَة قَالَه يحيى"],[213,"حُسَيْن بن عَليّ ثِقَة صَدُوق قَالَه عُثْمَان بن أبي شيبَة"],[214,"الحكم بن أبان الْعَدنِي ثِقَة قَالَه أَحْمد وَيحيى"],[215,"وَقَالَ أَبُو بكار الحكم بن فروخ صَالح الحَدِيث قَالَه أَحْمد"],[216,"وَقَالَ يحيى الحكم بن خزرج ثِقَة"],[217,"الحكم بن فُضَيْل ثِقَة قَالَه يحيى"],[218,"الحكم بن هِشَام كُوفِي يحدث عَن عبد الْملك بن عُمَيْر وَهُوَ ثِقَة قَالَه بن معِين"],[219,"الحكم بن عَطِيَّة بَصرِي ثِقَة يحدث عَن ثَابت"],[220,"وَقَالَ الحكم بن مُوسَى لَيْسَ بِهِ بَأْس"],[221,"الحكم بن ظهير صَدُوق وَلَيْسَ مِمَّن يحْتَج بِهِ قَالَه عُثْمَان بن أبي شيبَة"],[222,"حَنْظَلَة الجُمَحِي ثِقَة قَالَه بن معِين وَأحمد وَكَانَ وَكِيع يَقُول ثِقَة أَخُوهُ عَمْرو بن أبي سُفْيَان روى عَنهُ الثَّوْريّ وَابْن الْمُبَارك"],[223,"حَنْظَلَة بن عبد الرَّحْمَن يروي عَنهُ مُحَمَّد بن فُضَيْل كُوفِي لم يكن بِهِ بَأْس"],[224,"نَا يحيى بن مُحَمَّد بن صاعد قَالَ نَا إِسْحَاق بن إِبْرَاهِيم بن حبيب بن الشَّهِيد قَالَ حَدثنِي أبي قَالَ لقِيت شُعْبَة فِي الطَّرِيق فَقَالَ مَا كَانَ أَبوك باقلهم حَدِيثا وَلكنه كَانَ شَدِيد الاتقاء وَقَالَ أَحْمد بن حَنْبَل فِي رِوَايَة ابْنه عبد الله عَنهُ حبيب بن الشَّهِيد ثِقَة"],[225,"حبيب بن أبي ثَابت كُوفِي ثِقَة قَالَه يحيى"],[226,"وَقَالَ حبيب بن الْمعلم الْبَصْرِيّ ثِقَة وَقَالَ أَحْمد ثِقَة مَا أصح حَدِيثه"],[227,"قَالَ أَحْمد حبيب بن شهَاب لَيْسَ بِهِ بَأْس"],[228,"قَالَ وحبِيب بن الزبير مَا أعلم بِهِ بَأْسا"],[229,"وحبِيب بن أبي مَرْزُوق مَا أرى بِهِ بَأْسا"],[230,"قَالَ يحيى حبيب بن أبي الْعَالِيَة ثِقَة"],[231,"وحبِيب بن أبي عمْرَة ثِقَة كُوفِي"],[232,"وحبِيب بن شهَاب بن مُدْلِج ثِقَة"],[233,"وحبِيب بن أبي حبيب الْأنمَاطِي صَالح بِالتَّصْغِيرِ"],[234,"حبيب بن حجر الْعَبْسِي لَيْسَ بِهِ بَأْس قَالَه يحيى"],[235,"حبيب أَخُو حَمْزَة الزيات ثِقَة قَالَه عُثْمَان بن أبي شيبَة"],[236,"حُصَيْن بن عبد الرَّحْمَن الثِّقَة الْمَأْمُون من كبار أَصْحَاب الحَدِيث وَهُوَ أَبُو الْهُذيْل السمي قَالَه أَحْمد وَيحيى"],[237,"وحصين بن نَافِع لَيْسَ بِهِ بَأْس"],[238,"وَأَبُو مُحصن حُصَيْن بن نمير لَيْسَ بِهِ بَأْس قَالَه يحيى"],[239,"حَمَّاد بن أبي سُلَيْمَان ثِقَة"],[240,"وَحَمَّاد بن يحيى الْأَبَح لَيْسَ بِهِ بَأْس ثِقَة قَالَه يحيى"],[241,"حَمَّاد بن نجيح ثِقَة مقارب الحَدِيث روى عَنهُ وَكِيع وَأَبُو عُبَيْدَة الْحداد قَالَه أَحْمد حَمَّاد بن نجيح ثِقَة قَالَه يحيى"],[242,"حَمَّاد بن أبي الدَّرْدَاء ثِقَة قَالَه أَحْمد"],[243,"حَمَّاد بن جَعْفَر بَصرِي ثِقَة قَالَه يحيى"],[244,"وَقَالَ حَمَّاد بن دَلِيل لَيْسَ بِهِ بَأْس ثِقَة وكنيته أَبُو زيد ولي قَضَاء الْمَدَائِن قَالَ بن عمار الْموصِلِي حَمَّاد بن دَلِيل كَانَ قَاضِيا على الْمَدَائِن فهرب مِنْهَا وَكَانَ من ثِقَات النَّاس ثمَّ رَأَيْته بِمَكَّة يَبِيع الْبر"],[245,"وَقَالَ أَحْمد فِي رِوَايَة عبد الله عَنهُ حَمَّاد بن يُونُس إِنْسَان كيس كُوفِي"],[246,"نَا عبد الله بن مُحَمَّد نَا إِسْحَاق بن إِبْرَاهِيم نَا مُؤَمل قَالَ سَمِعت شُعْبَة يَقُول من أَرَادَ أَيُّوب فَعَلَيهِ بحماد بن زيد"],[247,"حَمَّاد بن مسْعدَة ثِقَة ثِقَة لَا باس بِهِ"],[248,"حَمَّاد بن الْخياط ثِقَة هُوَ مديني قَالَه يحيى"],[249,"نَا عُثْمَان بن أَحْمد نَا حَنْبَل بن إِسْحَاق نَا أَبُو سَلمَة نَا حَمَّاد بن زيد قَالَ قدم علينا جرير بن حَازِم من الْمَدِينَة فأتيناه فتحدثنا عِنْده فَقَالَ جرير ثَنَا قيس بن سعد عَن حجاج بن أَرْطَاة قَالَ فلبثنا مَا شَاءَ الله ثمَّ قدم علينا حجاج بن ثَلَاثِينَ أَو إِحْدَى وَثَلَاثِينَ سنة فَرَأَيْت عَلَيْهِ من الزحام شَيْء لم أره على حَمَّاد بن أبي سُلَيْمَان وَرَأَيْت مطر الْوراق وَدَاوُد بن أبي هِنْد وَيُونُس بن عبيد جثاه على ركبهمْ يَقُولُونَ يَا أَبَا أَرْطَاة مَا تَقول فِي كَذَا مَا تَقول فِي كَذَا قَالَ يحيى الْحجَّاج بن أَرْطَاة كُوفِي لَيْسَ بِالْقَوِيّ"],[250,"حجاج بن دِينَار واسطي قَالَه يحيى وَقَالَ أَحْمد لَيْسَ بِهِ بَأْس وَقَالَ عَبدة بن سُلَيْمَان كَانَ ثبتا وَقَالَ بن عمار هُوَ ثِقَة"],[251,"حجاج بن أبي زَيْنَب قَالَ يحيى هُوَ واسطي ثِقَة وَقَالَ ان أبي خَيْثَمَة لَيْسَ بِهِ بَأْس"],[252,"حجاج الصَّواف بَصرِي ثِقَة"],[253,"وحجاج بن الْأسود بَصرِي ثِقَة قَالَه يحيى"],[254,"حجاج الْأسود الْقَسْمَلِي رجل صَالح حدث عَنهُ حَمَّاد بن سَلمَة قَالَ أَحْمد مَا أرى بِهِ بَأْسا"],[255,"حجاج بن فرافصة بَصرِي لَا بَأْس بِهِ قد روى عَن بن سِيرِين قَالَه يحيى فِي رِوَايَة عَبَّاس عَنهُ وَقَالَ فِي رِوَايَة عبد الله بن أَحْمد عَنهُ حجاج بن فرافصة رجل زاهد لَيْسَ بِهِ بَأْس حدث عَنهُ الثَّوْريّ وَمعمر"],[256,"حجاج بن أبي عُثْمَان شيخ ثِقَة قَالَه أَحْمد وَهُوَ بَصرِي"],[257,"قَالَ وحجاج بن حسان الْقَيْسِي لَيْسَ بِهِ بَأْس وَفِي رِوَايَة أُخْرَى عَنهُ شيخ ثِقَة"],[258,"وحجاج الْأَحول لَيْسَ بِهِ بَأْس روى عَنهُ سعيد بن أبي عرُوبَة عَن قَتَادَة عَن أنس من نسي صَلَاة"],[259,"وحجاج بن منهال مَا أرى بِهِ بَأْسا كَانَ صَاحب سنة رَفعه الله بِالْخَيرِ"],[260,"حجاج الْأَحول روى عَنهُ بن أبي عرُوبَة لَيْسَ بِهِ بَأْس ثِقَة قَالَه يحيى وَقَالَ حَدثنَا إِسْمَاعِيل عَنهُ وَقَالَ لَا أعلم بن من هُوَ"],[261,"حجاج بن الْأسود ثِقَة حدث عَنهُ حَمَّاد بن سَلمَة وَزعم روح أَنه سمع مِنْهُ قَالَه يحيى وَهُوَ بَصرِي ثِقَة وَقَالَ أَحْمد أَيْضا هُوَ ثِقَة"],[262,"حجاج الفسطاطي لَيْسَ بِهِ بَأْس قَالَه يحيى"],[263,"وَقَالَ عَليّ بن الْمَدِينِيّ الْحجَّاج بن دِينَار ثِقَة"],[264,"حجاج بن أبي عُيَيْنَة صَالح قَالَه يحيى"],[265,"حَوْشَب بن عقيل الْعَبْدي يكني أَبَا دحْيَة ثِقَة وثقة أَحْمد وَيحيى"],[266,"حميد بن زِيَاد أَبُو صَخْر لَيْسَ بِهِ بَأْس قَالَه أَحْمد"],[267,"وَقَالَ يحيى بن معِين حميد الْأَعْرَج ثِقَة وَهُوَ أَخُو سندل وسندل كَذَّاب واسْمه عمر بن قيس"],[268,"وَقَالَ بن نمير كَانَ حميد بن سلمَان ثِقَة"],[269,"أَبُو الْأسود حميد بن الْأسود حدث عَنهُ عبيد الله بن عمر وَكَانَ صَدُوقًا ذكره بن أبي خَيْثَمَة عَن عبيد الله"],[270,"حميد بن قيس الْمَكِّيّ الْأَعْرَج ثِقَة قَالَه يحيى"],[271,"حميد بن يَعْقُوب بن يسَار روى عَنهُ أَبُو إِسْحَاق وَكَانَ ثِقَة"],[272,"حميد بن أبي حميد الْمصْرِيّ عَن سيف ثِقَة"],[273,"حميد بن هِلَال ثِقَة قَالَه فيهمَا يحيى"],[274,"أَو هَانِئ الْمصْرِيّ حميد بن هاني أكبر شيخ لِابْنِ وهب رفع بِهِ أَحْمد بن صَالح"],[275,"حَمْزَة الزيات ثِقَة"],[276,"وَحَمْزَة بن سَلمَة أَبُو أَيُّوب صَالح قَالَه فيهمَا يحيى"],[277,"الْحَارِث بن يزِيد الَّذِي روى عَنهُ بن لهيعه روى عَنهُ يحيى بن سعيد الْأنْصَارِيّ قَالَ فِيهِ أَحْمد بن حَنْبَل شيخ ثِقَة من الثِّقَات"],[278,"وَقَالَ يحيى بن معِين الْحَارِث بن مرّة الْحَنَفِيّ ثِقَة وَقد سَمِعت مِنْهُ"],[279,"والحرث بن عبيد الْبَصْرِيّ أَبُو قدامَة ضَعِيف قَالَه يحيى وَقَالَ مرّة أُخْرَى الْحَارِث بن عبيد ثِقَة"],[280,"قَالَ والْحَارث بن حصيرة لَا بَأْس بِهِ"],[281,"وَقَالَ أَحْمد بن صَالح الْحَارِث الْأَعْوَر ثِقَة مَا احفظه وَأحسن مَا روى عَن عَليّ واثنى عَلَيْهِ سمع عليا رضي الله عنه يَقُول من يَشْتَرِي علمي بدرهم فَذهب الْحَارِث فَاشْترى صحيفَة فجَاء بهَا إِلَى عَليّ فاملأ عَلَيْهِ قيل لِأَحْمَد بن صَالح فَقَوْل الشّعبِيّ حَدثنَا الْحَارِث وَكَانَ كذابا فَقَالَ لم يكن يكذب فِي الحَدِيث إِنَّمَا كَانَ كذبه فِي رَأْيه"],[282,"حَكِيم بن الديلم وَكَانَ مكفوفا وَكَانَ ثِقَة قَالَه أَحْمد"],[283,"حَكِيم بن نَافِع الرقي لَيْسَ بِهِ بَأْس قَالَه يحيى"],[284,"حكام بن سلم الرَّازِيّ ثِقَة"],[285,"وَقَالَ أَحْمد حَيْوَة بن شُرَيْح ثِقَة نَا أَحْمد بن عَمْرو بن جَابر بالرملة قَالَ سَمِعت مُحَمَّد بن عَوْف الْحِمصِي يَقُول أول مَا قدم علينا أَحْمد بن حَنْبَل مر بِنَا إِلَى حَيْوَة بن شُرَيْح الثِّقَة فَسمع مِنْهُ نُسْخَة بَقِيَّة عَن يحيى بن سعيد"],[286,"حَيَّان بياع الأنماط ثِقَة قَالَه يحيى"],[287,"قَالَ وحاجز بن عبد الله الْمحَاربي ثِقَة"],[288,"وحبان أَخُو منْدَل بن عَليّ الْعَنزي صَالح لَيْسَ بِذَاكَ الْقوي حَدِيثه هُوَ وَأَخُوهُ شَيْء وَاحِد"],[289,"حبوية أَبُو يزِيد الرَّازِيّ ثِقَة قَالَه عُثْمَان بن أبي شيبَة"],[290,"حَفْص بن سُلَيْمَان الْمنْقري ثِقَة قَالَه يحيى وَقَالَ احْمَد هُوَ صَالح"],[291,"حَفْص بن مسيرَة ثِقَة قَالَه يحيى وَقَالَ مرّة لَيْسَ بِهِ بَأْس وَيَقُولُونَ انه عرض على زيد بن أسلم"],[292,"قَالَ وَحَفْص بن النَّضر السّلمِيّ لَيْسَ بِهِ بَأْس"],[293,"وَقَالَ أَحْمد حمْرَان بن عبد الْعَزِيز شيخ ثِقَة"],[294,"حَرْب بن أبي الْعَالِيَة شيخ ثِقَة قَالَه عبيد الله بن عمر"],[295,"حَرْب بن مَيْمُون صَالح قَالَه يحيى"],[296,"وَقَالَ أَحْمد حَرْب بن سريح لَيْسَ بِهِ بَأْس وَقَالَ يحيى هُوَ ثِقَة"],[297,"حَاتِم بن وردان ثِقَة قَالَه يحيى فِي رِوَايَة عَبَّاس وَغَيره"],[298,"وَقَالَ أَحْمد فِي حَاتِم بن أبي صَغِيرَة ثِقَة ثِقَة"],[299,"حريز بن عُثْمَان وَهُوَ الرَّحبِي ثِقَة وثقة أَحْمد وَيحيى"],[300,"وَقَالَ يحيى حشرج بن نباتة كُوفِي ثِقَة"],[301,"حُرَيْث بن السَّائِب الْبَصْرِيّ يرْوى عَنهُ عبد الرَّحْمَن بن مهْدي ووكيع وَهُوَ ثِقَة قَالَه يحيى"],[302,"وَقَالَ الْحَرِيش بن الخريت أَخُو الزبير بن الخريت لَيْسَ بِهِ بَأْس"],[303,"وَقَالَ احْمَد حَرْمَلَة بن عمرَان التجِيبِي ثِقَة"],[304,"حنيف الْمُؤَذّن روى عَنهُ جرير شيخ صَالح قَالَه يحيى"],[305,"وَقَالَ أَحْمد حزم شيخ ثِقَة ثِقَة"],[306,"حطَّان بن حفاف أَبُو الجويرية الْجرْمِي كُوفِي ثِقَة روى عَنهُ بن عُيَيْنَة وَزُهَيْر قَالَه يحيى فِي رِوَايَة بن أبي خَيْثَمَة عَنهُ"],[307,"قَالَ والتيمي عَن الْحَضْرَمِيّ شيخ روى عَن مُعْتَمر عَن أَبِيه عَن الْحَضْرَمِيّ لَا بَأْس بِهِ قَالَه بن معِين فِي رِوَايَة عبد الله عَنهُ وَفِي رِوَايَة إِسْحَاق الكوشج ثِقَة"],[308,"نَا عبد الله بن مُحَمَّد الْبَغَوِيّ قَالَ حَدثنِي احْمَد بن سعد الزُّهْرِيّ قَالَ سُئِلَ أَحْمد بن حَنْبَل عَن حدير فَقَالَ لَيْسَ بِهِ بَأْس"],[309,"نَا مُحَمَّد بن أَحْمد بن الْحسن قَالَ حَدثنَا مُحَمَّد بن عُثْمَان بن أبي شيبَة قَالَ سَمِعت الْحسن بن سهل يَقُول سَمِعت حَفْص بن عمر يَقُول سَمِعت الْأَزْدِيّ يَقُول رَحْمَة الله على الْحر بن صياح فقد كنت أَلْقَاهُ شَبِيها بالمتهم مَعَ مَا هُوَ عَلَيْهِ من الْعَمَل وَالْعِبَادَة"],[310,"قَالَ شُعْبَة قَالَ خَالِد الْحذاء مَا كتبت حَدِيثا قطّ إِلَّا حَدِيثا طَويلا فَلَمَّا حفظته محوته قَالَ بن شاهين وَذكر أَحْمد بن عُمَيْر الدِّمَشْقِي وَمَات قبل دخولي الْبَلَد قَالَ نَا مُعَاوِيَة بن صَالح الْأَشْعَرِيّ قَالَ سَمِعت يحيى بن معِين يَقُول خَالِد الْحذاء بَصرِي ثِقَة نَا عبد الله بن مُحَمَّد الْبَغَوِيّ قَالَ نَا إِسْحَاق بن أبي إِسْرَائِيل قَالَ نَا إِسْحَاق بن شَوْذَب وَكَانَ خَالِد ثِقَة"],[311,"خَالِد بن أبي كَرِيمَة كُوفِي ثِقَة قَالَه أَحْمد وَيحيى"],[312,"خَالِد بن رَبَاح الْهُذلِيّ ثِقَة وَهُوَ بَصرِي يروي عَنهُ يزِيد بن هَارُون قَالَه بن معِين وَقَالَ يحيى الْقطَّان كَانَ خَالِد بن رَبَاح صَاحب عَرَبِيَّة وَكَانَ ثبتا فأفسدوه بِالْقدرِ"],[313,"خَالِد بن الْحَارِث قَالَ فِيهِ حَمَّاد بن زيد ذَاك الصدوق"],[314,"خَالِد بن يزِيد بن أبي مَالك ثِقَة صَادِق قَالَه عُثْمَان بن أبي شيبَة"],[315,"قَالَ وخَالِد بن مخلد ثِقَة صَدُوق"],[316,"وخَالِد بن قيس لَيْسَ بِهِ بَأْس قَالَه عَليّ بن الْمَدِينِيّ"],[317,"وخَالِد الطَّحَّان ثِقَة رجل صَالح لَهُ فِي بدنه صَلَاح اشْترى نَفسه من الله ثَلَاث مَرَّات قَالَه أَحْمد بن حَنْبَل"],[318,"قَالَ وخَالِد النيلي خَالِد بن دِينَار شيخ ثِقَة"],[319,"وخَالِد الزيات لَا بَأْس بِهِ"],[320,"وخَالِد بن يزِيد ثِقَة"],[321,"وَأَبُو عبد الرَّحِيم خَالِد بن أبي يزِيد وَبَينه وَبَين مُحَمَّد بن سَلمَة قرَابَة كَانَ على بَيت المَال مَا أقرب حَدِيثه وَقَالَهُ أَحْمد"],[322,"وَقَالَ يحيى خرَاش بن مَالك ثِقَة"],[323,"وَخَلِيفَة بن غَالب صَالح"],[324,"وَخَلِيفَة بن خياط ثِقَة"],[325,"نَا عبد الله بن مُحَمَّد الْبَغَوِيّ نَا عبد الله بن مُحَمَّد نَا أَبُو عُبَيْدَة الْحداد قَالَ نَا خلف بن مهْرَان أَبُو الرّبيع الْعَدوي وَكَانَ ثِقَة مرضيا"],[326,"قَالَ يحيى فِي رِوَايَة بن أبي خَيْثَمَة عَنهُ خلف بن خَليفَة واسطي لَيْسَ بِهِ بَأْس وَقَالَ فِيهِ عُثْمَان بن أبي شيبَة هُوَ صَدُوق ثِقَة وَلكنه كَانَ خرف فاضطرب عَلَيْهِ حَدِيثه"],[327,"خلف بن الْوَلِيد ثِقَة قَالَه يحيى فِي رِوَايَة بن أبي خَيْثَمَة عَنهُ"],[328,"قَالَ بن أبي خَيْثَمَة ليحيى أَنا أُعْطِيك رجلا وَجب عَلَيْهِ حد فِي فِرْيَة يزْعم انه ثِقَة قَالَ من هُوَ قلت خلف بن سَالم قَالَ ذَاك إِنَّمَا شتم بنت حَامِد مرّة وَاحِدَة وَمَا بِهِ بَأْس إِلَّا انه سَفِيه"],[329,"وَقَالَ أَحْمد فِي رِوَايَة عبد الله ابْنه عَنهُ خلاس ثِقَة ثِقَة"],[330,"وَقَالَ يحيى بن سعيد فِي رِوَايَة عَليّ بن الْمَدِينِيّ عَنهُ خُلَيْد بن جَعْفَر بَلغنِي انه لَا بَأْس بِهِ وَقَالَ فِيهِ شُعْبَة وَقد روى عَنهُ كَانَ من أصدق النَّاس وأشدهم انقاءا"],[331,"الْخَلِيل بن مرّة ثِقَة قَالَ أَحْمد بن صَالح مَا رَأَيْت أحدا يتَكَلَّم فِيهِ وَرَأَيْت أَحَادِيثه عَن قَتَادَة وَيحيى بن أبي كثير صحاصا وانما اسْتغنى عَنهُ البصريون لِأَنَّهُ كَانَ خاملا وَلم أر أحدا تَركه وَهُوَ ثِقَة"],[332,"الْحسن بن أَحْمد بن صَدَقَة"],[333,"قَالَ بن أبي خَيْثَمَة قَالَ نَا يحيى بن معِين نَا أَبُو مُعَاوِيَة عَن الْأَعْمَش قَالَ كَانَ خَيْثَمَة بن عبد الرَّحْمَن سيدا"],[334,"خصيف جزري ثِقَة لَيْسَ بِهِ بَأْس قَالَه يحيى بن معِين"],[335,"الْخضر بن مُحَمَّد الْحَرَّانِي الَّذِي حَدثنَا عَنهُ عَمْرو النَّاقِد ثِقَة قَالَه أَحْمد بن حَنْبَل"],[336,"خبيب بن عبد الرَّحْمَن ثِقَة قَالَه يحيى"],[337,"قَالَ والخزرج بن عُثْمَان السَّعْدِيّ صَالح"],[338,"نَا عبد الله بن سُلَيْمَان الْأَشْعَث قَالَ ثَنَا كثير بن عُبَيْدَة قَالَ سَمِعت بن عُيَيْنَة يَقُول قَالَ لي بن جريج لقِيت دَاوُد بن أبي هِنْد فرأيته يقرع الْعلم قرعا وَبِه قَالَ حَدثنَا بن عُيَيْنَة قَالَ قَالَ أبي لقد رَأَيْت دَاوُد بن أبي هِنْد وَهُوَ بن خمس وَعشْرين سنة وَهُوَ يُسَمِّي دَاوُد الْقَارِي وَقَالَ بن معِين فِي رِوَايَة الْمفضل بن عتْبَان عَنهُ دَاوُد بن أبي هِنْد مولى لبني قُشَيْر وَاسم أبي هِنْد دِينَار وَقَالَ عُثْمَان دَاوُد بن أبي هِنْد ثَبت وَقَالَ أَحْمد دَاوُد بن أبي هِنْد ثِقَة ثِقَة"],[339,"دَاوُد بن الْحصين ثِقَة لَيْسَ بِهِ بَأْس قَالَه يحيى وَقَالَ فِيهِ احْمَد بن صَالح هُوَ من أهل الثِّقَة والصدق وَلَا شكّ فِيهِ"],[340,"وَقَالَ يحيى فِي رِوَايَة عَبَّاس بن مُحَمَّد دَاوُد الأودي الَّذِي يروي عَنهُ حسن بن صَالح وَأَبُو عوَانَة ثِقَة قَالَ أَحْمد وَدَاوُد بن عبد الله الأودي كُوفِي ثِقَة من الثِّقَات وَهُوَ قديم وَهُوَ غير دَاوُد عَم بن إِدْرِيس روى عَن حميد بن عبد الرَّحْمَن وروى عَنهُ أَبُو عوَانَة وَزُهَيْر بن خَيْثَمَة"],[341,"دَاوُد بن أبي الْفُرَات يحدث عَن أبي بردة ثِقَة قَالَه يحيى وَقَالَ فِيهِ عبد الله بن الْمُبَارك انه ثِقَة لَا يعلم بِهِ بَأْسا"],[342,"وَقَالَ بن معِين دَاوُد بن عَمْرو روى عَنهُ هشيم لَيْسَ بِهِ بَأْس وَهُوَ هاشمي قدم وَاسِط"],[343,"وَقَالَ دَاوُد بن شَابُور ثِقَة"],[344,"وَدَاوُد بن إِبْرَاهِيم ثِقَة"],[345,"وَدَاوُد بن محبر لَيْسَ بِكَذَّابٍ قد كتبت عَن أَبِيه المحبر بن قحذم قَالَه يحيى"],[346,"أَبُو الحجاف واسْمه دَاوُد بن أبي عَوْف صَالح قَالَه أَحْمد"],[347,"دَاوُد بن فَرَاهِيجَ روى عَنهُ شُعْبَة لَيْسَ بِهِ بَأْس قَالَه يحيى وَقَالَ فِيهِ مرّة أُخْرَى هُوَ ضَعِيف"],[348,"دراج أَو السَّمْح سُلَيْمَان بن عَمْرو مصري يروي عَن أبي الْهَيْثَم عَن أبي سعيد مَا كَانَ بِهَذَا الْإِسْنَاد فَلَيْسَ بِهِ بَأْس ودراج وَأَبُو الْهَيْثَم ثقتان قَالَه يحيى"],[349,"وَقَالَ دَيْلَم بن غَزوَان صَالح يروي ثَلَاثَة وَيحْتَمل أَرْبَعَة أَحَادِيث"],[350,"أَبُو صَالح الَّذِي روى عَنهُ الْأَعْمَش اسْمه ذكْوَان مولى غطفان مديني ثِقَة قَالَه يحيى"],[351,"قَالَ الشّعبِيّ ثَنَا ربيع بن خثيم وَكَانَ من معادن الصدْق"],[352,"الرّبيع بن صبيح قَالَ يحيى ثِقَة وَقَالَ مرّة أُخْرَى ضَعِيف وَقَالَ فِيهِ لَا بَأْس بِهِ رجل صَالح نَا عبد الله بن مُحَمَّد الْبَغَوِيّ ثَنَا مَحْمُود بن غيلَان نَا أَبُو دَاوُد قَالَ قَالَ شُعْبَة لقد بلغ الرّبيع بمصرنا هَذَا مَا لم يبلغهُ الْأَحْنَف بن قيس"],[353,"الرّبيع بن سعد الْجعْفِيّ ثِقَة يروي عَنهُ حُسَيْن الْجعْفِيّ ومروان ووكيع قَالَه يحيى وَقَالَ بن عمار الرّبيع بن سعد ثِقَة كُوفِي"],[354,"نَا مُحَمَّد بن مخلد نَا صَالح بن أَحْمد نَا عَليّ بن الْمَدِينِيّ قَالَ سَأَلت عبد الرَّحْمَن بن مهْدي عَن الرّبيع بن عبد الله الَّذِي روى عَن الْحسن وَعَن حَفْص عَن الْحسن قَالَ كَانَ عِنْدِي ثِقَة فِي حَدِيث قلت لعبد الرَّحْمَن كَانَ يرى الْقدر قَالَ كَانَ يُجَالس عَمْرو بن قايد يَوْم الْجُمُعَة"],[355,"الرّبيع بن حبيب كُوفِي أَخُو عَائِذ بن حبيب وهما ثقتان يُقَال لَهما بَنو الملاح"],[356,"وَالربيع بن حبيب بَصرِي عَن الْحسن وَابْن سِيرِين وَهُوَ ثِقَة"],[357,"الرّبيع بن مُسلم شيخ ثِقَة قَالَه أَحْمد وَقَالَ فِيهِ يحيى لَيْسَ بِهِ بَأْس"],[358,"نَا مُحَمَّد بن أَحْمد بن الْحسن نَا مُحَمَّد بن عُثْمَان بن أبي شيبَة قَالَ سَمِعت أبي يَقُول لما حَدثنَا زيد بن الْحباب عَن ربيع بن إِبْرَاهِيم الْحَنَفِيّ سَأَلته عَنهُ فَقَالَ كَانَ وَالله من الصَّادِقين"],[359,"ربيعَة بن كُلْثُوم بن جبر روى عَنهُ يحيى بن سعيد قَالَ يحيى بن معِين لَيْسَ بِهِ بَأْس وَقَالَ فِيهِ أَحْمد هُوَ صَالح"],[360,"نَا أَحْمد بن الْحُسَيْن بن الْجُنَيْد ناعلي بن مُسلم نَا وَكِيع نَا ربيعَة بن عُثْمَان التَّيْمِيّ وَكَانَ فِيهِ عسر وَكَانَ عِنْده أَحَادِيث حَسَنَة وَكَانَ ثِقَة"],[361,"روح بن الْقَاسِم قَالَ فِيهِ بن الْمُبَارك كَانَ ثِقَة وَقَالَ فِيهِ سُفْيَان فِي رِوَايَة عَليّ بن الْمَدِينِيّ لم أر رجلا فِي شَيْء أحسن حفظا من روح بن الْقَاسِم نَا الْبَغَوِيّ عبد الله بن مُحَمَّد قَالَ قَالَ إِسْحَاق بن إِبْرَاهِيم الْمروزِي عَن بن معِين روح بن الْقَاسِم ثِقَة"],[362,"روح بن أسلم قَالَ فِيهِ يحيى لم يكن من أهل الْكَذِب وَقَالَ فِيهِ بن أبي خَيْثَمَة لم يزل أبي يحدث عَن روح بن أسلم حَتَّى مَاتَ وَسُئِلَ بن معِين عَنهُ فَلم يقل إِلَّا خيرا"],[363,"حَدثنَا عبد الله بن مُحَمَّد الْبَغَوِيّ قَالَ ثَنَا إِسْحَاق بن إِبْرَاهِيم يَعْنِي بن أبي إِسْرَائِيل قَالَ حَدثنَا الثِّقَة أَبُو رَجَاء روح بن الْمسيب الْكَلْبِيّ"],[364,"روح بن عبَادَة صَدُوق صَالح قَالَه يحيى بن معِين وثقة مرّة أُخْرَى"],[365,"نَا عبد الله بن مُحَمَّد الْبَغَوِيّ قَالَ سَمِعت أَحْمد بن حَنْبَل يَقُول رشدين أَرْجُو أَن يكون ثِقَة أَو صَالح الحَدِيث وَفِي رِوَايَة أُخْرَى عَنهُ فِي رشدين بن سعد الْمصْرِيّ رشدين من أوثق النَّاس فِي الحَدِيث وَكَانَ يَقُول إِن رشدين بن سعد مستجاب الدعْوَة وَذكر أَحْمد أَو مُحَمَّد بن رشدين قَالَ حَدثنِي مهْدي بن جَعْفَر قَالَ كتب عني أَحْمد بن حَنْبَل كتاب جدي رشدين بن سعد على الْوَجْه مَا أشبه عَيْنَيْك بعيني جدك وَكُنَّا إِذا نَظرنَا اليه قَالَ غضوا عني أبصاركم"],[366,"الركين الضَّبِّيّ ثِقَة يروي عَنهُ سُفْيَان الثَّوْريّ قَالَه يحيى"],[367,"وركين الْفَزارِيّ أَيْضا لم يذكرهُ يحيى إِلَّا بِخَير"],[368,"الركين بن الرّبيع ثِقَة قَالَه أَحْمد"],[369,"الرحيل بن مُعَاوِيَة قَالَ يحيى لَيْسَ بِهِ بَأْس"],[370,"نَا الْحسن بن صَدَقَة نَا بن أبي خَيْثَمَة قَالَ سَمِعت يحيى بن معِين يَقُول قَالَ عبد الرَّحْمَن بن مهْدي كُنَّا نعد ربعي بن علية أَخا إِسْمَاعِيل بن علية من بقايا شُيُوخنَا قَالَ يحيى هُوَ ثِقَة مَأْمُون وَفِي رِوَايَة إِسْحَاق عَن يحيى هُوَ صَالح"],[371,"رواد أَبُو عِصَام لَيْسَ بِهِ بَأْس إِنَّمَا غلط عَن سُفْيَان قَالَه يحيى"],[372,"رَقَبَة بن مصقلة شيخ ثِقَة من الثِّقَات قَالَه أَحْمد"],[373,"ريحَان بن سعيد حدث عَن عباد بن مَنْصُور قَالَ يحيى مَا أرى بِهِ بَأْسا"],[374,"رَجَاء بن أبي سَلمَة ثِقَة حدث عَنهُ حَمَّاد بن سَلمَة وَحَمَّاد بن زيد وضمرة وَهُوَ رَجَاء أَبُو الْمِقْدَام قَالَه أَحْمد وَقَالَ فِيهِ يحيى ثِقَة"],[375,"رزام بن سعيد يروي عَنهُ أَبُو أَحْمد الزبيرِي قَالَ فِيهِ أَحْمد بن حَنْبَل هُوَ ثِقَة"],[376,"قَالَ نَا مكرم بن أَحْمد قَالَ نايزيد بن الْهَيْثَم قَالَ يحيى بن معِين زُهَيْر بن مُعَاوِيَة ثِقَة مَأْمُون"],[377,"زُهَيْر الْخُرَاسَانِي لَيْسَ بِهِ بَأْس روى عَنهُ معافى وَالْحسن بن حَلِيم قَالَه يحيى"],[378,"وَقَالَ أَحْمد بن صَالح زُهَيْر بن مُحَمَّد لَا بَأْس بِهِ وَهَذِه الْأَحَادِيث الَّتِي يَرْوِيهَا أهل الشَّام عَنهُ لَيْسَ تعجبني وَقَالَ يحيى فِي رِوَايَة أُخْرَى زُهَيْر بن مُحَمَّد ثِقَة خراساني"],[379,"وَزُهَيْر بن أبي ثَابت روى عَنهُ سُفْيَان الثَّوْريّ وَهُوَ كُوفِي ثِقَة"],[380,"وَقَالَ الْأَعْمَش كنت إِذا سَمِعت من زيد بن وهب الحَدِيث لم أُبَالِي أَن لَا أسمعهُ من غَيره"],[381,"زيد بن أبي أنيسَة ثِقَة قَالَه يحيى"],[382,"زيد بن أسلم ثِقَة قَالَه احْمَد"],[383,"زيد بن جُبَير هُوَ الَّذِي يروي حَدِيث بن مَسْعُود إِن الجنادب لتنقز من المرضاء ثِقَة وثقة يحيى فِي غير رِوَايَة وَقَالَ احْمَد فِي زيد بن جُبَير وَحَكِيم بن جُبَير ليسَا بأخوين"],[384,"زيد بن جُبَير الْجُشَمِي ثِقَة من بني سليم وَهُوَ صَالح الحَدِيث وَفِي رِوَايَة أُخْرَى عَن أَحْمد وَسُئِلَ عَن زيد بن جُبَير وآدَم بن عَليّ فَقَالَ زيد بن جُبَير أعجب إِلَيّ زيد روى عَنهُ شُعْبَة"],[385,"زيد الْعمي صَالح قَالَه أَحْمد روى عَنهُ سُفْيَان وَشعْبَة"],[386,"قَالَ وَزيد بن رفيع مَا بِهِ بَأْس روى عَنهُ المَسْعُودِيّ وَمعمر"],[387,"وَقَالَ يحيى زيد بن أبي عتاب ثِقَة"],[388,"وَزيد بن حرمل ثِقَة"],[389,"وَزيد بن أبي الزَّرْقَاء ثِقَة موصلي"],[390,"زيد بن الْحباب ثِقَة قَالَه عُثْمَان بن أبي شيبَة"],[391,"زِيَاد بن سعد ثِقَة قَالَه يحيى"],[392,"زِيَاد بن جُبَير ثِقَة قَالَه يحيى"],[393,"زِيَاد بن الرّبيع كَانَ شَيخا صَدُوقًا وَلَيْسَ بِحجَّة قَالَه عُثْمَان وَقَالَ فِيهِ أَحْمد هُوَ ثِقَة"],[394,"زِيَاد بن خَيْثَمَة لَيْسَ بِهِ بَأْس قَالَه يحيى"],[395,"وَزِيَاد النميري لَيْسَ بِهِ بَأْس"],[396,"وَزِيَاد بن أبي مُسلم الَّذِي يروي عَنهُ عبيد الله بن مُوسَى ثِقَة بَصرِي وروى عَنهُ أَيْضا وَكِيع وَكَانَ يُقَال أَنه عَابِد"],[397,"زِيَاد الأعلم ثِقَة ثِقَة قَالَه أَحْمد"],[398,"وَقَالَ زِيَاد بن أبي مُسلم وَيُقَال بن مُسلم وَهُوَ أَبُو عمر الْفراء رجل صَالح"],[399,"زِيَاد بن علاقَة ثِقَة"],[400,"وَزِيَاد بن فياض ثِقَة"],[401,"وَزِيَاد بن صبيح صَالح قَالَه كُله يحيى"],[402,"زَائِدَة بن أبي الرقاد لَيْسَ بِهِ بَأْس قَالَه عبيد الله بن عمر القواريري وَقَالَ كتبت كل شَيْء عَنهُ وَأنكر الحَدِيث الَّذِي حدث بِهِ مُحَمَّد بن سَلام الجُمَحِي عَن زَائِدَة بن أبي الرقاد عَن ثَابت عَن أنس عَن النَّبِي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لَام عَطِيَّة إِذا خفضت فأشمي وَلَا تنهكي فَإِنَّهُ أسرى للْوَجْه وأحظى عِنْد الزَّوْج"],[403,"زَائِدَة بن مُوسَى الْهَمدَانِي ثِقَة قَالَه يحيى"],[404,"الزبْرِقَان بن عبد الله ثِقَة قَالَه يحيى بن سعيد الْقطَّان فِي رِوَايَة عَليّ بن الْمَدِينِيّ عَنهُ وَقَالَ بن معِين الزبْرِقَان ثِقَة لَيْسَ بِهِ بَأْس"],[405,"الزنْجِي بن خَالِد ثِقَة قَالَه يحيى فِي رِوَايَة عَبَّاس عَنهُ"],[406,"زهرَة بن معبد شيخ ثِقَة قَالَه أَحْمد"],[407,"وَقَالَ زَكَرِيَّا بن إِسْحَاق ثِقَة"],[408,"وزَكَرِيا بن أبي زَائِدَة حُلْو الحَدِيث ثِقَة قَالَه أَحْمد ووثقة يحيى وَقَالَ هُوَ أَخُو عمر"],[409,"زَكَرِيَّا بن مَنْظُور شيخ روى عَنهُ الْحزَامِي والبرجماني وَلَيْسَ بِهِ بَأْس قَالَه أَحْمد بن صَالح"],[410,"زَكَرِيَّا بن سياه ثِقَة"],[411,"وزَكَرِيا بن سليم أَن عمرَان صَالح قَالَه يحيى بن معِين"],[412,"زفر صَاحب الرَّأْي ثِقَة مَأْمُون قَالَه يحيى بن معِين فِي رِوَايَة الْعَبَّاس عَنهُ وَكَذَا قَالَ أَبُو نعيم زفر ثِقَة"],[413,"زفر بن هُبَيْرَة الْمَازِني ثِقَة ثِقَة يروي عَن إِن ثَوْبَان ذكره عبد الله بن سُلَيْمَان الْأَشْعَث عَنهُ الْجراح بن مخلد"],[414,"زفر بن سُلَيْمَان سجستاني ثِقَة قَالَه يحيى وَعُثْمَان بن أبي شيبَة وَقَالَ روى عَن عبد الله بن إِدْرِيس"],[415,"زاجر بن الصَّلْت ثِقَة قَالَه يحيى بن معِين وَقد سَمِعت مِنْهُ"],[416,"زَاذَان ثِقَة كَانَ يتَغَنَّى ثمَّ تَابَ"],[417,"الزبير بن الخريت ثِقَة قَالَه أَحْمد"],[418,"وَقَالَ بن معِين الزبير بن عدي ثِقَة"],[419,"قَالَ وزرزر مولى آل جُبَير ثِقَة"],[420,"سَمُرَة صَدُوق الحَدِيث عَظِيم الْأَمَانَة قَالَه بن سِيرِين فِي رِوَايَة عبد الله بن صبيح عَنهُ"],[421,"سعيد بن أَوْس الْعَبْسِي لَيْسَ بِهِ بَأْس قَالَه يحيى"],[422,"وَقَالَ بن عمار سعد بن سعيد أَخُو يحيى بن سعيد الْأنْصَارِيّ ثِقَة"],[423,"قَالَ يحيى بن معِين فِي سعد بن إِبْرَاهِيم ثِقَة هُوَ أكبر من يَعْقُوب أَي شَيْء يقصر"],[424,"سعد بن عبد الله الْأَيْلِي لَا بَأْس بِهِ قَالَه أَحْمد بن صَالح"],[425,"أَبُو هَاشم السنجاري اسْمه سعد روى عَن بن عمر بَصرِي ثِقَة قَالَه يحيى"],[426,"وَقَالَ سعد بن سِنَان روى عَنهُ يزِيد بن أبي حبيب ثِقَة"],[427,"وَسَعِيد بن يسَار مديني ثِقَة"],[428,"وَقَالَ بن عمار فِي أبي سِنَان سعيد بن سِنَان الشَّيْبَانِيّ هُوَ ثِقَة كُوفِي"],[429,"وَقَالَ يحيى بن سعيد فِي سعيد بن عبيد الطَّائِي لم يكن بِهِ بَأْس وَقَالَ بن معِين سعيد بن عبيد الطَّائِي ثِقَة"],[430,"وَسَعِيد بن عبيد الْهنائِي الْبَصْرِيّ ثِقَة كَذَا قَالَ فِي رِوَايَة يزِيد بن الْهَيْثَم عَنهُ فيهمَا"],[431,"وَفِي رِوَايَة عَنهُ انه ذكر سعيد بن بشير فَقَالَ انه ثقه مَأْمُون"],[432,"سعيد بن حسان المَخْزُومِي ثِقَة قَالَه يحيى"],[433,"وَقَالَ سعيد بن زَكَرِيَّا الْمَدَائِنِي لَيْسَ بِهِ بَأْس وَقَالَ فِيهِ عُثْمَان بن أبي شيبَة لَا بَأْس بِهِ صَدُوق لكنه لم يكن يعرف الحَدِيث"],[434,"قَالَ بن معِين وَسَعِيد الْجريرِي ثِقَة"],[435,"وَسَعِيد بن يزِيد أَبُو مسلمة ثِقَة والجريري ثِقَة أَكثر حَدِيث من أبي مسلمة وَأَبُو مسلمة شيخ مِسْكين ثِقَة"],[436,"سعيد بن نَافِع روى عَنهُ بكري وَيزِيد بن أبي حبيب كَانَ صديقا لعمر بن عبد الْعَزِيز وَكَانَ يلقب صنارة وَلَيْسَ بَين سعيد بن نَافِع وَحميد بن نَافِع قرَابَة قَالَ ذَلِك أَحْمد بن صَالح"],[437,"سعيد بن عبد الرَّحْمَن روى عَن بن سِيرِين وَهُوَ سعيد أَخُو أبي حرَّة ثِقَة قَالَه بن معِين"],[438,"قَالَ وَأَبُو عَاصِم الْعَبَّادِيّ كَانَ ينزل بعبادان لم يكن بِهِ بَأْس سَمِعت عبد الله بن منيع فِي مَا قرئَ يَقُول أَبُو عَاصِم الْعَبَّادِيّ أَحْسبهُ سعيد بن زَرْبِي"],[439,"سعيد بن عبد الرَّحْمَن بن أنيس لَيْسَ بِهِ بَأْس قَالَه يحيى"],[440,"وَعَن أَحْمد بن أبي خَيْثَمَة بِإِسْنَادِهِ كَانَ سعيد بن جُبَير جهبذ الْعلمَاء"],[441,"وَقَالَ أَحْمد بن حَنْبَل سعيد بن عبد الْعَزِيز ثِقَة"],[442,"وَسَعِيد بن أبي صَدَقَة ثِقَة ثِقَة"],[443,"وَسَعِيد بن مينا ثِقَة روى عَنهُ أَيُّوب"],[444,"سعيد بن عَمْرو بن جعدة بن هُبَيْرَة ثِقَة قَالَ يحيى حَدثنَا عَنهُ قَاسم بن مَالك وَحدث عَنهُ بن عُيَيْنَة والمسعودي وَسَعِيد المَقْبُري عَن أَبِيه عَن أبي هُرَيْرَة قَالَ يحيى أَبوهُ لَيْسَ بِهِ بَأْس وَلَكِن ابْنه ثمَّ قَالَ لَا بَأْس بهما جَمِيعًا"],[445,"وَقَالَ سعيد بن حَيَّان بن حجدر الطَّائِي لَيْسَ بِهِ بَأْس"],[446,"وَسَعِيد بن أَوْس عَن بِلَال بن يحيى لَيْسَ بِهِ بَأْس"],[447,"سعيد بن عبيد الله الثَّقَفِيّ ثِقَة"],[448,"وَسَعِيد بن عبيد الْهنائِي ثِقَة"],[449,"سعيد بن مَسْرُوق ثِقَة"],[450,"وَسَعِيد بن العنبس ثِقَة"],[451,"وَأَبُو السّفر سعيد بن أَحْمد الثَّوْريّ ثَوْر هَمدَان ثِقَة كُوفِي"],[452,"سُلَيْمَان بن عَمْرو مصري يُقَال لَهُ أَبُو الْهَيْثَم ثِقَة عَن أبي سعيد الْخُدْرِيّ وَعنهُ دراج أَبُو السَّمْح قَالَه يحيى"],[453,"سُلَيْمَان الْأَحول مكي خَال بن أبي نجيح هُوَ بن أبي مُسلم ثِقَة ثِقَة"],[454,"وَسليمَان بن سحيم لَيْسَ بِهِ بَأْس"],[455,"وَسليمَان بن بُرَيْدَة أوثق وَأفضل من عبد الله قَالَه يحيى"],[456,"سُلَيْمَان بن بِلَال ثِقَة وَكَانَ على سوق الْمَدِينَة قَالَه يحيى"],[457,"سُلَيْمَان بن أبي الْمُغيرَة ثِقَة خِيَار قَالَه سُفْيَان بن عُيَيْنَة"],[458,"سُلَيْمَان بن بِلَال لَا بَأْس بِهِ وَلَيْسَ مِمَّن يعْتَمد على حَدِيثه قَالَه عُثْمَان بن أبي شيبَة"],[459,"أَبُو خَالِد الْأَحْمَر لَيْسَ بِهِ بَأْس وَفِي كتاب بن أبي خَيْثَمَة أَبُو خَالِد الْأَحْمَر الثِّقَة الْمَأْمُون"],[460,"سُلَيْمَان بن سحيم من موَالِي الْعَبَّاس لَهُ شَأْن ثَبت قَالَه أَحْمد بن صَالح"],[461,"سُلَيْمَان بن الْمُغيرَة ثِقَة قَالَه عُثْمَان"],[462,"سُلَيْمَان بن عبد الرَّحْمَن الدِّمَشْقِي كتب عَنهُ شُعْبَة بواسط وروى عَنهُ خَالِد بن معدان وَاللَّيْث بن سعد وَعَمْرو وَيزِيد بن أبي حبيب وجعفر بن ربيعَة وَابْن لَهِيعَة بِمصْر وَله شَأْن قَالَه أَحْمد بن صَالح"],[463,"سُلَيْمَان بن أبي سُلَيْمَان يروي عَنهُ يزِيد بن أبي حبيب كِلَاهُمَا ثِقَة ذكره بن أبي خَيْثَمَة"],[464,"سُلَيْمَان بن يسَار ثِقَة قَالَه يحيى"],[465,"قَالَ وَسليمَان بن عبيد السّلمِيّ ثِقَة"],[466,"وَسليمَان الْعَطَّار عَن عزْرَة ثِقَة هُوَ أَبُو صلَة بن سُلَيْمَان الوَاسِطِيّ"],[467,"سَلام بن أبي مُطِيع من الثِّقَات حَدثنَا عَنهُ إِن مهْدي"],[468,"وَسَلام بن مِسْكين من الثِّقَات قَالَه أَحْمد"],[469,"وَقَالَ بن معِين سَلام بن أبي مُطِيع بَصرِي ثِقَة قَالَه أَحْمد كَانَ سَلام بن أبي مُطِيع صَاحب سنة وَكَانَ عبد الرَّحْمَن بن مهْدي يحدث عَنهُ"],[470,"قَالَ يحيى أَبُو الْأَحْوَص ثِقَة يَعْنِي سَلام بن سليم"],[471,"نَا عبد الله بن مُحَمَّد الْبَغَوِيّ قَالَ سَمِعت أَحْمد بن مُحَمَّد بن حَنْبَل يَقُول أَبُو المُهَاجر الرقي اسْمه سَالم وَهُوَ ثِقَة فِي الحَدِيث"],[472,"وَقَالَ وَكِيع حَدثنَا أَبُو فراس سلم بن نبيت وَكَانَ ثِقَة وَقَالَ عُثْمَان سَلمَة بن نبيط ثِقَة شيخ كيس"],[473,"وَقَالَ يحيى سَلمَة بن كهيل ثِقَة"],[474,"وَأَبُو حَازِم الْأَشْجَعِيّ واسْمه سلمَان مولى عزة الأشجعية كُوفِي ثِقَة"],[475,"وَأَبُو الشعْثَاء الْمحَاربي هُوَ سليم بن أسود كُوفِي ثِقَة وَفِي رِوَايَة أُخْرَى كنيته أَبُو الْأَشْعَث روى عَنهُ إِبْرَاهِيم النَّخعِيّ"],[476,"وَأَبُو الشعْثَاء هُوَ سليم بن أَيُّوب قَالَه عُثْمَان بن أبي شيبَة"],[477,"وَقَالَ أَحْمد سليم بن أَخْضَر من أهل الْأَمَانَة والصدق"],[478,"وَقَالَ يحيى فِي سلم الْعلوِي لَا بَأْس بِهِ فَذكر ليحيى قَول شُعْبَة فِيهِ قَالَ الَّذِي يرى الْهلَال قبل النَّاس فَقَالَ لَيْسَ بِهِ بَأْس حَدِيد الْبَصَر يرى الْهلَال قبل النَّاس"],[479,"سلم بن جَعْفَر ثِقَة كَذَا قَالَ عَليّ بن الْمَدِينِيّ وَهُوَ رجل من أهل الْيمن"],[480,"وَقَالَ يحيى فِي سلم بن أبي الذَّيَّال مَا أرى بِهِ بَأْسا حدث عَنهُ مُعْتَمر وَقَالَ أَحْمد سلم بن أبي الذَّيَّال ثِقَة صَالح الحَدِيث مَا سَمِعت أحدا حدث عَنهُ غير مُعْتَمر وَكَانَ غزا مَعَه فِي الْبَحْر فَسمع مِنْهُ زَعَمُوا ذَلِك"],[481,"وَقَالَ يحيى سلم بن قُتَيْبَة ثِقَة صَدُوق لَيْسَ بِهِ بَأْس"],[482,"وَقَالَ يحيى وَأحمد سلم بن عبد الرَّحْمَن النَّخعِيّ ثِقَة"],[483,"سلم بن بشير بن جحل لَا بَأْس بِهِ قَالَه يحيى"],[484,"السّري بن يحيى قَالَ شُعْبَة مَا رَأَيْت أصدق مِنْهُ وَقَالَ يحيى بن سعيد السّري بن يحيى ثَبت ثِقَة وَقَالَ بن معِين لَيْسَ بِهِ بَأْس وَفِي رِوَايَة أُخْرَى عَنهُ ثِقَة وَسُئِلَ عَنهُ وَعَن يزِيد بن إِبْرَاهِيم أَيهمَا أثبت فَقَالَ يزِيد لَا شكّ فِيهِ وَالسري ثِقَة لَكِن يزِيد بن إِبْرَاهِيم أكبر مِنْهُ"],[485,"وَقَالَ سِنَان أَبُو حبيب ثِقَة"],[486,"وَقَالَ أَحْمد بن صَالح سِنَان بن سعد الْكِنْدِيّ ثِقَة لَيْسَ فِي قلبِي من حَدِيثه شَيْء هُوَ من أهل الْبَصْرَة"],[487,"وَقَالَ يحيى سِنَان بن عبد الرَّحْمَن ثِقَة"],[488,"وَسنَان بن هَارُون البرجمي صَالح"],[489,"وَسنَان أَبُو ربيعَة صَالح"],[490,"وَقَالَ أَحْمد فِي سيار أبي الحكم ثِقَة"],[491,"وَقَالَ عَليّ بن الْمَدِينِيّ سيف بن سُلَيْمَان الْمَكِّيّ ثِقَة وَقَالَ سَأَلت يحيى بن سعيد عَن سيف بن سُلَيْمَان فَقَالَ كَانَ عندنَا ثبتا مِمَّن يصدق ويحفظ وَقَالَ بن عمار سيف الْمَكِّيّ روى عَنهُ يحيى الْقطَّان وَهُوَ ثِقَة نَا عبد الله بن سُلَيْمَان قَالَ قَالَ عبد الله بن احْمَد قَالَ أبي سيف اخْتلفُوا فِيهِ بن سُلَيْمَان أَو بن أبي سُلَيْمَان ثِقَة"],[492,"سيف بن هَارُون البرجمي ثِقَة قَالَه أَبُو نعيم"],[493,"سيف بن سُلَيْمَان التمار ثِقَة من كبار أَصْحَاب أبي جَعْفَر"],[494,"نَا مُحَمَّد بن مَحْمُود السراج حَدثنَا بن زَنْجوَيْه نَا يَعْقُوب الْحَضْرَمِيّ قَالَ قَالَ شُعْبَة سُفْيَان أَمِير الْمُؤمنِينَ فِي الحَدِيث نَا مُحَمَّد بن مخلد قَالَ سَمِعت أَحْمد بن مَنْصُور الرَّمَادِي قَالَ نَا أَبُو الصَّلْت قَالَ نَا يحيى بن يمَان قَالَ كَانَ سُفْيَان الثَّوْريّ أَمِير الؤمنين فِي الحَدِيث وَابْن عُيَيْنَة صَاحب شرطته نَا يحيى بن مُحَمَّد بن صاعد قَالَ نَا أَحْمد بن مَنْصُور نَا عبد الرَّزَّاق قَالَ كُنَّا عِنْد الثَّوْريّ فَقَالَ أخبرنَا مَنْصُور عَن إِبْرَاهِيم عَن عَلْقَمَة عَن عبد الله قَالَ هَذَا وَالله السد الْعَرَبِيّ"],[495,"نَا مُحَمَّد بن أَحْمد بن الْحسن قَالَ نَا مُحَمَّد بن عُثْمَان بن أبي شيبَة قَالَ سَمِعت أبي يَقُول كُنَّا عِنْد أبي نعيم فَذَكرنَا سُفْيَان بن عُيَيْنَة فَقَالَ أَبُو نعيم سُفْيَان بن عُيَيْنَة الْحِنْطَة الراوردية وَسَائِر الْقَوْم شعير البط نَا أَبُو حبيب الْعَبَّاس بن أَحْمد بن مُحَمَّد عِيسَى الْبري سنة ثَمَان وثلاثمائة قَالَ نَا سوار بن عبد الله قَالَ سَمِعت بن عُيَيْنَة يَقُول لَو قيل لي لم طلبت الحَدِيث مَا دَريت مَا أَقُول نَا الْبَغَوِيّ ثَنَا عبد الله بن نعيم القواريري قَالَ نَا حَمَّاد بن زيد قَالَ قَالَ سُفْيَان بن عُيَيْنَة يَا أَبَا إِسْمَاعِيل ذهب بهاء الْعلم نَا إِبْرَاهِيم بن إِبْرَاهِيم بن أبان الرواس قَالَ نَا سوار بن عبد الله قَالَ قَالَ سُفْيَان بن عُيَيْنَة لَيْسَ شَيْء فِي الأَرْض أثقل حملا من الْعلم نَا نصر بن الْقَاسِم قَالَ نَا إِسْحَاق بن أبي إِسْرَائِيل قَالَ سَمِعت سُفْيَان يَقُول إِذا كَانَ يأتم بِمن قبله فَهُوَ إِمَام لمن بعده"],[496,"سُفْيَان بن حُسَيْن قَالَ بن معِين ثِقَة فِي غير الزُّهْرِيّ قَالَ عُثْمَان كَانَ مؤدبا للمهدي وَلكنه كَانَ مضطربا فِي الحَدِيث قَلِيلا وَقَالَ يحيى فِي رِوَايَة أُخْرَى ثِقَة واسطي"],[497,"قَالَ عُثْمَان سُفْيَان بن وَكِيع رجل صدق"],[498,"سُفْيَان بن أبي عبد الله صَالح"],[499,"سمى مولى أبي بكر ثِقَة قَالَه يحيى"],[500,"وَقَالَ عَن أبي حَاجِب سوَادَة بن عَاصِم بَصرِي ثِقَة"],[501,"السكن بن إِسْمَاعِيل الْأَصَم ثِقَة قَالَه بن الْمَدِينِيّ وَيحيى وَعبيد الله بن عمر"],[502,"قَالَ يحيى بن معِين سكن البرجمي صَالح"],[503,"وَسكن بن الْمُغيرَة صَالح"],[504,"وَقَالَ سماك بن حَرْب ثِقَة نَا عبد الله بن مُحَمَّد الْبَغَوِيّ قَالَ نَا مُحَمَّد بن غيلَان قَالَ نَا مُؤَمل عَن حَمَّاد بن سَلمَة عَن سماك بن حَرْب قَالَ أدْركْت ثَمَانِينَ من أَصْحَاب النَّبِي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ"],[505,"سماك بن سَلمَة رجل صَالح قَالَه أَحْمد"],[506,"سماك أَبُو بكر عَن أَيُّوب فِي الْأَذَان ثِقَة"],[507,"وَقَالَ يحيى وَعَاصِم بن بَهْدَلَة وَسماك ثقتان"],[508,"أَبُو الْعَبَّاس الشَّاعِر اسْمه السَّائِب بن فروخ ثِقَة"],[509,"والسائب بن عمر المَخْزُومِي حدث عَنهُ يحيى بن سعيد أرَاهُ شَيخا ثِقَة قَالَه يحيى"],[510,"وَقَالَ أَحْمد بن صَالح سُهَيْل بن أبي صَالح من الْمُتَّقِينَ وَإِنَّمَا توقي فِي غلط حَدِيثه مِمَّن يَأْخُذ عَنهُ"],[511,"وَقَالَ أَحْمد الْعَلَاء وَسُهيْل بن أبي صَالح يَعْنِي أَنَّهُمَا نظيران سُهَيْل أروى عَن الرِّجَال"],[512,"سهل السراج ثِقَة بَصرِي قَالَه يحيى"],[513,"وَقَالَ سهل بن يُوسُف صَاحب الأنماط ثِقَة قد سَمِعت مِنْهُ"],[514,"وَسُهيْل بن أبي حزم صَالح"],[515,"وَسُهيْل بن صبرَة روى عَنهُ مُحَمَّد بن أبي بكر الْمقدمِي وَقَالَ أَحْمد سُهَيْل ثِقَة حَدثنَا عَنهُ عَفَّان وَقَالَ مُحَمَّد بن أبي بكر لم يكن بِالْبَصْرَةِ أحفظ عَن شُعْبَة من هَذَا يَعْنِي سُهَيْل بن صبرَة"],[516,"سحبل بن أبي يحيى ثِقَة قَالَه يحيى وَقَالَ أَحْمد سحبل اسْمه عبد الله بن مُحَمَّد بن أبي يحيى لَيْسَ بِهِ بَأْس"],[517,"نَا يحيى بن مُحَمَّد بن صاعد قَالَ نَا أَبُو بكر بن مُحَمَّد بن هاني الْأَثْرَم قَالَ قَالَ أَبُو عبد الله أَحْمد بن حَنْبَل قد كَانَ سنيد يلْزم حجاجا وَرُبمَا رَأَيْت حجاجا يملي عَلَيْهِ من كِتَابه وَأَرْجُو الا يكون حدث إِلَّا بِصدق"],[518,"وَقَالَ بن عمار سحيم أَبُو شيخ ثِقَة إِلَّا أَنه كَانَ مُحْتَاجا"],[519,"نَا مُحَمَّد بن مُحَمَّد بن سُلَيْمَان الباغندي قَالَ حَدثنِي زيد بن حزم قَالَ حَدثنَا أَبُو دَاوُد عَن شُعْبَة عَن خَالِد الْحذاء قَالَ مَا أعلم أحدا أَحَق بِالْقضَاءِ من سوار ثمَّ قَالَ عبيد الله هُوَ أعلم بالآثار"],[520,"أَبُو حَمْزَة سوار الصَّيْرَفِي ثِقَة قَالَه يحيى بن معِين"],[521,"وسدير الصَّيْرَفِي ثِقَة"],[522,"وسوار ثِقَة"],[523,"قَالَ أَحْمد فِي سوار أبي عُبَيْدَة هُوَ ثِقَة وَكَانَ من كبار أَصْحَاب سعيد بن أبي عرُوبَة"],[524,"وَقَالَ أَحْمد فِي سُوَيْد بن نجيح أبي قُطْبَة مَا أرى بِهِ بَأْسا حدث عَنهُ وَكِيع وَمُحَمّد بن عبيد ومروان"],[525,"وَقَالَ يحيى سُوَيْد بن إِبْرَاهِيم صَالح"],[526,"وسُويد بن زيد الرقاشِي ثِقَة"],[527,"وسريج بن يُونُس لَيْسَ بِهِ بَأْس"],[528,"وسعدان بن سَالم لَيْسَ بِهِ بَأْس"],[529,"وَأَبُو صَالح الَّذِي يروي عَن بن عَبَّاس اسْمه سميع الزيات لَا أَدْرِي كُوفِي أم بَصرِي ثِقَة"],[530,"قَالَ يحيى شُرَيْح بن هاني ثِقَة كُوفِي انْتقل الى الشَّام"],[531,"وَشُرَيْح بن أَرْطَاة كُوفِي ثِقَة وَهُوَ أقدم من شُرَيْح بن شُرَحْبِيل القَاضِي"],[532,"وَشُرَيْح القَاضِي ثِقَة وَهُوَ شُرَيْح بن الْحَارِث أَبُو أُميَّة وَكَانَ كوشجا عَاشَ عشْرين وَمِائَة سنة وَقَالَ سُلَيْمَان بن أبي شيخ فِي رِوَايَة بن أبي خَيْثَمَة عَنهُ كَانَ يُقَال ولي شُرَيْح زمن عمر وَالصَّحِيح فِي زمن عُثْمَان"],[533,"شُرَيْح بن النُّعْمَان روى عَنهُ أَبُو إِسْحَاق وَكَانَ رجل صدق"],[534,"شُرَيْح بن سراج الْجرْمِي أَبُو بشر ثِقَة قَالَه أَحْمد"],[535,"وَقَالَ يحيى شهر بن حَوْشَب ثَبت وَفِي رِوَايَة أُخْرَى عَنهُ شَامي نزل الْبَصْرَة وَكَانَ من الْأَشْعَرِيين من أنفسهم وَهُوَ ثِقَة"],[536,"وَقَالَ أَحْمد فِي شُعْبَة مولى بن عَبَّاس مَا أرى بِهِ بَأْسا"],[537,"نَا عبد الله بن سُلَيْمَان نَا مُحَمَّد بن مصفر قَالَ سَمِعت بَقِيَّة بن الْوَلِيد قَالَ سَمِعت شُعْبَة بن الْحجَّاج يَقُول اكتبوا الْمَشْهُور عَن الْمَشْهُور نَا الْبَغَوِيّ ناعلي بن مُسلم نَا أَبُو دَاوُد الطَّيَالِسِيّ قَالَ مَا رَأَيْت أحدا يشبه شُعْبَة فِي الحَدِيث وَقَالَ أَيُّوب فِي رِوَايَة حَمَّاد بن زيد عَنهُ الْآن يقدم عَلَيْكُم رجل من أهل وَاسِط يُقَال لَهُ شُعْبَة هُوَ فَارس فِي الحَدِيث فَخُذُوا عَنهُ قَالَ حَمَّاد فَلَمَّا قدم شُعْبَة أَخذنَا عَنهُ نَا مُحَمَّد بن مُحَمَّد بن سُلَيْمَان الباغندي قَالَ حَدثنِي مُحَمَّد بن بشار بنْدَار قَالَ سَمِعت يحيى بن سعيد يَقُول وَقلت لَهُ عَن ثِقَة فَقَالَ لَا تقل عَن ثِقَة لَو حققت لَك مَا حدثتك إِلَّا عَن أَرْبَعَة بن عون وَشعْبَة ومسعر وَهِشَام الدستوَائي"],[538,"شبيب بن غرقده روى عَنهُ مَنْصُور ثِقَة قَالَه أَحْمد"],[539,"شبيب بن بشر ثِقَة قَالَه يحيى"],[540,"وَقَالَ شُعَيْب بن أبي حَمْزَة لَيْسَ بِهِ بَأْس هُوَ أعلم بالزهري من يُونُس وَمعمر"],[541,"وَقَالَ أَحْمد بن صَالح فِي شُعَيْب بن اللَّيْث ثِقَة قيل لِأَحْمَد سمع شُعَيْب الْكتب من أَبِيه فَقَالَ كَانَ يَقُول سَمِعت بَعْضًا وفاتني بعض وَهَذَا من ثقته قيل لَهُ سَمِعت مِنْهُ شَيْئا فَقَالَ أخذت مِنْهُ كتاب التَّارِيخ لِأَبِيهِ وَسمعت مِنْهُ شَيْئا قرئَ عَلَيْهِ وَأَنا حَاضر"],[542,"شُعَيْب بن حَرْب ثِقَة مَأْمُون قَالَه يحيى"],[543,"وَقَالَ شُعَيْب بن إِسْحَاق الدِّمَشْقِي ثِقَة"],[544,"وَشُعَيْب بن خَالِد كُوفِي لَيْسَ بِهِ بَأْس روى عَنهُ زُهَيْر بن مُعَاوِيَة"],[545,"وَشُعَيْب بن دِرْهَم ثِقَة"],[546,"وَشُعَيْب بن الحبحاب ثِقَة قَالَه أَحْمد"],[547,"وَقَالَ يحيى شبْل بن عبَادَة ثِقَة"],[548,"وَقَالَ أَحْمد شَدَّاد أَبُو طَلْحَة شيخ ثِقَة روى عَنهُ بن عَلَيْهِ ووكيع"],[549,"وَقَالَ يحيى شَدَّاد بن سعيد الرَّاسِبِي ثِقَة"],[550,"وشرحبيل بن مدرك روى عَنهُ مُحَمَّد بن عبيد ثِقَة"],[551,"وَشريك ثِقَة ثِقَة"],[552,"وَشريك بن خَليفَة رُوِيَ عَنهُ قَتَادَة وَهُوَ ثِقَة هَذَا كُله عَن يحيى"],[553,"وَقَالَ شَيبَان ثِقَة وَكَانَ صَاحب كتاب رجل صَالح يُقَال انه مَاتَ بِبَغْدَاد فِي خلَافَة الْمهْدي وَدفن فِي مَقَابِر الخيزران"],[554,"وَقَالَ عُثْمَان بن أبي شيبَة شبيل النَّحْوِيّ وَكَانَ علما صَدُوقًا حسن الحَدِيث"],[555,"قَالَ أَحْمد شباك شيخ ثِقَة وَقَالَ عُثْمَان شباك ثَبت"],[556,"وَقَالَ يحيى شهَاب بن خرَاش كُوفِي نزل الشَّام لَيْسَ بِهِ بَأْس وَفِي رِوَايَة أُخْرَى عَنهُ شهَاب بن خرَاش بن حَوْشَب صَالح"],[557,"وَقَالَ شَبابَة بن سوار صَدُوق وَقَالَ عُثْمَان شَبابَة صَدُوق حسن الْعقل ثِقَة يذكر الارجاء عَنهُ فَقَالَ كذب"],[558,"قَالَ يحيى شَقِيق بن أبي عبد الله ثِقَة نَا إِبْرَاهِيم بن مُحَمَّد الْعمريّ قَالَ نَا أَبُو كريب مُحَمَّد بن الْعَلَاء قَالَ نَا غَنَّام بن عَليّ قَالَ نَا الْأَعْمَش عَن خَيْثَمَة قَالَ مَا أتيت شقيقا قطّ إِلَّا سَمِعت مِنْهُ شَيْئا لم أسمعهُ"],[559,"وَقَالَ بن معِين أَبُو بدر شُجَاع بن مخلد أعرفهُ لَيْسَ بِهِ بَأْس نعم الشَّيْء أَو نعم الرجل ثِقَة"],[560,"وشبيل بن عزْرَة بن قيس بن عُمَيْر ثِقَة"],[561,"قَالَ يحيى بن سعيد فِي رِوَايَة عَليّ بن الْمَدِينِيّ عَنهُ وَقد سَأَلَهُ عَن صَالح بن مُسلم ثِقَة قَالَ نعم من الطَّبَقَة الْعليا"],[562,"نَا عبد لله بن سُلَيْمَان ومكرم قَالَا نَا عبد الله بن أَحْمد قَالَ قلت لأبي إِن بشر بن عمر زعم انه سَأَلَ مَالِكًا عَن صَالح مولى التؤمة فَقَالَ لَيْسَ بِثِقَة قَالَ أبي كَانَ مَالك قد أدْرك صَالحا وَهُوَ قد إختلط وَهُوَ كَبِير مَا أعلم بِهِ بَأْسا مِمَّن سمع مِنْهُ قَدِيما وَقد روى عَنهُ أكَابِر أهل الْمَدِينَة"],[563,"الصَّلْت بن مهْرَان روى عَنهُ مُحَمَّد بن بكر البرْسَانِي وَقد كَانَ ثِقَة ينزل نَبَاته"],[564,"عبد الله بن مَرْوَان ثِقَة روى عَنهُ سُلَيْمَان بن عبد الرَّحْمَن الدِّمَشْقِي وَوَثَّقَهُ"],[565,"وَقَالَ أَحْمد صَالح الدهان لَيْسَ بِهِ بَأْس"],[566,"وَصَالح بن مُحَمَّد بن زَائِدَة مَا أرى بِهِ بَأْسا"],[567,"وَصَالح بن مُسلم الْبكْرِيّ لَيْسَ بِهِ بَأْس ثمَّ قَالَ صَالح بن مُسلم ثِقَة"],[568,"وَقَالَ يحيى صَالح بن عمر الوَاسِطِيّ ثِقَة"],[569,"وَأَبُو الْخَلِيل يروي عَن مُجَاهِد صَالح بن أبي مَرْيَم بَصرِي ثِقَة مولى ضبيعة"],[570,"صَالح المري لَيْسَ بِهِ بَأْس"],[571,"وَأَبُو الْأَزْهَر صَالح بن دِرْهَم ثِقَة يروي عَنهُ شُعْبَة ومروان الْفَزارِيّ وَقَالَ أَحْمد لَا أعلم إِلَّا خيرا حدث عَنهُ يحيى بن سعيد"],[572,"أَبُو عَامر الخزاز اسْمه صَالح بن رستم صَادِق الحَدِيث قَالَه يحيى"],[573,"وَقَالَ صَالح بن أبي سُلَيْمَان ثِقَة"],[574,"وَصدقَة بن يسَار مكي ثِقَة"],[575,"وَقَالَ عَليّ بن الْمَدِينِيّ صَدَقَة بن عبد الله بن كثير الرَّازِيّ قد روى عَن عبد الله بن كثير وَأَيوب وَابْن جريج وَكَانَ ثِقَة"],[576,"وَقَالَ أَحْمد بن صَالح صَدَقَة بن عبد الله السمين الَّذِي روى عَنهُ عَمْرو بن أبي سَلمَة مَا بِهِ بَأْس عِنْدِي ووثقة سعيد بن عبد الْعَزِيز بِحَضْرَة الْأَوْزَاعِيّ كنيته أَبُو مُعَاوِيَة"],[577,"صَدَقَة بن يزِيد الدِّمَشْقِي صَالح الحَدِيث"],[578,"وَصدقَة بن خَالِد ثِقَة قَالَه يحيى"],[579,"وَقَالَ أَحْمد وَصدقَة بن خَالِد الَّذِي روى عَنهُ أَبُو مسْهر وَالْحكم بن مُوسَى هَذَا ثِقَة لَيْسَ بِهِ بَأْس"],[580,"وَأَبُو الزِّنْبَاع صَدَقَة بن صَالح كُوفِي ثِقَة قَالَه يحيى"],[581,"وَصدقَة بن عبيد الله الْمَازِني لَيْسَ بِهِ بَأْس قَالَه يحيى"],[582,"وَقَالَ صَفْوَان بن سليم ثِقَة قيل لَهُ يُقَارب زيد بن أسلم وَهَؤُلَاء قَالَ نعم"],[583,"وَصَفوَان بن أبي الصَّهْبَاء ثِقَة"],[584,"وَصَفوَان بن عَمْرو ثِقَة"],[585,"وصخر بن جوَيْرِية صَالح وَقَالَ مرّة أُخْرَى حَدِيثه لَيْسَ بالمتروك إِنَّمَا يتَكَلَّم فِيهِ لِأَنَّهُ يُقَال إِن كِتَابه سقط"],[586,"الصَّلْت بن بهْرَام قَالَ يحيى ثِقَة وَقَالَ أَحْمد لَيْسَ بِهِ بَأْس"],[587,"قَالَ والصلت بن دِينَار ترك النَّاس حَدِيثه قَالَ عبد الله ونهاني أبي أَن أكتب عَنهُ شَيْئا من الحَدِيث"],[588,"الصَّلْت الربعِي الَّذِي روى عَنهُ سُفْيَان لَيْسَ بِهِ بَأْس قَالَه يحيى"],[589,"قَالَ وَأَبُو الْمليح الَّذِي يروي عَنهُ مَرْوَان هُوَ صبيح أَبُو الْمليح وَهُوَ ثِقَة"],[590,"وصغدي الْكُوفِي ثِقَة يروي عَنهُ أَبُو نعيم"],[591,"وصغدي الْبَصْرِيّ لَيْسَ بِشَيْء"],[592,"قَالَ يحيى الْقطَّان فِي رِوَايَة عَليّ بن الْمَدِينِيّ عَنهُ ضرار بن مرّة ثِقَة وَهُوَ كُوفِي أَبُو سِنَان وثقة أَحْمد وَيحيى"],[593,"ضَمرَة بن سعيد ثِقَة قَالَه يحيى"],[594,"وضمرة بن ربيعَة قَالَ أَحْمد من الثِّقَات المأمونين رجل صَالح صَالح الحَدِيث لم يكن بِالشَّام رجل يُشبههُ قيل لَهُ أَيّمَا أحب إِلَيْك هُوَ أَو بَقِيَّة قَالَ لَا ضَمرَة أحب إِلَيْنَا بَقِيَّة لَا يُبَالِي عَن من أَخذ"],[595,"قَالَ وَالضَّحَّاك بن مُزَاحم ثِقَة مَأْمُون وَقَالَ فِيهِ يحيى أَيْضا ثِقَة وَقد كَانَ بخراسان"],[596,"وَالضَّحَّاك بن حمرَة ثِقَة قَالَه إِسْحَاق بن رَاهَوَيْه"],[597,"ضمام الْمعَافِرِي صَالح الحَدِيث قَالَه أَحْمد فِي رِوَايَة عبد الله ابْنه عَنهُ"],[598,"ضمام بن إِسْمَاعِيل لَيْسَ بِهِ بَأْس"],[599,"طَلْحَة بن يحيى ثِقَة قَالَه يحيى وَقَالَ عُثْمَان طَلْحَة بن يحيى أوثق من عمر بن هَارُون"],[600,"طَلْحَة الأيامي حدث عَنهُ مَالك بن أنس وَهُوَ ثِقَة قَالَه يحيى"],[601,"وَقَالَ أَحْمد بن صَالح طَلْحَة بن عبد الْملك الْأَيْلِي ثِقَة مَا سقط من أهل أَيْلَة إِلَّا الحكم بن عبد الله الْأَيْلِي الأيليون كلهم ثِقَات"],[602,"طَلْحَة الْقصار لَا بَأْس بِهِ قَالَه أَحْمد"],[603,"وَطَلْحَة بن مصرف أثنى عَلَيْهِ عبد الْملك بن أبجر"],[604,"قَالَ أَحْمد أَبُو سُفْيَان طَلْحَة بن نَافِع لَيْسَ بِهِ بَأْس"],[605,"وَطَلْحَة بن عبيد الله بن كريز الْخُزَاعِيّ ثِقَة"],[606,"وَطَلْحَة بن النَّضر روى عَنهُ بن الْمُبَارك وَزيد بن الْحباب مَا أرى بِهِ بَأْسا"],[607,"وَطَلْحَة بن أبي سعيد روى عَنهُ لَيْث بن سعد وَابْن الْمُبَارك مَا أرى بِهِ بَأْسا"],[608,"قَالَ بن معِين وَطَلْحَة بن قيس ثِقَة"],[609,"وَطَلْحَة بن الخشين الشني ثِقَة"],[610,"وطعمة الْجَعْفَرِي ثِقَة"],[611,"وطارق بن عبد الرَّحْمَن ثِقَة"],[612,"وَقَالَ الزُّهْرِيّ حَدثنِي طَاوس وَلَو رَأَيْت طَاوس علمت انه لَا يكذب وَقَالَ ميسرَة أَخْبرنِي الرِّضَا يَعْنِي طَاوس"],[613,"طلق بن غَنَّام ثِقَة صَدُوق لم يكن بالمتبحر فِي الْعلم قَالَه عُثْمَان بن أبي شيبَة"],[614,"طَيْسَلَة الْهُذلِيّ ثِقَة قَالَه يحيى لم يذكر فِيهِ شَيْئا"],[615,"نَا عبد الله بن مُحَمَّد قَالَ نامحمود بن غيلَان قَالَ نَا النَّضر بن شُمَيْل قَالَ سَمِعت شُعْبَة يَقُول شكّ بن عون أحب إِلَيّ من يَقِين غَيره وَقَالَ رجل لخَالِد بن الْحَرْث يَا أَبَا عُثْمَان مَا أحسن حَدِيث بن عون قَالَ نرى مَا حسنها فِيهَا قَالَ عُثْمَان بن أبي شيبَة بن عون ثِقَة صَحِيح الحَدِيث"],[616,"عبد الله بن دِينَار ثِقَة وَولده عبد الرَّحْمَن لَيْسَ بِذَاكَ"],[617,"عبد الله بن عبد الله الرَّازِيّ كَانَ ثِقَة وَكَانَ حجاج يَأْخُذ عَنهُ قَالَه عباد بن الْعَوام عَن حجاج وَقَالَ فِيهِ أَحْمد مااعلم إِلَّا خيرا روى عَنهُ الْأَعْمَش وَالْحكم وَابْن أبي ليلى وَسَعِيد بن مَسْرُوق"],[618,"عبد الله بن حبيب بن أبي ثَابت وَأَخُوهُ عبيد الله ثِقَات"],[619,"وَقَالَ يحيى عبد الله بن أبي نجيح ثِقَة"],[620,"وَعبد الله بن مرّة لَيْسَ بِهِ بَأْس"],[621,"وَعبد الله بن عَطاء كُوفِي ثِقَة"],[622,"وَعبد الله بن بكير كُوفِي يروي عَنهُ يعلي وَأَبُو نعيم لَيْسَ بِهِ بَأْس"],[623,"عبد الله بن مَرْوَان ثِقَة روى عَنهُ سُلَيْمَان بن عبد الرَّحْمَن وَوَثَّقَهُ"],[624,"وَقَالَ أَحْمد بن صَالح بن لَهِيعَة ثِقَة وَرفع بِهِ وَقَالَ فِيمَا رُوِيَ عَنهُ من الْأَحَادِيث وَوَقع فِيهَا تَخْلِيط يطْرَح ذَلِك التَّخْلِيط"],[625,"عبد الله بن بشر ثِقَة يَعْنِي الَّذِي روى عَنهُ معمر بن سُلَيْمَان روى عَن الْأَعْمَش أفطر الحاجم والمحجوم ثِقَة من خِيَار النَّاس قَالَه بن معِين"],[626,"قَالَ وَعبد الله بن رَجَاء يَعْنِي الْمَكِّيّ ثِقَة"],[627,"وَعبد الله بن سعيد بن أبي هِنْد ثِقَة"],[628,"وَأَبُو أويس هُوَ عبد الله بن عبد الله بن أويس ثِقَة"],[629,"وَأَبُو مُسلم الْخَولَانِيّ عبد الله بن ثوب شَامي ثِقَة"],[630,"الأرطباني بن عَم بن عون قَالَ أَحْمد مَا أرى بِهِ بَأْسا وَسَماهُ نصر بن عَليّ فَقَالَ نَا عبد الله بن حَفْص الأرطباني"],[631,"عبد الله بن سعيد بن أبي هِنْد ثِقَة قَالَه عَليّ بن الْمَدِينِيّ"],[632,"قَالَ يحيى عبد الله الْعمريّ صَالح لَيْسَ بِهِ بَأْس"],[633,"عبد الله بن سُبْرَة أَبُو سُبْرَة لَيْسَ بِهِ باس"],[634,"عبد الله بن حَنش ثِقَة"],[635,"وَعبد الله بن عصم وَهُوَ بن عصمَة ثِقَة"],[636,"عبد الله بن أبي جميلَة يحدث عَن أَبِيه لَيْسَ بِهِ بَأْس"],[637,"عبد الله بن عبيد بن عُمَيْر ثِقَة"],[638,"وَأَبُو الزِّنَاد ثِقَة واسْمه عبد الله بن ذكْوَان"],[639,"نَا مُحَمَّد بن أَحْمد بن الْحسن قَالَ نَا مُحَمَّد بن عُثْمَان بن أبي شيبَة قَالَ سَمِعت منجابا يَقُول سَمِعت أَبَا عَامر الْأَسدي يَقُول سَمِعت سُفْيَان يَعْنِي الثَّوْريّ يَقُول كَانَ بن شَوْذَب عندنَا وَنحن نعده من ثِقَات مَشَايِخنَا واسْمه عبد الله"],[640,"نَا عبد الله بن مُحَمَّد الْبَغَوِيّ قَالَ سَمِعت أَحْمد بن حَنْبَل يَقُول كَانَ عبد الله بن وهب عَالما صَالحا فَقِيها كثير الْعلم وَقَالَ أَحْمد بن حَنْبَل أخبرنَا من رأى بن أبي حَازِم يعرض لَهُ على بن وهب وَفِي رِوَايَة الْعَبَّاس بن مُحَمَّد عَن يحيى بن معِين قَالَ عبد الله بن وهب ثِقَة"],[641,"وَعبد الله بن الْعَلَاء بن زبر أَبُو زبر ثِقَة"],[642,"نَا أَحْمد بن مُحَمَّد بن سعيد قَالَ حَدثنِي عبد الله بن غَنَّام عَن حَفْص بن غياث قَالَ كنت عِنْد مُحَمَّد بن عبد الله بن نمير فجَاء رجل فَسَأَلَهُ أَيّمَا أثبت حَفْص بن غياث أَو بن إِدْرِيس فَجعل ينظر إِلَيّ ثمَّ أقبل على الرجل فَقَالَ إِذا حَدثَك حَفْص بن غياث من كِتَابه فحسبك بِهِ فَعلمت انه يقدم بن إِدْرِيس يَعْنِي عبد الله بن إِدْرِيس"],[643,"عبد الله بن خَالِد بن سعيد بن أبي مَرْيَم ثِقَة من أهل الْمَدِينَة روى حَدِيث عَليّ حفظت لكم سِتا قَالَه أَحْمد بن صَالح"],[644,"عبد الله بن يزِيد الصهباني ثِقَة"],[645,"وَعبد الله بن الْوَلِيد الْمُزنِيّ ثِقَة قَالَه يحيى"],[646,"عبد الله بن سَلمَة الْأَفْطَس سمع من هِشَام بن عُرْوَة وَيحيى بن سعيد قَالَ فِيهِ عبيد الله بن عمر القواريري لم يكن يكذب وَلَكِن كَانَ فِي لِسَانه لِبَاس"],[647,"عبد الله بن حمْرَان صَالح"],[648,"قَالَ وَأَبُو معمر صَاحب عبد الْوَارِث ثَبت ثِقَة واسْمه عبد الله بن عَمْرو"],[649,"أَبُو رَيْحَانَة قَالَ فِيهِ أَحْمد مَا أعلم إِلَّا خيرا واسْمه عبد الله بن مطر روى عَنهُ إِسْمَاعِيل وَشعْبَة وَعلي يَعْنِي بن عَاصِم وَغَيرهم وَهُوَ مَعْرُوف"],[650,"عبد الله بن أبي بكر بن مُحَمَّد وَأَبوهُ لم يزَالُوا أهل بَيت علم وَكَانَ أَبُو بكر واليا لِسُلَيْمَان"],[651,"عبد الله بن يزِيد بن ضبة شيخ ثِقَة روى عَنهُ بشر بن الْمفضل قَالَه عَليّ بن الْمَدِينِيّ"],[652,"قَالَ وَعبد الله بن حمْرَان شيخ ثِقَة مبرز"],[653,"عبد الله بن رَجَاء الْمَكِّيّ روى عَنهُ إِبْرَاهِيم وَالشَّافِعِيّ وَقَالَ الثِّقَة الْمَأْمُون الْحَافِظ"],[654,"قَالَ وَعبد الله بن عبد الرَّحْمَن الطَّائِفِي صَالح"],[655,"عبد الله بن يُونُس شيخ ثِقَة روى عَنهُ يزِيد بن هَارُون روى عَن سيار أبي الحكم قَالَه أَحْمد"],[656,"عبد الله بن يزِيد الْمَدِينِيّ يُقَال لَهُ فنطس روى عَنهُ بن أبي ذِئْب وَعلي بن ثَابت وَالثَّوْري وَأَبُو خَالِد الْأَحْمَر وَمَا أعلم إِلَّا خيرا حَدِيثه حَدِيث مقارب يَعْنِي عبد الله بن يزِيد قَالَه أَحْمد"],[657,"وَقَالَ عبد الله بن سعيد بن أبي هِنْد شيخ مدنِي ثِقَة"],[658,"وَعبد الله بن أبي لبيد مديني وَكَانَ قدم الْكُوفَة مَا أعلم لحديثه بَأْسا حدث عَنهُ أَبُو إِسْحَاق وَابْن عُيَيْنَة وَالثَّوْري وَكَانَ بن أبي لبيد يرى الْقدر"],[659,"وَعبد الله بن سُبْرَة صَالح روى عَنهُ هشيم"],[660,"وَعبد الله بن شبْرمَة ثِقَة"],[661,"وسحبل اسْمه عبد الله بن مُحَمَّد بن أبي يحيى لَيْسَ بِهِ باس"],[662,"عبد الله بن بجير أَو بحير يروي عَنهُ أَبُو دَاوُد ثِقَة قَالَه يحيى"],[663,"وَقَالَ فِي عبد الله بن عَطاء صَاحب بن زيد ثِقَة"],[664,"عبد الله بن زيد بن أسلم ثِقَة قَالَه أَحْمد"],[665,"وَقَالَ عبد الله بن يزِيد الَّذِي روى عَنهُ سُفْيَان ثِقَة وَهُوَ رجل صهباني وَهُوَ من النخع"],[666,"وَقَالَ فِي أبي نصر ثِقَة ثِقَة بن فُضَيْل حَدثنِي عَنهُ"],[667,"وَعبد الله بن يزِيد مولى الْأسود بن سُفْيَان أَبُو أَيُّوب الأفريقي روى عَنهُ بن أبي ثَابت لَيْسَ بِهِ بَأْس قَالَه يحيى"],[668,"عبد الله بن زيد بن أسلم هُوَ من أوثق ولد زيد بن أسلم قَالَه أَحْمد"],[669,"عبد الله بن جَعْفَر الزُّهْرِيّ صَالح"],[670,"وَعبد الله بن بكر الْمُزنِيّ صَالح"],[671,"وَعبد الله بن المؤمل المَخْزُومِي صَالح"],[672,"وَعبد الله بن الْمُسْتَوْرد أَبُو ضَمرَة صُوَيْلِح"],[673,"وَعبد الله بن بديل الْمَكِّيّ صَالح"],[674,"وَعبد الله بن هَوْذَة الفريعي لَا باس بِهِ"],[675,"وَعبد الله بن المبشر الْمدنِي ثِقَة"],[676,"وَعبد الله بن شريك وَعبد الله بن جبر ثقتان قَالَه كُله يحيى"],[677,"عبد الله بن شريك قَالَ أَحْمد مَا أعلم بِهِ بَأْسا"],[678,"عبد الله بن جَعْفَر ثِقَة قَالَه يحيى"],[679,"عبد الله بن يزِيد بن هُرْمُز روى عَنهُ أَبُو مسْهر وَقَالَ كَانَ ثِقَة"],[680,"أَبُو حَدْرَد عبد الله بن عَوْف مديني ثِقَة قَالَه يحيى"],[681,"أَبُو معمر عبد الله بن سَخْبَرَة كُوفِي ثِقَة قَالَه يحيى"],[682,"قَالَ وَعبد الله بن شَقِيق من خِيَار الْمُسلمين لَا يطعن فِي حَدِيثه"],[683,"وَأَبُو بكر النَّهْشَلِي ثِقَة اسْمه عبد الله بن فلَان بن قطاف"],[684,"عبد الله بن بكر السَّهْمِي صَالح نَا الْحسن بن أبي خَيْثَمَة أخبرنَا سُلَيْمَان بن أبي شيخ عَن أبي عَمْرو الطَّائِي قَالَ عرض سوار على عبد الله بن بكير السَّهْمِي أَن يوليه قَضَاء الأبلة فَأبى فَقَالَ لَهُ سوار ترفع نَفسك عَن قَضَاء الأبلة قَالَ لَا وَلَكِن ارْفَعْ علمي عَن قَضَاء الأبلة"],[685,"نَا مكرم بن أَحْمد قَالَ نَا عبد الله بن أَحْمد قَالَ قيل ليحيى بن معِين مطرف مثل القعْنبِي ومعن بن مَالك فَقَالَ كلهم ثِقَات نَا حَمْزَة بن الْحُسَيْن نَا مُحَمَّد بن عبد الله الزُّهْرِيّ نَا الحنيني قَالَ كُنَّا عِنْد مَالك بن أنس فَقيل فَجْأَة يَا أَبَا عبد الله قد قدم بن قعنب قَالَ مَتى فَقرب قدومه فَقَالَ مَالك قومُوا بِنَا إِلَى خير أهل الأَرْض نسلم عَلَيْهِ فَقَامَ فَسلم عَلَيْهِ نَا حَمْزَة بن الْحُسَيْن نَا مُحَمَّد بن مُحَمَّد أَبُو الْحُسَيْن الْعَطَّار نَا الْحُسَيْن بن مَنْصُور قَالَ سَمِعت عبد الله بن دَاوُد الْخُرَيْبِي يَقُول حَدثنِي القعْنبِي عَن مَالك وَهُوَ وَالله عِنْدِي خير من مَالك"],[686,"عبد الله بن هُبَيْرَة ثِقَة قَالَه أَحْمد"],[687,"قَالَ أَبُو بكر بن أبي شيبَة صَدُوق واسْمه عبد الله بن مُحَمَّد"],[688,"أَبُو قَتَادَة الْحَرَّانِي ثِقَة واسْمه عبد الله بن وَاقد قَالَه يحيى"],[689,"قَالَ وَأَبُو عقيل الْكُوفِي ثِقَة قَالَ أَحْمد واسْمه عبد الله بن عقيل وَفِي رِوَايَة ابْنه عبد الله عَنهُ أَبُو عقيل عبد الله بن مُحَمَّد بن عقيل الثَّقَفِيّ ثِقَة"],[690,"عمر بن نبيه لم يكن بِهِ باس قَالَه يحيى الْقطَّان فِي رِوَايَة عَليّ بن الْمَدِينِيّ"],[691,"عمر بن ثَابت الَّذِي يروي عَن أبي أَيُّوب الْأنْصَارِيّ مَعْرُوف مَشْهُور قَالَه بن عمار الْموصِلِي"],[692,"عمر بن مُحَمَّد بن زيد بن عبد الله بن عمر بن الْخطاب شيخ ثِقَة لَيْسَ بِهِ بَأْس روى عَنهُ الثَّوْريّ قَالَه أَحْمد"],[693,"قَالَ وَعمر بن سعيد بن أبي حُسَيْن ثِقَة مكي من أوثق من يَكْتُبُونَ عَنهُ الحَدِيث"],[694,"نَا عبد الله بن سُلَيْمَان ومكرم قَالَا نَا عبد الله بن أَحْمد قَالَ سَمِعت يحيى بن معِين وَذكر عمر بن عَليّ بن مقدم فَقَالَ لم أكتب عَنهُ شَيْئا واسطي نزل الْبَصْرَة وَكَانَ يُدَلس وَمَا كَانَ بِهِ بَأْس حسن الْهَيْئَة"],[695,"وَقَالَ أَحْمد عمر بن أبي زَائِدَة صَالح"],[696,"وَعمر بن الْوَلِيد شيخ ثِقَة"],[697,"وَعمر بن يُونُس ثِقَة قَالَه أَحْمد وَلم أسمع مِنْهُ"],[698,"وَعمر بن قيس الماصر ثِقَة"],[699,"وَعمر بن أَيُّوب الْموصِلِي ثِقَة"],[700,"عمر بن الرماح ثِقَة"],[701,"عمر بن عبد الرَّحْمَن الْأَبَّار روى عَنهُ عُثْمَان بن أبي شيبَة وَقَالَ كَانَ ثِقَة"],[702,"وَعمر بن نَافِع الثَّقَفِيّ حدث عَنهُ وَكِيع"],[703,"وَعمر بن عبد الله بن غفرة لَيْسَ بِهِ بَأْس وَلَكِن حَدِيثه مَرَاسِيل"],[704,"وَعمر بن سعيد صَاحب الزُّهْرِيّ روى عَنهُ عبد الرَّحْمَن بن إِسْحَاق حَدِيثه مقارب"],[705,"قَالَ يحيى عمر بن دِينَار الْكُوفِي ثِقَة"],[706,"وَعمر بن ذَر ثِقَة"],[707,"عمر بن حسان البرجمي مَا أرى بِهِ بَأْسا روى عَنهُ أَبُو مُعَاوِيَة قَالَه أَحْمد"],[708,"عمر بن نحيح شَامي ثِقَة يروي عَنهُ إِسْمَاعِيل بن عَيَّاش قَالَه يحيى"],[709,"عمر بن أبي سَلمَة صَالح ثِقَة ان شَاءَ الله قَالَه أَحْمد"],[710,"قَالَ وَعمر بن أَيُّوب قدم علينا من الْموصل لَيْسَ بِهِ بَأْس"],[711,"وعمربن بن نَبهَان يحدث عَنهُ أَبُو قُتَيْبَة وجعفر بن سُلَيْمَان ثِقَة"],[712,"وَعمر بن فروخ ثِقَة"],[713,"وَعمر بن حَفْص بن غياث صَدُوق قَالَه أَحْمد"],[714,"عمر بن رديح روى عَنهُ أَحْمد بن مُحَمَّد الصفار شيخ بن أبي خَيْثَمَة وَقد كَانَ يوثق"],[715,"عمر بن مَالك ثِقَة قَالَه أَحْمد بن صَالح"],[716,"عمر بن حبيب مكي يروي عَنهُ بن عُيَيْنَة وَعبد الرَّزَّاق وَهُوَ ثِقَة قَالَه يحيى"],[717,"وَعمر بن يحيى بن عمَارَة صَالح"],[718,"وَعمر بن عمرَان الضَّرِير صَالح"],[719,"وَعمر بن عَامر لَيْسَ بِهِ بَأْس"],[720,"وَعمر بن مُرَقع بن صَيْفِي لَيْسَ بِهِ بَأْس"],[721,"وَعمر بن الْفضل ثِقَة"],[722,"وَعمر بن سُلَيْمَان ثِقَة"],[723,"وَعمر بن عمرَان الأعمي ثِقَة"],[724,"وَعمر بن صهْبَان الْمَدِينِيّ قَالَ أَحْمد بن صَالح مَا علمت مِنْهُ إِلَّا خيرا ثِقَة مَا رَأَيْت أحدا يتَكَلَّم فِيهِ"],[725,"قَالَ وَعمر بن قيس ثِقَة لَيْسَ فِيهِ شكّ وَإِنَّمَا طعن فِيهِ من قبل الْغَلَط وَهُوَ لَا بَأْس بِهِ"],[726,"قَالَ يحيى وَعمر بن عَطاء بن أبي الخوار ثِقَة"],[727,"نَا عبد الله بن سُلَيْمَان نَا عبد الله بن أَحْمد حَدثنِي أبي نَا عبد الصَّمد نَا حزم قَالَ سمت الْحسن يَقُول وَحدث بِحَدِيث فَقَالَ لَهُ عبد الله بن بُرَيْدَة من أخْبرك بِهَذَا الحَدِيث يَا أَبَا سعيد قَالَ ثَبت عُثْمَان بن أبي الْعَاصِ قَالَ ثِقَة وَالله"],[728,"عُثْمَان بن أبي هِنْد كُوفِي ثِقَة ثِقَة قَالَه أَحْمد"],[729,"وَعُثْمَان البتي أَبُو عَمْرو لَيْسَ بِهِ بَأْس"],[730,"وَعُثْمَان الشحام لَيْسَ بِهِ باس"],[731,"وَعُثْمَان بن غياث ثِقَة ثَبت"],[732,"وَعُثْمَان بن أبي زرْعَة وَهُوَ عُثْمَان الْأَعْشَى وَهُوَ عُثْمَان بن الْمُغيرَة وَهُوَ أَبُو الْمُغيرَة الثَّقَفِيّ وَهُوَ ثِقَة"],[733,"عُثْمَان بن عبد الرَّحْمَن الْحَرَّانِي ثِقَة ثِقَة إِلَّا انه كَانَ يروي عَن الضِّعَاف والأقوياء قَالَ بن عمار كتبت عَنهُ سنة أَربع وَثَمَانِينَ وَمِائَة ثمَّ كتبت عَن النُّفَيْلِي عَنهُ سنة أَربع عشرَة ومئتين"],[734,"عُثْمَان بن الْأسود كَانَ ثبتا ثِقَة قَالَه يحيى بن سعيد فِي رِوَايَة عَليّ بن الْمَدِينِيّ عَنهُ"],[735,"عُثْمَان بن وَاقد بن مُحَمَّد بن زيد بن عبد الله بن عمر بن الْخطاب ثِقَة وَقد روى عَنهُ وَكِيع عَنهُ قَالَه يحيى"],[736,"عُثْمَان بن عَاصِم أَبُو حُصَيْن كُوفِي ثِقَة"],[737,"عُثْمَان بن الْمُغيرَة ثِقَة وَهُوَ عُثْمَان بن أبي زرْعَة وَهُوَ عُثْمَان الثَّقَفِيّ وَهُوَ عُثْمَان أَبُو الْمُغيرَة"],[738,"وَعُثْمَان البتي ثِقَة"],[739,"وَعُثْمَان بن أبي رواد أَخُو عبد الْعَزِيز بن أبي رواد روى عَنهُ البرْسَانِي وَشعْبَة وَكَانَ ثِقَة"],[740,"وَعُثْمَان بن غياث ثِقَة قَالَ بن معِين وَكَانَ يحيى بن سعيد يضعف حَدِيثه فِي التَّفْسِير"],[741,"عُثْمَان بن أبي سُلَيْمَان من ولد جُبَير بن مطعم ثِقَة"],[742,"وَعُثْمَان بن عُمَيْر أَبُو الْيَقظَان صَالح"],[743,"وَعُثْمَان بن مرّة صَالح"],[744,"وَعُثْمَان بن الْقَاسِم فِي حَدِيث الطَّائِر لَا بَأْس بِهِ فِي مَوضِع أَخ عُثْمَان بن عبد الله الْبَاهِلِيّ صَاحب عِكْرِمَة فِي الطَّائِر ثِقَة"],[745,"وَعُثْمَان بن مُوسَى بن يقطر ثِقَة"],[746,"وَعُثْمَان بن عبيد الْبَصْرِيّ ثِقَة"],[747,"عُثْمَان بن حَكِيم من أهل الْمَدِينَة رفع بِهِ أَحْمد بن صَالح وَقَالَ سَمِعت سعيد بن جُبَير قيل لَهُ هُوَ عُثْمَان بن حَكِيم بن عباد بن حنيف قَالَ لَا وَقَالَ بن معِين عُثْمَان بن حَكِيم ثِقَة"],[748,"نَا مُحَمَّد بن مُحَمَّد بن سُلَيْمَان الباغندي نَا مُحَمَّد بن يحيى بن أبي عمر الْعَدنِي قَالَ نَا سُفْيَان عَن الزُّهْرِيّ قَالَ مَا رَأَيْت هاشميا أفضل من عَليّ بن الْحُسَيْن وَلَكِن كَانَ قَلِيل الحَدِيث"],[749,"عَليّ بن نصر الْحدانِي ثِقَة قَالَه يحيى"],[750,"وَقَالَ عَليّ بن الْمُبَارك لَيْسَ بِهِ بَأْس ثِقَة وَقَالَ بن الْمَدِينِيّ عَليّ بن الْمُبَارك بَصرِي هنائي ثِقَة"],[751,"قَالَ يحيى وَعلي بن الْأَقْمَر ثِقَة"],[752,"وَعلي بن بذيمة جزري ثِقَة لَيْسَ بِهِ بَأْس"],[753,"عَليّ بن صَالح ثِقَة"],[754,"وَعلي بن ثَابت مَا روى عَن الثِّقَات ثِقَة"],[755,"عَليّ بن عبد الْأَعْلَى لَيْسَ بِهِ بَأْس روى عَنهُ هشيم قَالَه أَحْمد"],[756,"وَقَالَ عَليّ بن الْمَدِينِيّ كَانَ عَليّ بن هَاشم صَدُوقًا فِي الحَدِيث"],[757,"عَليّ بن غراب ثِقَة قَالَه يحيى وَعُثْمَان"],[758,"وَعلي بن هَاشم بن الْبَرِيد ثِقَة"],[759,"وَعلي بن الحكم الْبنانِيّ ثِقَة يروي عَنهُ أَيُّوب السختاني وَمعمر بن رَاشد وَلم يذكرهُ يحيى إِلَّا بِخَير"],[760,"عَليّ بن أبي جبلة يحدث عَنهُ ضَمرَة شيخ ثِقَة من الثِّقَات"],[761,"عَليّ بن مسْهر قَالَ أَحْمد يشبه حَدِيثه أَصْحَاب الحَدِيث"],[762,"عَليّ بن رِفَاعَة روى عَنهُ وَكِيع قَالَ وَكَانَ ثِقَة"],[763,"عَليّ بن أبي إِسْرَائِيل روى عَن أبي إِسْحَاق الْفَزارِيّ روى عَنهُ أَحْمد فَقَالَ شيخ ثِقَة"],[764,"عَليّ بن عبد الله أَبُو عَاصِم قَالَ فِيهِ أَحْمد هَذَا شيخ ثِقَة"],[765,"وَقَالَ عَليّ بن ثَابت بن أبي زيد الْأنْصَارِيّ ثِقَة ثِقَة حدث عَنهُ سعيد بن أبي عرُوبَة وَحَمَّاد بن زيد وَهُوَ أَخُو عزْرَة بن ثَابت"],[766,"وَعلي بن هَاشم مَا أرى بِهِ بَأْسا"],[767,"وَعلي بن سُوَيْد بن منجوف مَا أرى بِهِ بَأْسا وَقد حدث عَنهُ يحيى بن سعيد"],[768,"عَليّ بن مدرك ثِقَة قَالَه يحيى"],[769,"قَالَ وَعلي بن بذيمة ثِقَة وَكَانَ فِيهِ شَيْء"],[770,"عَليّ بن الْمُنْذر الطريقي ثِقَة صَدُوق قَالَه بن نمير"],[771,"حدث هِشَام بن عُرْوَة عَن عبد الرَّحْمَن بن قَاسم بِحَدِيث فَقَالَ ملئ عَن ملئ"],[772,"نَا عبد الله بن مُحَمَّد الْبَغَوِيّ نَا مَحْمُود بن غيلَان نَا أَبُو دَاوُد قَالَ وَقع رجل فِي المَسْعُودِيّ عِنْد شُعْبَة فَقَالَ اسْكُتْ فَإِنَّهُ صَدُوق"],[773,"عبد الرَّحْمَن بن سعد الْمدنِي ثِقَة"],[774,"عبد الرَّحْمَن بن عجلَان كُوفِي ثِقَة يروي ثَلَاثَة أَحَادِيث"],[775,"وَعبد الرَّحْمَن بن الْقَاسِم ثِقَة لَا يسْأَل عَنهُ قَالَه بن معِين"],[776,"وَقَالَ عبد الرَّحْمَن بن عبد الله يَعْنِي بن عتبَة المَسْعُودِيّ ثِقَة"],[777,"عبد الرَّحْمَن بن عجلَان قَالَ وَكِيع كَانَ عندنَا وَعند من أدركنا من أَصْحَابنَا ثِقَة"],[778,"عبد الرَّحْمَن بن إِبْرَاهِيم الْقَاص ثِقَة روى عَنهُ عَفَّان بن هِلَال كَانَ ينزل كرمان قَالَه يحيى"],[779,"وَعبد الرَّحْمَن بن حَرْمَلَة لَيْسَ بِهِ بَأْس قيل ليحيى يَقُولُونَ سمع من سعيد بن الْمسيب وَهُوَ صَغِير فَقَالَ لَا"],[780,"عبد الرَّحْمَن بن أبي عمار روى عَنهُ يحيى الْقطَّان قَالَ أَحْمد وَكَانَ ثِقَة وَيُقَال بن عمار بن أبي زَيْنَب ثِقَة"],[781,"عبد الرَّحْمَن بن الغسيل ثِقَة قَالَه بن معِين"],[782,"قَالَ وَعبد الرَّحْمَن بن أبي الموال ثِقَة"],[783,"وَعبد الرَّحْمَن بن أبي الرِّجَال ثِقَة"],[784,"وَعبد الرَّحْمَن بن إِسْحَاق ثِقَة مديني"],[785,"نَا مُحَمَّد بن سُلَيْمَان الباغندي قَالَ نَا مُحَمَّد بن عُثْمَان بن أبي صَفْوَان قَالَ سَمِعت عَليّ بن الْمَدِينِيّ يَقُول غير مرّة وَالله لَو أخذت فَحَلَفت بَين الرُّكْن وَالْمقَام لحلفت إِنِّي لم أر أحدا قطّ أعلم بِالْحَدِيثِ من عبد الرَّحْمَن بن مهْدي وَقَالَ مُحَمَّد بن أبي صَفْوَان سَمِعت عبد الرَّحْمَن بن مهْدي يَقُول اخْتلفت الى حَمَّاد بن زيد زَمَانا وَمَا بِي اليه حَاجَة وَقَالَ أَحْمد عبد الرَّحْمَن بن مهْدي من معادن الصدْق"],[786,"وَقَالَ بن معِين عبد الرَّحْمَن بن الْقَاسِم ثِقَة"],[787,"وَعبد الرَّحْمَن بن حسان ثِقَة"],[788,"وَعبد الرَّحْمَن بن حميد الَّذِي روى عَنهُ الدَّرَاورْدِي ثِقَة"],[789,"وَعبد الرَّحْمَن بن مُعَاوِيَة أَبُو الْحُوَيْرِث روى عَنهُ بن عُيَيْنَة مديني ثِقَة"],[790,"وَعبد الرَّحْمَن بن يزِيد بن جَابر وَهُوَ أَخُو يزِيد بن جَابر ثقتان"],[791,"وَعبد الرَّحْمَن بن ثَابت بن ثَوْبَان لَيْسَ بِهِ بَأْس"],[792,"وَعبد الرَّحْمَن بن أبي الرِّجَال ثِقَة روى عَنهُ الحكم بن مُوسَى وَكَانَ بِالشَّام"],[793,"وَعبد الرَّحْمَن بن بديل بن ميسرَة لَيْسَ بِهِ باس وَقَالَ مرّة أُخْرَى عبد الرَّحْمَن بن بديل عَن أَبِيه إِن الله أهلين روى عَنهُ بن مهْدي ضَعِيف"],[794,"عبد الرَّحْمَن بن فضَالة أَخُو مبارك شيخ ثِقَة من الثِّقَات"],[795,"وَعبد الرَّحْمَن بن شُرَيْح أَبُو شُرَيْح لَيْسَ بِهِ بَأْس"],[796,"وَقَالَ عُثْمَان بن أبي شيبَة فِي عبد الرَّحْمَن الْمحَاربي هُوَ صَدُوق وَلَكِن هُوَ كَذَا ضعفه"],[797,"عبد الرَّحْمَن بن الْعُرْيَان أَبُو الْحسن روى عَنهُ إِبْرَاهِيم بن عبد الله وَقَالَ ثِقَة مَأْمُون"],[798,"وَقَالَ يحيى بن ثَوْبَان أَصله خراساني نزل الشَّام وَمَا ذكره يحيى الا بِخَير"],[799,"قَالَ وَعبد الرَّحْمَن أَو عبيد الرَّحْمَن بن فضَالة أَخُو مبارك بن فضَالة لَيْسَ بِهِ باس"],[800,"وَعبد الرَّحْمَن السراج بَصرِي ثِقَة"],[801,"وَأَبُو سعيد مولى بني هَاشم بَصرِي كَانَ ينزل مَكَّة وَهُوَ ثِقَة واسْمه عبد الرَّحْمَن"],[802,"وَعبد الرَّحْمَن بن عُثْمَان البكراوي"],[803,"قَالَ يحيى أثبت النَّاس فِي هِشَام بن عُرْوَة عبد الرَّحْمَن بن أبي الزِّنَاد"],[804,"قَالَ وَعبد الرَّحْمَن بن زِيَاد بن أنعم الأفريقي لَيْسَ بِهِ بَأْس وَفِيه ضعف وَهُوَ أحب إِلَيّ من أبي بكر بن أبي مَرْيَم الغساني"],[805,"عبد الرَّحْمَن بن مُحَمَّد بن أبي الرِّجَال ثِقَة قَالَه أَحْمد"],[806,"عبد الرَّحْمَن بن إِسْحَاق الْمَدِينِيّ لَيْسَ بِهِ بَأْس"],[807,"قَالَ وَعبد الرَّحْمَن بن عبد الله بن مُحَمَّد بن عبد الرَّحْمَن بن أبي بكر الصّديق لَا أعلم إِلَّا خيرا وَهُوَ الَّذِي يُقَال لَهُ عَتيق روى عَنهُ أَبُو حزرة وَمُحَمّد بن إِسْحَاق"],[808,"وَعبد الرَّحْمَن بن مُحَمَّد الْمحَاربي الْكُوفِي ثِقَة"],[809,"وَعبد الرَّحْمَن بن غَزوَان قراد كنيته أَبُو نوح لَيْسَ بِهِ باس"],[810,"وَعبد الرَّحْمَن بن عبد الْملك بن أبجر ثِقَة"],[811,"وَعبد الرَّحْمَن بن أبي الموال صَالح"],[812,"وَعبد الرَّحْمَن بن وردان"],[813,"وَعبد الرَّحْمَن بن الْعُرْيَان الْحَارِثِيّ ثِقَة"],[814,"وَعبد الرَّحْمَن بن علقم الَّذِي حدث عَنهُ سُفْيَان قَالَه فِيهِ بن مهْدي كَانَ من الْأَثْبَات الثِّقَات"],[815,"وَقَالَ يحيى وَعبد الرَّحْمَن بن عبد الله بن كثير صَالح"],[816,"وَعبد الرَّحْمَن بن حميد بن عبد الرَّحْمَن بن عَوْف لَا باس بِهِ"],[817,"وَعبد الرَّحْمَن بن العداء ثِقَة"],[818,"وَعبد الرَّحْمَن بن مُحَمَّد بن أبي حَاطِب ثِقَة"],[819,"نَا إِسْحَاق بن مُوسَى الرَّمْلِيّ قَالَ سَمِعت مُحَمَّد بن عَوْف الْحِمصِي يَقُول سَمِعت الْوَلِيد بن عتبَة يَقُول احترقت كتب الْأَوْزَاعِيّ زمن الرجفة ثَلَاثَة عشر فنداقا فَأَتَاهُ رجل بنسخها فَقَالَ لَهُ يَا أَبَا عَمْرو هَذِه نُسْخَة كتابك وإصلاحك بِيَدِك فَمَا عرض لشَيْء مِنْهَا"],[820,"قَالَ يحيى عبد الرَّحْمَن بن صَالح ثِقَة إِلَّا إِنَّه يتشيع"],[821,"وَقَالَ أَحْمد عَبَّاس بن عبد الله بن معبد بن عَبَّاس مديني لَيْسَ بِهِ باس وَقَالَ يحيى ثِقَة"],[822,"عَبَّاس بن الْفضل الْأنْصَارِيّ ثِقَة وَلَكِن حدث بِحَدِيث أنكروه عَلَيْهِ قَالَه يحيى"],[823,"وَقَالَ عَبَّاس الْجريرِي ثِقَة وَلَيْسَ هُوَ أَخا سعيد الْجريرِي هُوَ رجل آخر وهومن الجريريين"],[824,"قَالَ أَحْمد الْعَبَّاس بن ذريح لَيْسَ بِهِ بَأْس"],[825,"وَقَالَ يحيى قد روى عَوْف عَن شيخ بَصرِي يُقَال لَهُ عَبَّاس الْعمي وَلَيْسَ بِهِ بَأْس"],[826,"وَقَالَ أَبُو نعيم مَا كَانَ بِالْكُوفَةِ مِمَّن يتشيع أوثق من عَاصِم بن حميد الْخياط"],[827,"وَقَالَ عُثْمَان بن أبي شيبَة عَاصِم الْأَحول ثَبت"],[828,"عَاصِم بن بَهْدَلَة ثِقَة رجل صَالح خير قَالَه أَحْمد بن حَنْبَل عَاصِم بن أبي النجُود قَالَ بن معِين لَيْسَ بِهِ بَأْس"],[829,"نَا نصر بن الْقَاسِم الْفَرَائِضِي انا إِسْحَاق بن أبي إِسْرَائِيل قَالَ نَا حَمَّاد بن زيد قَالَ رُبمَا أتيت عَاصِم بن بَهْدَلَة وَهُوَ فِي الْمَسْجِد يُصَلِّي كَأَنَّهُ خَشَبَة مَنْصُوبَة قَالَ بن معِين عَاصِم بن بَهْدَلَة ثِقَة لَا بَأْس بِهِ وَالْأَعْمَش احفظ مِنْهُ"],[830,"وَعَاصِم بن ضَمرَة ثِقَة شيعي روى عَنهُ أَبُو إِسْحَاق"],[831,"وَعَاصِم بن كُلَيْب ثِقَة مَأْمُون وَقَالَ أَحْمد بن صَالح عَاصِم بن كُلَيْب يعد من وُجُوه الْكُوفِيّين من الثِّقَات"],[832,"وَقَالَ أَرْبَعَة إخْوَة ثِقَات عبيد الله وَعبد الله وَعَاصِم وَأَبُو بكر بَنو عمر بن حَفْص بن عَاصِم بن عمر بن الْخطاب"],[833,"عَاصِم بن عمر بن عَليّ لَيْسَ بِهِ بَأْس قَالَه يحيى"],[834,"عَاصِم بن ضَمرَة قَالَ عُثْمَان هُوَ أحب إِلَيّ من الْحَارِث كَانَ الْحَارِث ضَعِيفا"],[835,"نَا عبد الله بن مُحَمَّد الْبَغَوِيّ نامحمود بن غيلَان نَا يحيى بن آدم نَا الْحسن بن ثَابت قَالَ سَمِعت الْأَعْمَش يعجب من حَفْص أبي إِسْحَاق لرجاله الَّذين يروي عَنْهُم وَقَالَ الْأَعْمَش كَانَ أَصْحَاب عبد الله إِذا رَأَوْا أَبَا إِسْحَاق قَالُوا هَذَا عَمْرو الْقَارِي هَذَا عَمْرو الَّذِي لَا يلْتَفت"],[836,"قَالَ بن معِين عَمْرو بن شُعَيْب ثِقَة قيل لَهُ فِيمَا روى عَن أَبِيه قَالَ كَذَا يَقُول أَصْحَاب الحَدِيث قيل لَهُ كَانَت صحيفَة قَالَ نعم وَقَالَ أَحْمد بن صَالح عَمْرو بن شُعَيْب سمع من أَبِيه عَن جده وَكله سَماع وَعَمْرو بن شُعَيْب ثَبت وَأَحَادِيثه تقوم مقَام الثبت"],[837,"وَفِي رِوَايَة عَبَّاس عَن يحيى قَالَ عَمْرو بن قيس السكونِي هُوَ الَّذِي روى عَنهُ إِسْمَاعِيل بن عَيَّاش وَهُوَ ثِقَة"],[838,"وَفِي رِوَايَة أُخْرَى عَنهُ عَمْرو بن عَامر روى عَن أنس لَيْسَ بِهِ بَأْس ثِقَة"],[839,"وَعَمْرو بن عُثْمَان بن موهب ثِقَة لَيْسَ بِهِ بَأْس"],[840,"وَعَمْرو بن أبي قيس ثِقَة"],[841,"عَمْرو بن أبي قيس رازي لَا بَأْس بِهِ كَانَ يهم فِي الحَدِيث قَلِيلا روى عَنهُ أُولَئِكَ الرازيون قَالَه عُثْمَان"],[842,"أَبُو نعَامَة الْعَدوي قَالَ يحيى هُوَ عَمْرو بن عِيسَى بَصرِي ثِقَة روى عَنهُ وَكِيع بن الْجراح وَعبد الْوَارِث ومروان"],[843,"وَقَالَ أَحْمد بن صَالح عَمْرو بن مَالك الْجَنبي ثِقَة"],[844,"نَا الْحُسَيْن بن صَدَقَة قَالَ نَا أَحْمد بن أبي خَيْثَمَة انا أَبُو الْفَتْح قَالَ قَالَ سُفْيَان قَالُوا لعطاء بِمن تَأْمُرنَا قَالَ بِعَمْرو بن دِينَار"],[845,"وَقَالَ بن معِين روى عِيسَى بن يُونُس ووكيع عَن رجل يُقَال لَهُ عَمْرو بن مَنْصُور المشرقي وَكَانَ كوفيا ثِقَة"],[846,"وَقَالَ عَمْرو بن الْوَلِيد الأغضف كَانَ على قَضَاء فَارس وَقد أدركناه لَيْسَ بِهِ باس"],[847,"وَعَمْرو بن أبي حَكِيم الوَاسِطِيّ يروي عَنهُ هشيم وَهُوَ ثِقَة"],[848,"وَعَمْرو بن مهَاجر ثِقَة قَالَه أَحْمد وَيحيى"],[849,"وَعَمْرو العنقري يروي عَنهُ بن جريج قَالَ يحيى لَيْسَ بِهِ باس وَقَالَ أَحْمد ثِقَة"],[850,"عَمْرو بن قَتَادَة اليمامي ثِقَة مَأْمُون روى عَنهُ القدماء قَالَه يحيى"],[851,"وَقَالَ فِي أبي السَّوْدَاء واسْمه عَمْرو بن عمرَان كُوفِي ثِقَة"],[852,"نامكرم قَالَ نَا عبد الله قَالَ قَالَ لي أبي قَالَ أَبُو قطن وَكَانَ ثبتا مَا أعرت كتابي أحدا قطّ واسْمه عَمْرو بن الْهَيْثَم وَقَالَ يحيى أَبُو قطن ثِقَة"],[853,"قَالَ أَحْمد وَأَبُو الزَّعْرَاء شيخ كُوفِي وَهُوَ ثِقَة وَهُوَ بن أخي أبي الْأَحْوَص من الثِّقَات اسْمه عَمْرو بن عَمْرو"],[854,"وَعَمْرو بن هرم ثِقَة"],[855,"قَالَ أَحْمد عَمْرو بن الْحجَّاج وَقَالَ بَعضهم بن أبي الْحجَّاج حَدثنَا عَنهُ بن علية وَيحيى وَابْن سَوَاء أرَاهُ شَيخا ثِقَة"],[856,"وروى بن عُيَيْنَة عَن عَمْرو بن يحيى بن قمطة وَكَانَ من خِيَار أهل مَكَّة"],[857,"وَقَالَ يزِيد بن هَارُون عَمْرو بن عون مِمَّن يزْدَاد عندنَا كل يَوْم خيرا"],[858,"وَقَالَ يحيى عَمْرو بن أبي حَكِيم الوَاسِطِيّ يروي عَنهُ هشيم وَهُوَ ثِقَة"],[859,"وَعَمْرو بن مَرْزُوق بَصرِي لَيْسَ بِهِ باس وَهُوَ واشحي"],[860,"وَعَمْرو بن سعيد بن يحيى الْقرشِي صَالح"],[861,"وَعَمْرو بن أبي وهب صَالح"],[862,"عَمْرو بن أبي حَكِيم ثِقَة صَالح"],[863,"وَعَمْرو بن عَاصِم ثِقَة وَفِي رِوَايَة أُخْرَى صَالح"],[864,"عَامر بن عبد الْوَاحِد الْأَحول بَصرِي وَلَيْسَ بِهِ باس قَالَه يحيى قَالَ وَهُوَ كل عَامر يروي عَنهُ البصريون لَيْسَ غَيرهم"],[865,"قَالَ يحيى بن سعيد وَذكر عَامر صَاحب العريف فَقَالَ كَانَ ثِقَة"],[866,"عَامر بن شفي شيخ روى عَنهُ عبيد الله بن عمر وَهُوَ عِنْد يحيى ثِقَة إِن شَاءَ الله"],[867,"عَامر بن عبد الله بن الزبي من أوثق النَّاس"],[868,"عَامر بن صَالح الزبيرِي ثِقَة لم يكن صَاحب كذب قَالَه أَحْمد"],[869,"عَامر بن السبط روى عَنهُ عايذ بن حبيب قَالَ يحيى صَالح وَعَن يحيى بن سعيد إِنَّه ثِقَة ثَبت"],[870,"قَالَ يحيى وعامر بن عُبَيْدَة ثِقَة"],[871,"قَالَ وَأَبُو الصَّلْت الْهَرَوِيّ ثِقَة صَدُوق إِلَّا أَنه يتشيع واسْمه عبد السَّلَام بن صَالح"],[872,"عمار بن أبي عمار أثنى عَلَيْهِ حَمَّاد وَقَالَ أَحْمد هُوَ ثِقَة وَوَثَّقَهُ يحيى أَيْضا"],[873,"وَأَبُو هَاشم الزَّعْفَرَانِي هَكَذَا يَقُول البصريون لَا يَقُولُونَ الزعافري ثِقَة وَهُوَ عمار بن عمَارَة"],[874,"وَقَالَ عمار بن مُحَمَّد بن أُخْت سُفْيَان الثَّوْريّ لَيْسَ بِهِ بَأْس وَقَالَ عَليّ بن حجر كَانَ عمار بن مُحَمَّد ثبتا ثِقَة"],[875,"عمار بن زُرَيْق ثِقَة قَالَه عَليّ بن الْمَدِينِيّ"],[876,"عمار بن زادان لَيْسَ بِهِ بَأْس قَالَه يحيى"],[877,"قَالَ وَعمارَة بن الْقَعْقَاع ثِقَة"],[878,"وَعمارَة بن أبي حَفْصَة ثِقَة"],[879,"وَعمارَة بن غزيَّة لَيْسَ بِهِ بَأْس"],[880,"وَعمارَة بن زَاذَان وَعمارَة بن مهْرَان لَيْسَ بهما بَأْس"],[881,"وَعمارَة بن أبي حَفْصَة شيخ ثِقَة قَالَه أَحْمد"],[882,"قَالَ وَعمارَة بن زَاذَان الصيدلاني لَيْسَ بِهِ بَأْس"],[883,"عمَارَة أَبُو سعيد العابد قَالَ أَحْمد بَلغنِي انه عبد الله حَتَّى صَار جلدا على عظم من الْعِبَادَة وَهُوَ شيخ ثِقَة من أَصْحَاب الْحسن ثِقَة بَصرِي"],[884,"قَالَ وَعمارَة بن غزيَّة الْأَنْصَارِيَّة ثِقَة"],[885,"وَعمارَة بن عُمَيْر ثِقَة وَزِيَادَة"],[886,"عمَارَة الإسْكَنْدراني يروي بن الْمُبَارك عَنهُ عَن عِكْرِمَة فِي التَّفْسِير شيخ ثِقَة قَالَه يحيى"],[887,"وَقَالَ عبد الْملك بن قدامَة الجُمَحِي ثِقَة"],[888,"عبد الْملك بن أبي بشير ثِقَة وَكَانَ أَصله بَصرِي قَالَه يحيى بن سعيد الْقطَّان"],[889,"عبد الْملك بن أبي كثير ثِقَة لم يكن بِهِ بَأْس قَالَ يحيى بن معِين"],[890,"عبد الْملك بن أخي الْقَعْقَاع بن شور حَدِيثه عَن بن عمر عَن النَّبِي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي النَّبِيذ قَالَ فِيهِ بن صَالح لَا يجوز أَن يَأْتِي إِلَى رجل مثل هَذَا قد روى عَنهُ الثِّقَات فيضعفه بِلَا حجَّة وَلم يُضعفهُ أحد"],[891,"وَعبد الْملك بن أبي بشير لَيْسَ بِهِ بَأْس"],[892,"بن جريج ثِقَة حجَّة قَالَه عُثْمَان"],[893,"وَقَالَ أَبُو عَامر الْعَقدي ثِقَة عَاقل يَعْنِي عبد الْملك بن عَمْرو"],[894,"أَبُو سَلام الْحَنَفِيّ هُوَ عبد الْملك بن سَلام الْمَدَائِنِي وَهُوَ ثِقَة يروي عَنهُ يزِيد بن هَارُون قَالَه يحيى"],[895,"عبد الْملك بن أبي سُلَيْمَان ثِقَة قَالَه أَحْمد"],[896,"عبد الْملك بن أعين كُوفِي لَيْسَ بِهِ بَأْس قَالَه يحيى"],[897,"بن أبي غنية شيخ ثِقَة يُقَال لَهُ هنيَّة وَمَا رَأَيْت عَلَيْهِ قَمِيصًا مَرْفُوعا قَالَه أَحْمد"],[898,"وَقَالَ يحيى الْأَصْمَعِي ثِقَة واسْمه عبد الْملك بن قريب"],[899,"عبد الْملك بن أبجر ثِقَة قَالَه أَحْمد"],[900,"عبد الْملك بن الْوَلِيد بن معدان صَالح"],[901,"عبد الْملك بن حسن الْحَارِثِيّ صَالح قَالَه يحيى"],[902,"عبد الحميد بن عبد الْعَزِيز بن أبي رواد ثِقَة قَالَه يحيى"],[903,"عبد الحميد بن رَافع شيخ ثِقَة روى عَنهُ الثَّوْريّ قَالَه يحيى"],[904,"وَقَالَ فِي عبد الحميد بن جَعْفَر الْأنْصَارِيّ لَيْسَ بِهِ بَأْس وَقَالَ فِي رِوَايَة أُخْرَى ثِقَة يرْمى بِالْقدرِ"],[905,"وَعبد الحميد بن بهْرَام ثِقَة كَانَت عِنْده صحيفَة لَيْسَ بِهِ بَأْس"],[906,"وَأَبُو يحيى الْحمانِي ثِقَة وَابْنه ثِقَة وَأَبُو يحيى اسْمه عبد الحميد"],[907,"وَقَالَ أَحْمد بن صَالح عبد الحميد بن بهْرَام ثِقَة يُعجبنِي حَدِيثه حَدِيث صَحِيح أَحَادِيثه عَن شهر بن حَوْشَب صَحِيحَة"],[908,"عبد الحميد بن أبي جَعْفَر الْفراء أثنى عَلَيْهِ شريك خيرا قَالَ أَحْمد عبد الحميد بن جَعْفَر ثِقَة"],[909,"قَالَ وَعبد الحميد صَاحب الزيَادي هُوَ عبد الحميد بن كرديد وَهُوَ ثِقَة"],[910,"قَالَ وَكَانَ بِالشَّام رجل من أَصْحَاب الْأَوْزَاعِيّ يُقَال لَهُ بن أبي الْعشْرين وَكَانَ ثِقَة واسْمه عبد الحميد"],[911,"عبد الحميد بن سُهَيْل بن عبد الرَّحْمَن بن عَوْف ثِقَة قَالَه بن معِين"],[912,"وَعبد الحميد بن الْحسن الْهِلَالِي لَيْسَ بِهِ بَأْس"],[913,"عبد ربه بن عبيد أَبُو كَعْب ثِقَة"],[914,"قَالَ أَحْمد عبد ربه بن بارق الْحَنَفِيّ قَالَ هُوَ بن أخي سماك الْحَنَفِيّ وَمَا بِهِ بَأْس"],[915,"عبد ربه بن أبي رَاشد ثِقَة قَالَه أَحْمد"],[916,"أَبُو شهَاب الحناط عبد ربه بن نَافِع ثِقَة قَالَه يحيى وَقَالَ بن عمار إِنَّمَا كَانَ يطعن فِيهِ من أجل النَّبِيذ انه كَانَ يشرب النَّبِيذ"],[917,"عبد ربه السَّعْدِيّ يكنى أَبَا نعَامَة وَهُوَ ثِقَة مَأْمُون وَهُوَ أَخُو يحيى بن سعيد الْأنْصَارِيّ قَالَه يحيى"],[918,"وَقَالَ عبد ربه القصاب ثِقَة"],[919,"قَالَ يحيى اسْم أبي عبد الله الجدلي فلَان بن عبد من قيس كُوفِي ثِقَة وَقَالَ أَحْمد اسْمه عبد بن عبد"],[920,"قَالَ يحيى عبد الْوَاحِد بن أَيمن ثِقَة"],[921,"وَأَبُو عُبَيْدَة الْحداد عبد الْوَاحِد بن وَاصل سدوسي ثِقَة"],[922,"وَعبد الْوَاحِد بن صَفْوَان بَصرِي لَيْسَ بِهِ بَأْس"],[923,"عبد الْوَاحِد الْمَالِكِي ثِقَة"],[924,"عبد الْعَزِيز بن صُهَيْب الْبنانِيّ قَالَ أَحْمد ثِقَة من الثِّقَات"],[925,"وَعبد الْعَزِيز بن رفيع ثِقَة"],[926,"وَعبد الْعَزِيز بن عمر بن عبد الْعَزِيز ثِقَة ثِقَة قَالَه أَحْمد وَيحيى"],[927,"عبد الْعَزِيز بن مُوسَى اللاحوني قَرْيَة بحمص ثِقَة ثِقَة ورى عَنهُ مُحَمَّد بن عَوْف وَأثْنى عَلَيْهِ"],[928,"قَالَ بن معِين بن أبي حَازِم والداروردي لَيْسَ بهما بَأْس وَاسم كل وَاحِد مِنْهُمَا عبد الْعَزِيز قَالَ يحيى عبد الْعَزِيز الدَّرَاورْدِي مَا روى من كِتَابه فَهُوَ أثبت من حفظه"],[929,"قَالَ أَحْمد بن صَالح عبد الْعَزِيز بن عَيَّاش"],[930,"نَا عبد الْعَزِيز بن عبد الصَّمد وَلم يكن بِهِ بَأْس وَقَالَ بن أبي خَيْثَمَة نَا عبيد الله قَالَ حَدثنِي عبد الْعَزِيز بن عبد الصَّمد الْعمي وَكَانَ حَافِظًا"],[931,"أَبُو مودود الْمَدِينِيّ عبد الْعَزِيز بن أبي سُلَيْمَان ثِقَة ثِقَة"],[932,"وَأَبُو مودود الْبَصْرِيّ واسْمه بَحر بن مُوسَى قَالَه يحيى"],[933,"وَقَالَ عبد الْعَزِيز بن حَكِيم كُوفِي لَيْسَ بِهِ بَأْس"],[934,"وَعبد الْعَزِيز بن الْمُخْتَار بَصرِي ثِقَة"],[935,"وَعبد الْعَزِيز الْمَاجشون صَالح"],[936,"وَعبد الْعَزِيز بن صُهَيْب ثِقَة"],[937,"وَعبد الْعَزِيز بن ربيع وَأَبُو الْعَوام الْبَاهِلِيّ ثِقَة"],[938,"وَعبد الْعَزِيز بن مُسلم الْقَسْمَلِي ثِقَة"],[939,"وَعبيد الله بن عمر عَن الْقَاسِم بن مُحَمَّد وَالقَاسِم بن مُحَمَّد عَن عَائِشَة مشبك بِالذَّهَب"],[940,"عبيد الله بن الْعيزَار ثِقَة قَالَه يحيى بن سعيد فِي رِوَايَة بن الْمَدِينِيّ"],[941,"قَالَ يحيى عبيد الله بن عمر من الثِّقَات"],[942,"وَعبيد الله بن اياد بن لَقِيط ثِقَة وَقَالَ أَبُو نعيم كَانَ عبيد الله بن اياد بن لَقِيط ثِقَة وَكَانَ عريف قومه وَكَانُوا قد صيروا إِلَيْهِ حفر الخَنْدَق بِالْكُوفَةِ فَكَانَ يَجِيء فيحفرون قدامه وَكَانَت لَهُ صحيفَة فِيهَا أَحَادِيثه فَإِذا جَاءَهُ إِنْسَان رمى إِلَيْهِ بِتِلْكَ الصَّحِيفَة فَكتب مِنْهَا مَا أَرَادَ وَقَرَأَ عَلَيْهِ"],[943,"عبيد الله بن عبد الْملك أَبُو كُلْثُوم الْعَبْدي ثِقَة روى عَنهُ القواريري وَوَثَّقَهُ"],[944,"وَقَالَ يحيى عبيد الله بن عبد الرَّحْمَن بن موهب لَيْسَ بِهِ بَأْس"],[945,"وَعبد الله بن أبي رَافع ثِقَة"],[946,"وَعبيد الله بن الْأَخْنَس لَيْسَ بِهِ بَأْس يروي عَنهُ سعيد بن أبي عرُوبَة وَكَانَ خرازا وكنيته أَبُو مَالك"],[947,"قَالَ أَحْمد فِي عبيد الله بن أبي جَعْفَر كَانَ يتفقه لَيْسَ بِهِ بَأْس"],[948,"وَعبيد الله بن أبي زِيَاد القداح صَالح لَيْسَ بِهِ بَأْس"],[949,"وَعبيد الله بن أبي بكر بن أنس ثِقَة"],[950,"عبيد الله بن مُوسَى ثِقَة قَالَه يحيى"],[951,"عبيد الله بن مُوسَى صَدُوق ثِقَة وَكَانَ يضطرب فِي حَدِيث سُفْيَان اضطرابا قبيحا قَالَه عُثْمَان"],[952,"وَقَالَ عبيد الله الْأَشْجَعِيّ ثِقَة كَانَ أثبت النَّاس فِي الثَّوْريّ إِذا أخرج كِتَابه"],[953,"عبيد الله القواريري ثِقَة قَالَه يحيى"],[954,"قَالَ وَعبيد الله بن شميط ثِقَة"],[955,"وَعبيد الله بن أبي بكر ثِقَة"],[956,"وَعبيد الله بن أبي يزِيد ثِقَة"],[957,"وَعبيد الله بن عبد الرَّحْمَن بن موهب صَالح"],[958,"وَعبيد الله بن أبي زِيَاد صَالح"],[959,"ثَنَا عبد الله بن مُحَمَّد الْبَغَوِيّ قَالَ ثَنَا القواريري قَالَ ثَنَا عبيد الله بن عبد الْملك أَبُو كُلْثُوم الْعَبْدي"],[960,"عبيد بن أبي وسيم ثِقَة قَالَه يحيى"],[961,"وَعبيد بن سعيد الْقرشِي أَخُو يحيى بن سعيد الْأمَوِي لَيْسَ بِهِ بَأْس ثِقَة قَالَه يحيى قد رَأَيْته كَانَ أَصْغَر من أبي أَحْمد الزبيرِي"],[962,"أَبُو صَالح الَّذِي روى عَنهُ بشر بن سعيد اسْمه عبيد مولى السفاح مديني ثِقَة"],[963,"عبيد بن نسطاس يروي عَن أبي عُبَيْدَة عَن عبيد الله هُوَ نخعي كُوفِي ثِقَة"],[964,"عبيد الله بن الْحسن ثِقَة"],[965,"وَعبيد الصَّمد صُوَيْلِح"],[966,"وَعبد الرَّحْمَن بن فضَالة لَيْسَ بِهِ بَأْس"],[967,"وَعبد الْمُؤمن بن عبيد الله السدُوسِي كنيته أَبُو عُبَيْدَة وَهُوَ ثِقَة"],[968,"عبد الْمُؤمن بن الْقَاسِم ثِقَة وَهُوَ أَخُو أبي مَرْيَم روى عَنهُ قيس وَشريك قَالَه مُحَمَّد بن عبد الله بن نمير"],[969,"قَالَ يحيى عبد الْمُؤمن بن أبي شراعة ثِقَة"],[970,"عبد الْوَارِث قَالَ القواريري لَوْلَا الرَّأْي لم يكن بِهِ بَأْس وَقَالَ بن علية إِذا حَدثَك عبد الْوَارِث بِشَيْء فَشد يدك بِهِ"],[971,"عبد الْمجِيد بن أبي رواد ثِقَة لَيْسَ بِهِ بَأْس"],[972,"قَالَ يحيى عبد الْكَرِيم بن مَالك الْجَزرِي ثِقَة"],[973,"وَالْآخر لَيْسَ بِشَيْء يَعْنِي الْبَصْرِيّ"],[974,"عُبَيْدَة بن معتب لَا بَأْس بِهِ قَالَه عُثْمَان بن أبي شيبَة"],[975,"وَعبد الرَّحْمَن بن سُلَيْمَان ثِقَة قَالَه يحيى وَقَالَ عُثْمَان هُوَ ثِقَة صَدُوق لَيْسَ بِحجَّة"],[976,"عبد الْوَهَّاب بن عبد الْعَزِيز ثِقَة"],[977,"وَعبد الْوَهَّاب بن عَطاء الْخفاف ثِقَة قَالَه يحيى وَقَالَ عُثْمَان لَيْسَ بِكَذَّابٍ وَلَكِن لَيْسَ هُوَ مِمَّن يتكل عَلَيْهِ"],[978,"وَقَالَ يحيى لَيْسَ بِعَبْد الصَّمد بن حبيب بَأْس"],[979,"وَعبد الصَّمد بن النُّعْمَان الْبَزَّاز جَار مُعَاوِيَة بن عَمْرو ثِقَة فِي الحَدِيث"],[980,"عبد الصَّمد بن معقل ثِقَة"],[981,"عبد الْخَالِق بن سَلمَة الشَّيْبَانِيّ كَذَا قَالَ بن علية وَيزِيد بن هَارُون بن سَلمَة ثِقَة"],[982,"عبد الْجَبَّار بن عَمْرو الْأَيْلِي ثِقَة فِي حدثيه تَخْلِيط وَخلاف قَالَه أَحْمد بن صَالح"],[983,"عبد الْجَبَّار بن الْعَبَّاس يَعْنِي الشبامي لَيْسَ بِهِ بَأْس"],[984,"أَبُو مَرْيَم يحفظ قَالَه شُعْبَة"],[985,"وَقَالَ عَنْبَسَة الْوراق ثِقَة يروي عَنهُ يحيى بن سعيد الْقطَّان"],[986,"وعنبسة قَاضِي الرّيّ ثِقَة"],[987,"وعنبسة الْأَعْوَر الْأمَوِي ثِقَة"],[988,"وعنبسة أَخُو يحيى بن سعيد الْأمَوِي ثِقَة"],[989,"وعنبسة الْعَطَّار يروي عَنهُ وهيب الثَّقَفِيّ وَهُوَ بَصرِي ثِقَة"],[990,"قَالَ وعنبسة بن سعيد بن كثير كُوفِي وَهُوَ ثِقَة وَلَيْسَ هُوَ الْأمَوِي يروي عَنهُ أَبُو النَّضر هَاشم بن الْقَاسِم"],[991,"وعنبسة بن عبد الْوَاحِد الْكُوفِي ثِقَة"],[992,"وَعبد السَّلَام بن عجلَان ثِقَة"],[993,"وَعبد القاهر بن السّري صَالح"],[994,"وَعبيد الله بن عَمْرو الرقي ثِقَة"],[995,"وَعبد الْجَلِيل بن عَطِيَّة بَصرِي يروي عَنهُ بن مهْدي وَعبد الصَّمد وَهُوَ ثِقَة"],[996,"وَسُئِلَ الشّعبِيّ عَن عَلْقَمَة بن مرْثَد فَقَالَ ثِقَة قَالَه أَحْمد وَيحيى"],[997,"عبد الْأَعْلَى بن عبد الْأَعْلَى ثِقَة قَالَه يحيى وكنيته أَبُو همام"],[998,"قَالَ أَحْمد عبد الْأَعْلَى التَّيْمِيّ رجل صَالح حدث عَنهُ مسعر والمسعودي"],[999,"أَبُو مسْهر عبد الْأَعْلَى دمشقي ثِقَة قَالَه يحيى"],[1000,"وَعبد الْأَعْلَى صَالح"],[1001,"عباد بن كثير الشَّامي روى عَن زِيَاد بن الرّبيع قَالَ وَكَانَ ثِقَة"],[1002,"عباد بن كثير الرَّمْلِيّ خَواص ثِقَة قَالَه يحيى"],[1003,"حَدثنَا مُحَمَّد بن الْحسن ثَنَا حُسَيْن بن إِدْرِيس قَالَ قَالَ بن عمار الْموصِلِي عباد بن كثير هُوَ مقدسي وَهُوَ صَالح وَهُوَ اثْبتْ من عباد بن كثير الْمَكِّيّ"],[1004,"وَقَالَ يحيى فِي رِوَايَة الْعَبَّاس عَنهُ عباد بن الْعَوام وَعباد بن عباد جَمِيعًا ثِقَة وَعباد بن عباد أرفعهما واكثرهما حَدِيثا"],[1005,"عباد بن صُهَيْب قَالَ أَحْمد قد رَأَيْته بِالْبَصْرَةِ غير مرّة وَكَانَت الْقَدَرِيَّة تنتحله وَمَا كَانَ بِصَاحِب كذب وَكَانَ عِنْده من الحَدِيث أَمر عَظِيم وَكَانَ قد سمع من الْأَعْمَش"],[1006,"عباد بن ميسرَة الْمنْقري لَيْسَ بِهِ بَأْس قَالَه يحيى"],[1007,"عباد بن رَاشد ثِقَة ثِقَة قَالَه أَحْمد"],[1008,"عباد بن عباد الَّذِي يروي عَنهُ مُعْتَمر هُوَ عباد بن عباد بن عَلْقَمَة الْمَازِني شيخ بَصرِي ثِقَة ثِقَة قَالَه يحيى وَقَالَ أَحْمد مَا أرى بِهِ بَأْسا"],[1009,"وَقَالَ يحيى عقبَة بن أبي الصَّهْبَاء ثِقَة كنيته أَبُو خريم مولى باهلة وَهُوَ ثِقَة"],[1010,"وَعَطَاء بن يزِيد ثِقَة"],[1011,"وَعَطَاء بن أبي مَيْمُونَة ثِقَة لَيْسَ بِهِ بَأْس"],[1012,"وَعَطَاء الكيخاراني ثِقَة الَّذِي يحدث عَن أم الدَّرْدَاء قَالَه يحيى"],[1013,"وَقَالَ أَحْمد عَطاء بن دِينَار مَا أرى بِهِ بَأْسا روى عَنهُ بن لَهِيعَة وَسَعِيد بن أبي أَيُّوب"],[1014,"عَطِيَّة الْعَوْفِيّ لَيْسَ بِهِ بَأْس قَالَه يحيى"],[1015,"وَقَالَ عَطِيَّة السراج روى عَنهُ أَيُّوب بَصرِي ثِقَة"],[1016,"وعطية بن عبد الرَّحْمَن الثَّقَفِيّ روى عَنهُ سُفْيَان وَشريك ثِقَة"],[1017,"وعَوْف الْأَعرَابِي ثِقَة وَهُوَ هجري وَقَالَ أَحْمد عَوْف الْأَعرَابِي ثِقَة صَالح الحَدِيث"],[1018,"وَقَالَ أَحْمد عقبَة بن أبي صَالح كُوفِي روى عَن إِبْرَاهِيم صَالح"],[1019,"وَعقبَة بن سيار أَبُو الْجلاس روى عَنهُ شُعْبَة أَرْجُو ان يكون ثِقَة"],[1020,"وَعقبَة الْأَسدي روى عَنهُ الثَّوْريّ"],[1021,"وَعقبَة بن عبيد أَخُو سعيد بن عبيد سمع مِنْهُ أَبُو مُعَاوِيَة يروي عَنهُ حديثان أَو ثَلَاثَة"],[1022,"وَعقبَة بن خَالِد السكونِي يُقَال لَهُ عقبَة الْمُحدث أَرْجُو أَن يكون ثِقَة ان شَاءَ الله"],[1023,"وَعقبَة بن حَيَّان روى عَنهُ ربعي بن خرَاش"],[1024,"وَعقبَة بن أبي جسرة البصريون يروون عَنهُ"],[1025,"وَعقبَة بن عَلْقَمَة الْمعَافِرِي من أَصْحَاب الْأَوْزَاعِيّ ثِقَة من أهل طرابلس الْمغرب سكن الشَّام وَكَانَ خيارا روى عَنهُ أَبُو مسْهر"],[1026,"عقبَة بن عبد الغافر ثِقَة قَالَه بن معِين"],[1027,"وَعقبَة بن وساج بَصرِي ثِقَة وَقَالَ فِيهِ بن عمار مَعْرُوف ثِقَة روى عَنهُ النَّاس"],[1028,"عقبَة الْأَصَم الَّذِي روى عَنهُ يحيى بن حسان ثِقَة من أهل الْبَصْرَة قَالَه أَحْمد بن صَالح"],[1029,"عقبَة بن خَالِد قَالَ عُثْمَان هُوَ عِنْدِي ثِقَة"],[1030,"قَالَ أَحْمد عقبَة بن أبي الْعيزَار صَالح الحَدِيث"],[1031,"عقبَة بن وهب بن عقبَة العامري صَالح"],[1032,"وَعقبَة بن أبي جسرة ثِقَة قَالَه يحيى"],[1033,"قَالَ وَعقبَة بن مكرم الضَّبِّيّ ثِقَة"],[1034,"الْعَلَاء بن عتبَة الْحِمصِي روى عَنهُ إِسْمَاعِيل بن عَيَّاش وَقَالَ كَانَ ثِقَة"],[1035,"الْعَلَاء بن الْمسيب ثِقَة قَالَه يحيى"],[1036,"وَقَالَ الْعَلَاء بن الْحَارِث الَّذِي روى عَنهُ فرج بن فضَالة ثِقَة والْعَلَاء بن الْحَارِث لَيْسَ فِي حَدِيثه شَيْء وَقَالَ بن الْمَدِينِيّ الْعَلَاء بن الْحَارِث ثِقَة وَهُوَ الْحَضْرَمِيّ"],[1037,"الْعَلَاء بن أبي الْعَبَّاس الشَّاعِر ثِقَة ثِقَة قَالَه يحيى"],[1038,"والْعَلَاء بن هِلَال ثِقَة"],[1039,"والْعَلَاء بن صَالح ثِقَة"],[1040,"والْعَلَاء بن عبد الْجَبَّار لَيْسَ بِهِ بَأْس"],[1041,"الْعَلَاء بن خَالِد الْقرشِي ثِقَة"],[1042,"أَبُو شيبَة كُوفِي قَالَ يحيى لَيْسَ بِهِ بَأْس"],[1043,"عبَادَة بن نسي شَامي ثِقَة قَالَه أَحْمد"],[1044,"وَقَالَ يحيى عبَادَة بن مُسلم الْفَزارِيّ كُوفِي ثِقَة ثِقَة روى عَنهُ وَكِيع وَأَبُو نعيم وَابْن نمير"],[1045,"عُبَيْدَة بن حميد لم يكن بِهِ بَأْس وانما عابوه انه كَانَ يقْعد عِنْد أَصْحَاب الْكتب"],[1046,"عُبَيْدَة بن أبي رائطة الْمُجَاشِعِي ثِقَة قَالَه يحيى"],[1047,"وَقَالَ عُثْمَان عُبَيْدَة ثِقَة صَدُوق"],[1048,"وَقَالَ يحيى عزْرَة الَّذِي يحدث عَنهُ قَتَادَة ثِقَة وَقَالَ فِيهِ بن عمار عزْرَة بن ثَابت لَا أعلم أحدا قَالَ فِيهِ إِلَّا خيرا يَعْنِي صَاحب قَتَادَة"],[1049,"قَالَ يحيى الْعيزَار بن جَرْوَل ثِقَة"],[1050,"وَعِيسَى بن عمر ثِقَة كُوفِي"],[1051,"وَعِيسَى بن عبد الرَّحْمَن البَجلِيّ ثِقَة"],[1052,"وَعِيسَى بن طهْمَان ثِقَة"],[1053,"وَعِيسَى بن مَيْمُون الَّذِي يروي أعظم النِّكَاح بركَة ايسره مؤونة يُقَال لَهُ بن تليدان وَهُوَ من ولد أبي قُحَافَة ويروي عَنهُ حَمَّاد بن سَلمَة يَقُول بن سَخْبَرَة وَهُوَ هَذَا الَّذِي روى عَنهُ وَكِيع وَأَبُو نعيم وَلَيْسَ بِهِ بَأْس وَعِيسَى الَّذِي يروي أعْلنُوا النِّكَاح ويروي حَدِيث مُحَمَّد بن كَعْب ضَعِيف لَيْسَ بِشَيْء"],[1054,"وَعِيسَى بن مَيْمُون صَاحب الْقَاسِم لَيْسَ بِشَيْء"],[1055,"وَعِيسَى بن الْمُخْتَار صَالح"],[1056,"وَقَالَ عَليّ بن الْمَدِينِيّ فِي عِيسَى بن مَيْمُون ثِقَة وَقَالَ كَانَ سُفْيَان يقدمهُ على وَرْقَاء"],[1057,"قَالَ أَحْمد عِيسَى بن أبي عزة شيخ ثِقَة"],[1058,"وَقَالَ يحيى فِي عِيسَى بن الْمُغيرَة ثِقَة"],[1059,"وَعِيسَى بن الضَّحَّاك صَالح"],[1060,"وَعِيسَى بن حميد الرَّاسِبِي صَالح"],[1061,"وَأَبُو جَعْفَر الرَّازِيّ وَهُوَ عِيسَى بن عبد الله التَّمِيمِي صَالح كَذَا قَالَ بن عبد الله"],[1062,"وَقَالَ أَحْمد عدي بن ثَابت ثِقَة إِلَّا انه كَانَ يتشيع وَقَالَ فِيهِ يحيى عدي بن ثَابت الْجَزرِي لَيْسَ بِهِ بَأْس إِذا حدث عَن الثِّقَات"],[1063,"وعدي بن أبي عمَارَة لَيْسَ بِهِ بَأْس"],[1064,"وعافية القَاضِي ثِقَة"],[1065,"عِكْرِمَة بن عمار لَيْسَ بِهِ بَأْس صَدُوق وَقَالَ فِيهِ أَحْمد بن صَالح أَنا أَقُول ان عِكْرِمَة ثِقَة فأحتج بِهِ وَبِقَوْلِهِ لَا شكّ فِيهِ وَسُئِلَ أَيُّوب عَنهُ فَقَالَ لَو لم يكن عِنْدِي ثِقَة لم أكتب عَنهُ"],[1066,"وَقَالَ يحيى عِكْرِمَة بن خَالِد ثِقَة"],[1067,"وَأَبُو حَمْزَة الَّذِي روى عَن بن عَبَّاس عمرَان بن أبي عَطاء واسطي ثِقَة"],[1068,"وَعمْرَان بن سُلَيْمَان هُوَ عمرَان القبي كُوفِي ثِقَة يَعْنِي الْقبَّة والجونة الَّتِي بِالْكُوفَةِ بِحَضْرَة مَسْجِد الْجَامِع"],[1069,"وَقَالَ أَحْمد عمرَان بن أبي أنس أحد بني عَامر بن لؤَي وَكَانَ ثِقَة"],[1070,"وَقَالَ يحيى عمرَان بن زَائِدَة بن نشيط ثِقَة"],[1071,"قَالَ أَحْمد عمرَان الْقصير ثِقَة وَهُوَ عمرَان بن مُسلم"],[1072,"وَعمْرَان بن حدير صَدُوق صَدُوق"],[1073,"وَعمْرَان بن مُسلم الْجعْفِيّ ثِقَة كَمَا يكون الثِّقَة قَالَه أَحْمد"],[1074,"عمرَان بن عُيَيْنَة صَالح الحَدِيث قَالَه يحيى"],[1075,"وَقَالَ يحيى بن سعيد عمرَان الْعمي قَالَ لم يكن بِهِ بَأْس وَلَكِن لم يكن من أهل الحَدِيث كتبت عَنهُ أَشْيَاء فرميت بهَا"],[1076,"قَالَ يحيى بن معِين عُيَيْنَة بن عبد الرَّحْمَن ثِقَة وَأَبوهُ ثِقَة"],[1077,"وَقَالَ أَحْمد عُيَيْنَة بن عبد الرَّحْمَن لَيْسَ بِهِ بَأْس صَالح الحَدِيث وَأَبوهُ لَيْسَ بالمشهور"],[1078,"الْعَوام بن حَمْزَة مَا أقربه من مَسْعُود بن عَليّ لي يكن بِهِ بَأْس قَالَه يحيى الْقطَّان"],[1079,"والعوام بن حَوْشَب ثِقَة ثِقَة قَالَه أَحْمد"],[1080,"الْعَوام بن مراجم ثِقَة قَالَه يحيى"],[1081,"قَالَ وعطاف بن خَالِد لَيْسَ بِهِ بَأْس وَقَالَ أَحْمد عطاف لَيْسَ بِهِ بَأْس من أهل الْمَدِينَة وَلم يرضه بن مهْدي"],[1082,"وَقَالَ يحيى عَبدة بن سُلَيْمَان ثِقَة وَقَالَ عُثْمَان عَبدة بن سُلَيْمَان ثِقَة مُسلم صَدُوق"],[1083,"نَا مُحَمَّد بن مَحْمُود السراج انا مُحَمَّد بن سهل بن عَسْكَر قَالَ سَمِعت أَحْمد بن حَنْبَل يَقُول إِذا اخْتلف أَصْحَاب معمر فِي حَدِيث معمر فَالْحَدِيث حَدِيث عبد الرازاق"],[1084,"قَالَ يحيى عون بن عبد الله بن عتبَة ثِقَة"],[1085,"عون بن مُوسَى ثِقَة"],[1086,"عون بن المعمر ثِقَة وَقَالَ عَليّ بن الْمَدِينِيّ عون بن معمر الْعجلِيّ وَكَانَ من خِيَار النَّاس"],[1087,"عصمَة بن سَالم الْهنائِي ثِقَة ثِقَة روى عَنهُ مُسلم بن إِبْرَاهِيم"],[1088,"وَقَالَ أَحْمد بن صَالح عِيَاض بن عبد الله الفِهري من أهل الْمَدِينَة ثَبت لَهُ بِالْمَدِينَةِ شَأْن وَفِي حَدِيثه شَيْء"],[1089,"عِيَاض بن دِينَار اللَّيْثِيّ روى عَنهُ بن إِسْحَاق وَوَثَّقَهُ"],[1090,"عفيف بن عَمْرو شيخ روى عَنهُ مَالك وَقَالَ أَحْمد عفيف شيخ قديم"],[1091,"وَقَالَ يحيى عفيف بن سَالم الْموصِلِي ثِقَة"],[1092,"عَيَّاش بن عقبَة الْحَضْرَمِيّ عَم بن لَهِيعَة شيخ صَدُوق قَالَه أَبُو عبد الرَّحْمَن النَّسَائِيّ وَحدث عَنهُ"],[1093,"عُمَيْر مولى عبيد الله بن الْعَبَّاس روى عَنهُ عبد الرَّحْمَن بن هُرْمُز الْأَعْرَج وَقيل فِيهِ ثِقَة"],[1094,"وَقَالَ يحيى عتبَة بن أبي حَكِيم ثِقَة"],[1095,"وعبثر أَبُو زبيد ثِقَة"],[1096,"عثام بن عَليّ كُوفِي لَيْسَ بِهِ بَأْس يكنى أَبَا عَليّ قَالَه أَحْمد وَقَالَ عُثْمَان كَانَ صَدُوقًا"],[1097,"عقيل بن معقل ثِقَة"],[1098,"وَقَالَ يحيى عُرْوَة أَبُو عبد الله الْهَمدَانِي ثِقَة"],[1099,"وعوسجة بن الرماح ثِقَة"],[1100,"وعائذ بن بشير لَيْسَ بِهِ بَأْس وَلكنه روى أَحَادِيث مَنَاكِير"],[1101,"وعائذ بن حبيب ثِقَة"],[1102,"أَبُو الْعَوام عمرَان الْقطَّان من أخص النَّاس بقتادة وَكَانُوا يَقُولُونَ إِنَّه يمِيل اليه إِلَّا انهم لي يثبتوا عَلَيْهِ شَيْئا"],[1103,"غَالب الْقطَّان لَيْسَ بِهِ بَأْس قَالَه يحيى وَقَالَ احْمَد غَالب الْقطَّان ثِقَة ثِقَة"],[1104,"غَسَّان بن مُضر أَبُو مُضر شيخ ثِقَة وَثَّقَهُ احْمَد وَيحيى"],[1105,"وَفِي رِوَايَة بن أبي خَيْثَمَة قَالَ غَسَّان الْموصِلِي الَّذِي يروي جَامع سُفْيَان ثِقَة"],[1106,"غريف بن دِرْهَم التَّيْمِيّ روى عَنهُ وَكِيع وَقَالَ كَانَ ثِقَة"],[1107,"غوث بن جَابر قَالَ يحيى لم يكن بِهِ بَأْس وَمَا كتبت عَنهُ حَدِيثا قطّ كَانَ يروي حِكْمَة وهب"],[1108,"غياث بن الْمثنى فَقَالَ لَيْسَ بِهِ بَأْس حدث عَن بهز بن حَكِيم"],[1109,"غاضرة بن فرهد يروي عَنهُ عباد بن عباد وَأَبُو ظفر وَهُوَ ثِقَة قَالَه يحيى"],[1110,"وَقَالَ غيلَان بن جرير ثِقَة"],[1111,"وغزوان أَبُو مَالك الَّذِي روى عَنهُ حُصَيْن غفاري كُوفِي ثِقَة"],[1112,"قَالَ ثَنَا عبد الله بن سُلَيْمَان ومكرم قَالَا ثَنَا عبد الله قَالَ سَمِعت أبي يَقُول الفضيل بن غَزوَان هَذَا شيخ ثِقَة روى عَنهُ نعيم بن ميسرَة وَقَالَ بن عمار فُضَيْل بن غَزوَان كنيته أَبُو مُحَمَّد ثِقَة روى عَنهُ يحيى بن سعيد"],[1113,"فُضَيْل بن مَرْزُوق وَثَّقَهُ يحيى مرّة وَضَعفه أُخْرَى"],[1114,"الفضيل بن فضَالة قَالَ شُعْبَة ثِقَة"],[1115,"فُضَيْل بن عِيَاض قَالَ عُثْمَان كَانَ ثِقَة صَدُوقًا لَيْسَ بِحجَّة"],[1116,"وَقَالَ عَليّ بن الْمَدِينِيّ الْفضل بن الْعَلَاء كَانَ من أهل الْكُوفَة وَكَانَ عندنَا بِالْبَصْرَةِ وَكَانَ ثِقَة وَقَالَ يحيى لَا بَأْس بِهِ"],[1117,"الْفضل بن مُوسَى السينَانِي ثِقَة قَالَه يحيى وَكَانَ عبد الله بن الْمُبَارك يَقُول حَدثنِي الثِّقَة يَعْنِي السينَانِي"],[1118,"وَالْفضل بن عَنْبَسَة ثِقَة من كبار أَصْحَاب الحَدِيث قَالَه احْمَد"],[1119,"وَالْفضل بن دلهم يروي عَن الْحسن قَالَ يحيى ضَعِيف وَقَالَ مرّة أُخْرَى صَالح"],[1120,"وَالْفضل بن عَطِيَّة ثِقَة وَابْنه مُحَمَّد بن الْفضل كَذَّاب"],[1121,"وَقَالَ احْمَد بن صَالح مَا رَأَيْت مُحدثا اصدق من أبي نعيم يَعْنِي الْفضل بن دُكَيْن الْكُوفِي وَقَالَ احْمَد أَبُو نعيم كَانَ ثِقَة وَكَانَ يُدَلس أَحَادِيث مَنَاكِير"],[1122,"قَالَ يحيى الْفضل بن مَيْمُون صَالح الحَدِيث"],[1123,"فياض كُوفِي ثِقَة يروي عَنهُ مهْرَان الرَّازِيّ وحكام"],[1124,"فراس بن يحيى ثِقَة قَالَه بن عمار وَقَالَ عُثْمَان فراس صَدُوق قيل لَهُ ثَبت هُوَ قَالَ لَا وَلَا كَرَامَة وَلكنه صَدُوق روى عَنهُ سُفْيَان وَشريك وشيبان وَكَانَ فراس معلما"],[1125,"فرات الْقَزاز روى عَنهُ سُفْيَان وَقَالَ كَانَ ثِقَة"],[1126,"قَالَ يحيى الْفُرَات بن سلمَان ثِقَة"],[1127,"وفرات بن مُسلم وَهُوَ أَبُو نَوْفَل بن فرات وَهُوَ رقي ثِقَة"],[1128,"وفرات بن الْأَحْنَف ثِقَة وَهُوَ كُوفِي"],[1129,"وَفطر بن خَليفَة ثِقَة قَالَه يحيى وَأحمد وَقَالَ أَحْمد إِلَّا انه كَانَ يتشيع"],[1130,"فَايِد بن أبي رَافع مولى عبادل ثِقَة مديني قَالَه يحيى"],[1131,"أَبُو الورقاء ثِقَة واسْمه فَايِد قَالَه عَليّ بن الْمَدِينِيّ"],[1132,"وَقَالَ يحيى فَايِد أَبُو الورقاء روى عَنهُ الْكُوفِيُّونَ لَيْسَ بِثِقَة"],[1133,"فليح ثِقَة قَالَه بن معِين"],[1134,"فليت العامري مَا أرى بِهِ بَأْسا قَالَه احْمَد"],[1135,"فرقد السبخي لَيْسَ بِهِ بَأْس"],[1136,"قَالَ هشيم إِذا ذكر قَتَادَة فِي حَدِيث فاتركوا حَدِيث النَّاس وَقَالَ يحيى قَتَادَة ثِقَة"],[1137,"قَتَادَة بن الفضيل بن عبد الله بن قَتَادَة الْحَرَشِي الرهاوي وَكَانَ ثِقَة"],[1138,"الْقَاسِم بن مَيْمُون الْجعْفِيّ يحدث عَنهُ عَليّ بن ثَابت ووكيع وَهُوَ ثِقَة"],[1139,"الْقَاسِم بن حسان الَّذِي روى عَنهُ زيد بن ثَابت ثِقَة قَالَه أَحْمد بن صَالح"],[1140,"الْقَاسِم بن أبي أَيُّوب ثِقَة"],[1141,"الْقَاسِم بن عبد الرَّحْمَن الَّذِي يروي عَن أبي امامة ثِقَة قَالَه يحيى"],[1142,"وَالقَاسِم بن مَالك ثِقَة"],[1143,"وَالقَاسِم بن الْفضل الْحدانِي لَيْسَ بِهِ بَأْس ثِقَة وَقَالَ عبد الرَّحْمَن بن مهْدي الْقَاسِم بن الْفضل الْحدانِي من شُيُوخنَا الثِّقَات وَقَالَ بن عمار الْقَاسِم بن الْفضل من ثِقَات النَّاس روى عَنهُ يحيى بن سعيد"],[1144,"وَقَالَ أَحْمد الْقَاسِم بن معن مَسْتُور ثِقَة ولي قَضَاء الْكُوفَة روى عَنهُ بن مهْدي وَلَيْسَ بِهِ بَأْس وَكَانَ معن بن عبد الرَّحْمَن أَبوهُ من خِيَار الْمُسلمين"],[1145,"ثَنَا مُحَمَّد بن مخلد قَالَ سَمِعت عَبَّاس بن مُحَمَّد يَقُول أَبُو عبيد الْقَاسِم بن سَلام مِمَّن يزْدَاد عندنَا كل يَوْم خيرا"],[1146,"الْقَاسِم الْأَعْرَج ثِقَة قَالَه يحيى"],[1147,"حَدثنَا عبد الله بن مُحَمَّد الْبَغَوِيّ ثَنَا مَحْمُود بن غيلَان قَالَ نَا أَبُو دَاوُد قَالَ قَالَ لي شُعْبَة ادركوا قيسا قبل ان يَمُوت نَا مُحَمَّد بن مُحَمَّد بن سُلَيْمَان الباغندي قَالَ حَدثنِي زيد بن أخرم قَالَ نَا أَبُو دَاوُد قَالَ سَمِعت شُعْبَة يَقُول سَمِعت أَبَا حُصَيْن يثني على قيس وَقَالَ لنا شُعْبَة ادركوا قيسا قبل ان يَمُوت وَقَالَ عُثْمَان بن أبي شيبَة قيس بن الرّبيع كَانَ صَدُوقًا وَلَكِن اضْطربَ عَلَيْهِ بعض حَدِيثه"],[1148,"وَأَبُو نعَامَة الْحَنَفِيّ قيس بن عَبَايَة بَصرِي ثِقَة"],[1149,"وَقَالَ قيس بن أبي حَازِم كُوفِي ثِقَة"],[1150,"وَقيس بن وهب كُوفِي ثِقَة روى عَنهُ سُفْيَان وَوَثَّقَهُ احْمَد أَيْضا وَقَالَ روى عَنهُ شريك وَقَالَ يحيى روى عَنهُ أَبُو نعيم وَأَبُو احْمَد الزبيرِي عَن رجل يُقَال لَهُ قيس وَهُوَ كُوفِي ثِقَة"],[1151,"وَقَالَ قيس بن رَاشد كُوفِي ثِقَة"],[1152,"وَقيس بن سعد لَيْسَ بِهِ بَأْس"],[1153,"وقرة بن خَالِد السدُوسِي ثِقَة كنيته أَبُو خَالِد"],[1154,"وقرة بن عبد الرَّحْمَن قَالَ يحيى وَلَيْسَ بِهِ بَأْس عِنْدِي"],[1155,"وَقَالَ أَبُو صَالح الَّذِي روى عَنهُ يحيى بن أبي كثير اسْمه قيلويه بَصرِي ثِقَة مَأْمُون"],[1156,"وَقُطْبَة بن الْعَلَاء ثِقَة"],[1157,"وَقُطْبَة بن عبد الْعَزِيز كُوفِي ثِقَة"],[1158,"أَبُو الدهماء اسْمه قرفة بن بهيس وَهُوَ بَصرِي ثِقَة"],[1159,"قَالَ وَقُدَامَة بن مُوسَى ثِقَة"],[1160,"وقابوس بن أبي ظبْيَان لَيْسَ بِهِ بَأْس"],[1161,"وقزعة بن سُوَيْد لَيْسَ بِهِ بَأْس وهاه صَالح قَالَه يحيى"],[1162,"قطري الخشاب لَيْسَ بِهِ بَأْس"],[1163,"وقران بن تَمام ثِقَة وَكَانَ صَاحب دَوَاب"],[1164,"وقرط بن حُرَيْث بَصرِي قَالَ يحيى كتبت عَنهُ كَانَ يروي عَن سَلام بن مِسْكين وَلم يكن بِهِ بَأْس وَهُوَ مولى باهلة"],[1165,"وقرط بن عيوق لَيْسَ بِهِ بَأْس"],[1166,"وقرط بن حُرَيْث كنيته أَبُو سهل وَهُوَ بَصرِي لَيْسَ بِهِ بَأْس"],[1167,"قَالَ أَحْمد قبيصَة بن عقبَة رجل صَالح ثِقَة لَا بَأْس بِهِ كَانَ كثير الحَدِيث وَقَالَ يحيى قبيصَة بن عقبَة ثِقَة"],[1168,"قَالَ احْمَد بن حَنْبَل فِي رِوَايَة أبي بكر الْأَثْرَم احْمَد بن مُحَمَّد بن هاني كثير بن شنظير هُوَ مِمَّن يكْتب حَدِيثه ويشتهى وَقَالَ أَحْمد هُوَ صَالح قد روى عَنهُ النَّاس وَاحْتَمَلُوهُ"],[1169,"وَكثير بن كثير من قُرَيْش ثِقَة قَالَه أَحْمد"],[1170,"وَكثير بن زيد مَا أرى بِهِ بَأْسا"],[1171,"قَالَ يحيى كثير بن هِشَام ثِقَة نَحن أول من كتب عَنهُ كتبت عَنهُ كتبه مرَّتَيْنِ مرّة قبل ان يصنف وَمرَّة بعد مَا صنف"],[1172,"وكليب بن وَائِل كُوفِي ثِقَة"],[1173,"وكهمس بن الْحسن ثِقَة"],[1174,"وكلثوم بن جوشن شَامي انْتقل إِلَيْهَا لَيْسَ بِهِ بَأْس"],[1175,"وَقَالَ احْمَد كثلوم بن جبر شيخ ثِقَة"],[1176,"كَامِل أَبُو الْعَلَاء ثِقَة قَالَه يحيى"],[1177,"كَادِح بن جَعْفَر رجل صَالح خير قَالَه احْمَد"],[1178,"كريز بن معقل الْبَاهِلِيّ ثِقَة"],[1179,"لَيْث بن سعد ثِقَة صَدُوق قَالَه بن معِين وَقَالَ احْمَد بن صَالح اللَّيْث بن سعد امام قد أوجب الله علينا حَقه فَقيل لِأَحْمَد اللَّيْث بن سعد امام قَالَ نعم امام لم يكن بِالْبَلَدِ بعد عَمْرو بن الْحَارِث مثل اللَّيْث"],[1180,"قَالَ عُثْمَان لَيْث بن أبي سليم ثِقَة صَدُوق وَلَيْسَ بِحجَّة"],[1181,"قَالَ يحيى لَيْث أَبُو المشرفي واسطي لَيْسَ بِهِ بَأْس"],[1182,"نَا عبد الْعَزِيز بن قيس البرسيمي بِمصْر قَالَ نَا احْمَد بن عبد الْعَزِيز بن وهب قَالَ نَا عمي قَالَ حَدثنِي اللَّيْث بن سعد عَن يحيى بن سعيد قَالَ مَا أعلم أحدا بَقِي عِنْده من الْعلم مَا عِنْد بن شهَاب وَبِه قَالَ حَدثنِي اللَّيْث عَن الجُمَحِي انه قَالَ مَا رَأَيْت أحدا أقرب شبها بِابْن شهَاب من يحيى بن سعيد وَلَوْلَا بن شهَاب لذهب كثير من السّنَن وَبِه قَالَ سَمِعت اللَّيْث يحدث عَن جَعْفَر بن ربيعَة عَن عرَاك بن مَالك انه قَالَ أَخْبرنِي معلموا أهل الْمَدِينَة فَجعل يصفهم رجلا رجلا ثمَّ قَالَ واخبرك بأعلمهم جَمِيعًا بن شهَاب قَالَ فَقلت لَهُ كَيفَ كَانَ ذَاك فَقَالَ ان كل رجل من أُولَئِكَ قد اقْتصر على علمه الَّذِي لَيْسَ عِنْده شَيْء غَيره وان بن شهَاب جالسهم جَمِيعًا فَأخذ علمهمْ فَهُوَ اعْلَم مِنْهُم وَبِه قَالَ حَدثنِي اللَّيْث ان إِبْرَاهِيم بن عمر بن عبد الْعَزِيز حَدثهُ انه سمع أَبَاهُ يَقُول لِابْنِ شهَاب مَا أعلمك تعرض عَليّ شَيْئا الا شَيْئا مر على مسامعي الا انك أوعى لَهُ مني نَا عبد الله بن مُحَمَّد الْبَغَوِيّ قَالَ نَا إِسْحَاق بن أبي إِسْرَائِيل قَالَ سَمِعت سُفْيَان بن عُيَيْنَة يَقُول قيل لِلزهْرِيِّ أَلا تجْلِس الى سَارِيَة قَالَ أخْشَى ان يوطئ على عَقبي وَلَا يجلس ذَلِك الْمجْلس الا رجل زهد فِي الدّين"],[1183,"وَقَالَ بن معِين أَبُو الزبير الْمَكِّيّ صَاحب جَابر ثِقَة نَا عبد الله بن سُلَيْمَان بن الْأَشْعَث نَا أَبُو بَقِي هِشَام بن عبد الْملك قَالَ نَا سُوَيْد بن عبد الْعَزِيز قَالَ قَالَ لي بعض أَصْحَابنَا لم لم تحمل عَن أبي الزبير قلت خدعني شُعْبَة قَالَ لَا تحمل عَنهُ اني رَأَيْته يسيء صلَاته"],[1184,"نَا عبد الله بن مُحَمَّد الْبَغَوِيّ قَالَ سَمِعت احْمَد بن حَنْبَل يَقُول بن أبي ذِئْب كَانَ قَلِيل الحَدِيث وَكَانَ رجلا صَالحا قوالا بِالْحَقِّ قَالَ احْمَد بن حَنْبَل كَانَ يشبه بِسَعِيد بن الْمسيب يَعْنِي بن أبي ذِئْب نَا عبد الرَّحْمَن بن الْحسن الرهبي قَالَ نَا إِبْرَاهِيم بن هاني قَالَ سَمِعت بشر بن الْحَارِث يَقُول الثَّوْريّ خير من مائَة مثل بن أبي ذِئْب قَالَ إِبْرَاهِيم فَذَكرته لأبي عبد الله بن حَنْبَل فَقَالَ وَمَا يدريه بن أبي ذِئْب كَانَ صَاحب أَمر وَنهي"],[1185,"مُحَمَّد بن عبد الرَّحْمَن مولى آل طَلْحَة لَيْسَ بِهِ بَأْس قَالَه يحيى"],[1186,"وَقَالَ احْمَد بن صَالح أَبُو الْأسود ثَبت لَهُ شَأْن وَمَا بِالْمَدِينَةِ من حَدِيثه عشرَة أَحَادِيث وَحَدِيثه بِمصْر وَله مغازي فَذكر احْمَد من فَضله وثبته واسْمه مُحَمَّد بن عبد الرَّحْمَن"],[1187,"وَقَالَ احْمَد بن صَالح مُحَمَّد بن مُسلم بن أبي الوضاح ثِقَة ثِقَة قَالَهَا مرَّتَيْنِ"],[1188,"وَقَالَ يحيى مُحَمَّد بن زِيَاد الْأَلْهَانِي ثِقَة وَفِي رِوَايَة أُخْرَى عَنهُ مُحَمَّد بن زِيَاد الَّذِي روى عَنهُ شُعْبَة ثِقَة"],[1189,"مُحَمَّد بن يُوسُف هُوَ بن خي السَّائِب بن يزِيد وَكَانَ ثِقَة قَالَه عَليّ بن الْمَدِينِيّ قَالَ يحيى بن سعيد كَانَ مُحَمَّد بن يُوسُف أعرج وَكَانَ ثبتا وَكَانَ يَقُول السَّائِب بن يزِيد جدي من قبل أُمِّي"],[1190,"وَقَالَ احْمَد بن صَالح مُحَمَّد بن يُوسُف مولى عُثْمَان هُوَ بن عَفَّان الَّذِي روى عَنهُ بن جريج ثَبت لَهُ شَأْن وَكَانَ احْمَد بن صَالح معجبا بِهِ"],[1191,"نَا الْحسن بن صَدَقَة قَالَ نَا بن أبي خَيْثَمَة قَالَ سَأَلت يحيى بن معِين عَن مُحَمَّد بن إِسْحَاق فَقَالَ قَالَ عَاصِم بن عمر بن قَتَادَة لَا يزَال فِي النَّاس علم مَا عَاشَ مُحَمَّد بن إِسْحَاق قَالَ يحيى بن معِين بن إِسْحَاق سمع من عَاصِم وَكَانَ يَقُول هَذَا فِيهِ الا من حبر نَا الْحسن نَا بن أبي خَيْثَمَة نَا إِبْرَاهِيم بن الْمُنْذر عَن أبي عُيَيْنَة قَالَ سَمِعت الزُّهْرِيّ يَقُول لمُحَمد بن إِسْحَاق مَا لي لم أرك قَالَ ان اذنك هَذَا مَنَعَنِي فَقَالَ بن شهَاب لِبَوَّابِهِ لَا تَمنعهُ إِذا جَاءَنِي نَا الْحسن قَالَ نَا بن أبي خَيْثَمَة أخبرنَا إِبْرَاهِيم بن الْمُنْذر قَالَ قَالَ بن عُيَيْنَة مَا يَقُول أَصْحَابك فِي مُحَمَّد بن إِسْحَاق قَالَ قلت يَقُولُونَ انه كَذَّاب قَالَ لَا تقل ذَاك فَلَقَد رَأَيْته خلف رَأسه خلف الْقَبْر ينْتَظر يزِيد بن خصيفَة اسْمَع مِنْهُ الْأَحَادِيث الَّتِي افدتني نَا الْحسن نَا بن أبي خَيْثَمَة قَالَ سَمِعت يحيى بن معِين وَقيل لَهُ أَيهمَا أحب إِلَيْك مُوسَى بن عُبَيْدَة الربذي أَو مُحَمَّد بن إِسْحَاق فَقَالَ مُحَمَّد بن إِسْحَاق نَا الْحسن نَا بن أبي خَيْثَمَة نَا مُجَاهِد بن مُوسَى نَا يحيى بن آدم نَا أَبُو شهَاب قَالَ قَالَ لي شُعْبَة بن الْحجَّاج عَلَيْك بالحجاج بن أَرْطَأَة وَمُحَمّد بن إِسْحَاق نَا أَحْمد بن مَسْعُود الزبيرِي بِمصْر قَالَ نَا أَبُو أُميَّة الطرسوسي قَالَ نَا عَليّ بن قادم قَالَ حَدثنِي فياض بن مُحَمَّد الرقي قَالَ سَمِعت بن أبي ذِئْب يَقُول كُنَّا عِنْد الزُّهْرِيّ فَنظر إِلَى مُحَمَّد بن إِسْحَاق فَقَالَ الزُّهْرِيّ لَا يزَال بالحجاز علم كثير مَا دَامَ هَذَا الْأَحول بَين أظهرهم"],[1192,"مُحَمَّد بن ثَابت الْخُرَاسَانِي أَخُو عَليّ بن ثَابت ثِقَة مَأْمُون وَفِي رِوَايَة أُخْرَى عَنهُ مُحَمَّد بن ثَابت أَخُو عزْرَة بن ثَابت ثِقَة"],[1193,"وَمُحَمّد بن ثَابت وَمُحَمّد بن ثَابت الْبنانِيّ ليسَا بِشَيْء وَكَانَ عَفَّان يَقُول مُحَمَّد بن ثَابت الْبنانِيّ صَدُوق فِي نَفسه وَلكنه ضَعِيف الحَدِيث"],[1194,"نَا مُوسَى بن الْقَاسِم الأشيب قَالَ نَا عبد الله بن أبي الدُّنْيَا قَالَ نَا مُحَمَّد بن سعد عَن الْوَاقِدِيّ وَغَيره قَالَ نَا مُحَمَّد بن عبد الرَّحْمَن بن أبي صعصعة الْأنْصَارِيّ روى عَنهُ مَالك ثِقَة"],[1195,"مُحَمَّد بن أبي حَفْصَة ثِقَة قَالَه يحيى"],[1196,"مُحَمَّد بن عبد الله بن أبي مَرْيَم الْمَدِينِيّ لم يكن بِهِ بَأْس قَالَه يحيى بن سعيد الْأنْصَارِيّ"],[1197,"مُحَمَّد بن عَمْرو ثفة روى عَنهُ يحيى بن سعيد الْقطَّان قَالَه بن معِين"],[1198,"قَالَ وَمُحَمّد بن رَاشد الْأَعْمَى ثِقَة وَكَانَ قدريا"],[1199,"وَمُحَمّد بن سليم الْمَكِّيّ لَيْسَ بِهِ بَأْس"],[1200,"وَمُحَمّد بن قيس ثِقَة"],[1201,"وَمُحَمّد بن بكار ثِقَة"],[1202,"وَمُحَمّد بن جحادة ثِقَة"],[1203,"وَمُحَمّد بن شريك صَالح"],[1204,"نَا عبد الله بن سُلَيْمَان قَالَ قَالَ عبد الله بن أَحْمد سَأَلت أبي عَن مُحَمَّد بن الْحسن الوَاسِطِيّ الَّذِي يُقَال لَهُ الْمُزنِيّ قَالَ باس بِهِ بَأْس شيخ ضخم كتبت عَنهُ أول سنة انحدرت فِيهَا إِلَى الْبَصْرَة وَلم القه فِي السّنة الثَّانِيَة كَانَ قد مَاتَ قَدِيما"],[1205,"قَالَ بن معِين مُحَمَّد بن مهزم يُقَال لَهُ الرمام وَيُقَال لَهُ الشعاب ثفة"],[1206,"قَالَ مُحَمَّد بن دِرْهَم الشَّامي لَيْسَ بِهِ بَأْس"],[1207,"وَمُحَمّد بن المُهَاجر أَخُو عَمْرو بن المُهَاجر صَاحب حرس عمر بن عبد الْعَزِيز ثِقَة"],[1208,"وَمُحَمّد بن رَاشد شَامي كَانَ بِالْبَصْرَةِ ثِقَة"],[1209,"وَأَبُو حَمْزَة السكرِي مُحَمَّد بن مَيْمُون ثِقَة"],[1210,"نَا عبد الرَّحْمَن بن مُحَمَّد الزُّهْرِيّ قَالَ نَا إِسْمَاعِيل بن إِسْحَاق قَالَ قَالَ عَليّ بن الْمَدِينِيّ مُحَمَّد بن عُثْمَان الشَّامي ثِقَة كَانَ ينزل سكَّة بن سَمُرَة"],[1211,"نَا نصر بن الْقَاسِم الْفَرَائِضِي قَالَ نَا مُحَمَّد بن إِبْرَاهِيم بن قربَة الْخَوَارِزْمِيّ قَالَ مُحَمَّد بن ربيعَة الْكُوفِي ثِقَة"],[1212,"نَا مُحَمَّد بن مُحَمَّد بن سُلَيْمَان الباغندي نَا مُحَمَّد بن أبي صَفْوَان الثَّقَفِيّ قَالَ مَا رَأَيْت كوفيا دخل الْبَصْرَة يشبه مُحَمَّد بن عبد الله بن نمير وَفِي كتاب جدي عَن بن رشدين قَالَ سَأَلت احْمَد بن صَالح عَن مُحَمَّد بن عبد الله بن نمير قَالَ تَسْأَلنِي عَن رجل لم ار بالعراق مثل رجلَيْنِ هَذَا بن نمير الصَّغِير مُحَمَّد وَالَّذِي بِبَغْدَاد يَعْنِي أَحْمد بن حَنْبَل مَا رَأَيْت بالعراق مثلهمَا أجمع مِنْهُمَا لِلْعَقْلِ وَالْعلم وَالدّين وَلكُل شَيْء"],[1213,"قَالَ وَسمعت احْمَد بن صَالح وَسُئِلَ عَن مُحَمَّد بن أبي زِيَاد قَالَ هَذَا الثَّقَفِيّ بَصرِي ثِقَة"],[1214,"قَالَ يحيى بن معِين مُحَمَّد بن عبد الله بن أبي سارة مديني ثِقَة"],[1215,"وَمُحَمّد بن أبي يحيى ثِقَة"],[1216,"مُحَمَّد بن أبي فديك ثِقَة"],[1217,"وَمُحَمّد بن جَعْفَر أَخُو إِسْمَاعِيل بن جَعْفَر ثقتان"],[1218,"وَمُحَمّد بن بشر الْكُوفِي الَّذِي يروي عَن زِيَاد بن علاقَة ثِقَة"],[1219,"وَمُحَمّد بن ربيعَة الْكلابِي ثِقَة"],[1220,"وَمُحَمّد بن إِسْمَاعِيل ثِقَة"],[1221,"وَمُحَمّد بن مَيْمُون المفلوج الزَّعْفَرَانِي يروي عَن جَعْفَر بن مُحَمَّد وَهِشَام بن عُرْوَة ثِقَة"],[1222,"وَمُحَمّد بن مُسلم بن الْمثنى لَيْسَ بِهِ بَأْس يروي عَنهُ يحيى بن سعيد الْقطَّان وَأَبُو الْوَلِيد الطَّيَالِسِيّ وَشعْبَة يروي عَن أَبِيه مُسلم بن الْمثنى وَإِسْمَاعِيل بن أبي خَالِد يروي عَن أبي الْمثنى الْكُوفِي وَهُوَ هَذَا"],[1223,"وَمُحَمّد بن دِرْهَم الَّذِي يروي عَنهُ شَبابَة لَيْسَ بِشَيْء"],[1224,"وَمُحَمّد بن عبد الرَّحْمَن الطفَاوِي لَيْسَ بِهِ بَأْس"],[1225,"وَمُحَمّد بن مَرْوَان الْعقيلِيّ لَيْسَ بِهِ بَأْس"],[1226,"وَأَبُو همام الأهوزي لم يكن صَاحب حَدِيث وَلَكِن لَا بَأْس بِهِ وَهُوَ مُحَمَّد بن الزبْرِقَان"],[1227,"وَمُحَمّد بن تَمِيم لَيْسَ بِهِ بَأْس"],[1228,"وَمُحَمّد بن رَاشد كنيته أَبُو نَضْلَة لَيْسَ بِهِ بَأْس"],[1229,"والقصبي ثِقَة وَهُوَ مُحَمَّد بن عمر القصبي صَاحب عبد الْوَارِث"],[1230,"وَمُحَمّد بن سليم خراساني ثِقَة"],[1231,"وَمُحَمّد بن الْحسن الوَاسِطِيّ ثِقَة"],[1232,"وَمُحَمّد بن يزِيد الوَاسِطِيّ ثِقَة"],[1233,"قَالَ احْمَد أَبُو عون عبيد الله أثبت واوثق من عبد الْملك بن عُمَيْر"],[1234,"وَقَالَ مَا كَانَ بِمُحَمد بن يزِيد بَأْس كتبه صِحَاح وَأَصله شَامي روى عَن النُّعْمَان بن الْمُنْذر"],[1235,"وَقَالَ مُحَمَّد بن هِلَال الْمَدِينِيّ لَيْسَ بِهِ بَأْس وَأَبوهُ لَا اعرفه"],[1236,"وَكَانَ سُفْيَان الثَّوْريّ يَقُول مُحَمَّد بن سوقة المرضي"],[1237,"نَا عبد الله بن سُلَيْمَان نَا عبد الله بن احْمَد قَالَ نَا أَبُو مُوسَى الْأنْصَارِيّ قَالَ نَا الْوَلِيد بن مُسلم قَالَ سَمِعت الْأَوْزَاعِيّ يفضل مُحَمَّد بن الْوَلِيد الزبيدِيّ على كل من سمع من الزُّهْرِيّ"],[1238,"قَالَ أَحْمد مُحَمَّد بن الْمُرْتَفع شيخ ثِقَة روى عَنهُ بن جريج وَابْن عُيَيْنَة"],[1239,"وَقَالَ مُحَمَّد بن عبد الْوَهَّاب القناد ثِقَة لم يكن بِهِ بَأْس"],[1240,"وَقَالَ احْمَد فِي مُحَمَّد بن عباد الْمَكِّيّ حَدِيثه حَدِيث أهل الصدْق وَأَرْجُو أَن لَا يكون بِهِ بَأْس وَذكره مرّة أُخْرَى فَقَالَ يَقع فِي قلبِي انه صَدُوق"],[1241,"وَمُحَمّد بن مهَاجر ثِقَة"],[1242,"وَمُحَمّد بن أبي الرِّجَال ثِقَة"],[1243,"وَمُحَمّد بن زيد بن مهَاجر ثِقَة"],[1244,"وَقَالَ احْمَد بن حَنْبَل لَا يزَال بِالريِّ علم مَا دَامَ بهَا مُحَمَّد بن حميد يَعْنِي الرَّازِيّ حَيا قَالَ أَبُو عبد الرَّحْمَن قدم علينا مُحَمَّد بن حميد يَعْنِي الرَّازِيّ وَكَانَ أبي بالعسكر فَلَمَّا خرج قدم أبي وَكَانَ اصحابه يسألونه عَن بن حميد فَقَالَ لي مَا لهَؤُلَاء يَسْأَلُونِي عَن بن حميد قلت قدم هَا هُنَا فَحَدثهُمْ بِأَحَادِيث لَا يعرفونها قَالَ لي كتبت عَنهُ قلت نعم كتبت عَنهُ جُزْءا قَالَ اعْرِض عَليّ فعرضتها عَلَيْهِ فَقَالَ اما حَدِيثه عَن بن الْمُبَارك وَابْن جريج فَهُوَ صَحِيح فاما حَدِيثه عَن أهل الرّيّ فَهُوَ أعلم نَا الْحسن بن صَدَقَة نَا بن أبي خَيْثَمَة قَالَ سُئِلَ يحيى بن معِين عَن مُحَمَّد بن حميد الرَّازِيّ فَقَالَ ثِقَة لَيْسَ بِهِ بَأْس ذَا رَأْي كيس"],[1245,"نَا أَبُو هُرَيْرَة مُحَمَّد بن عَليّ الْأَنْطَاكِي قَالَ قَالَ أَبُو زرْعَة الدِّمَشْقِي سَأَلَني يحيى بن معِين عَن مُحَمَّد بن عَائِذ فَقَالَ كَيفَ صَاحبكُم بن عَائِذ قلت بِخَير يَا أَبَا زَكَرِيَّا ترى ان تكْتب عَنهُ وَهُوَ يعْمل على الْخراج قَالَ نعم"],[1246,"وَقَالَ عَليّ بن الْمَدِينِيّ كَانَ مُحَمَّد بن فُضَيْل ثِقَة ثبتا فِي الحَدِيث وَمَا أقل سقط حَدِيثه"],[1247,"وَقَالَ عَليّ أَيْضا مُحَمَّد بن معن بن مُحَمَّد بن معن بن نَضْلَة بن عَمْرو الْغِفَارِيّ ثِقَة"],[1248,"مُحَمَّد بن الْحَارِث الْحَارِثِيّ ثِقَة قَالَه عبيد الله بن عمر القواريري"],[1249,"مُحَمَّد بن مُوسَى بن أبي عبد الله الْمَدِينِيّ قَالَ احْمَد بن صَالح هَذَا شيخ ثِقَة من الفطريين من أهل الْمَدِينَة حسن الحَدِيث قَلِيل الحَدِيث"],[1250,"وَقَالَ احْمَد بن صَالح مُحَمَّد بن أبي حميد ثِقَة لَا شكّ فِيهِ حسن الحَدِيث روى عَنهُ أهل الْمَدِينَة يَقُولُونَ حَمَّاد وَغَيرهم يَقُولُونَ مُحَمَّد بن أبي حميد وَلَقَد قَالَ رجل حَمَّاد وَمُحَمّد اخوان ضعيفان وَهَذَا الرجل هُوَ الضَّعِيف إِذْ يضعف رجلا لم يخلقه الله حمادا أَو لم يَكُونَا اخوين قطّ إِنَّمَا هُوَ وَاحِد فَجعل وَاحِدًا اثْنَيْنِ ثمَّ جَعلهمَا ضعيفان فَمن أَضْعَف من هَذَا واكذب إِذْ يبسط لِسَانه على من لَا يعرف وَلَا يجوز لأحد ان يَقُول فِي رجل انه ضَعِيف الا رجل قد اجْمَعْ عَلَيْهِ بالتكذيب فَيُقَال هَذَا كَذَّاب"],[1251,"قَالَ مُحَمَّد بن عبد الله بن سُلَيْمَان مُحَمَّد بن عقبَة أَبُو جَعْفَر الشَّيْبَانِيّ ثِقَة حدث عَنهُ أَبُو كريب وَعبيد بن يعِيش وشيوخنا"],[1252,"وَقَالَ أَبُو نعيم فِي أَصْحَاب سُفْيَان لَيْسَ مِنْهُم أحد مثل أبي احْمَد الزبيرِي واسْمه مُحَمَّد بن عبد الله بن الزبير"],[1253,"قَالَ عُثْمَان كَانَ بن فُضَيْل صَدُوقًا وَكَانَ كثير الْوَهم كثير الْخَطَأ"],[1254,"قَالَ احْمَد مُحَمَّد بن شُعَيْب بن شَابُور مَا أرى بِهِ بَأْسا وَكَانَ رجلا عَاقِلا"],[1255,"قَالَ يحيى مُحَمَّد بن دِينَار الطَّاحِي ضَعِيف وَقَالَ مرّة أُخْرَى مُحَمَّد بن دِينَار الطَّاحِي ثفة لَيْسَ بِهِ بَأْس كَانَ على مسَائِل سوار لم يكن لَهُ كتاب"],[1256,"مُحَمَّد بن عبد الْوَاحِد بن أبي حزم الْقطعِي وَكَانَ صَاحب سنة وَكَانَ حَمَّاد بن زيد يقدمهُ روى عَنهُ عبيد الله بن عمر القواريري"],[1257,"قَالَ عُثْمَان بن أبي شيبَة مُحَمَّد بن الْحسن الْأَسدي ثِقَة صَدُوق قلت هُوَ حجَّة قَالَ اما حجَّة فَلَا وَهُوَ ضَعِيف"],[1258,"وَقَالَ عُثْمَان كَانَ بن الْأَصْبَهَانِيّ ثِقَة صَدُوقًا يَعْنِي مُحَمَّد بن عبد الرَّحْمَن"],[1259,"وَمُحَمّد بن بشر الْعَبْدي ثِقَة ثَبت إِذا كَانَ يحدث من كِتَابه"],[1260,"وَمُحَمّد بن جحادة ثِقَة لَا بَأْس بِهِ"],[1261,"مُحَمَّد بن سَوَاء كَانَ يزِيد بن زُرَيْع يَقُول عَلَيْكُم بِهِ"],[1262,"مُحَمَّد بن عبد الْملك بن أبي الشَّوَارِب شيخ صَدُوق لَا بَأْس بِهِ قَالَه عُثْمَان بن أبي شيبَة"],[1263,"نَا الْحسن بن احْمَد عَن عَبَّاس قَالَ سَأَلت يحيى أَيّمَا اعْجَبْ إِلَيْك فِي الْأَعْمَش عِيسَى بن يُونُس أَو حَفْص بن غياث أَو أَبُو مُعَاوِيَة فَقَالَ أَبُو مُعَاوِيَة نَا الْحسن بن صَدَقَة قَالَ نَا بن أبي خَيْثَمَة قَالَ نَا يحيى بن معني قَالَ قَالَ لنا وَكِيع من تكرمون قُلْنَا نكرم أَبَا مُعَاوِيَة قَالَ اما انه كَانَ يعد علينا فِي حَيَاة الْأَعْمَش ألف وَسبع مائَة فَقلت لأبي مُعَاوِيَة ان وكيعا قَالَ كَذَا وَكَذَا فَقَالَ صدق وَلَكِنِّي مَرضت مرضة فأنسيت أَربع مائَة نَا عبد الله بن مُحَمَّد نَا مَحْمُود بن غيلَان قَالَ سَمِعت شَبابَة يَقُول جَاءَ أَبُو مُعَاوِيَة حَتَّى جلس فِي مجْلِس شُعْبَة فَقَالَ من هَذَا انْظُرُوا فَإِذا هُوَ أَبُو مُعَاوِيَة فَقَالَ يَا أَبَا مُعَاوِيَة سَمِعت حَدِيث كَذَا وَكَذَا من الْأَعْمَش قَالَ نعم فَقَالَ شُعْبَة هَذَا صَاحب الْأَعْمَش فَاعْرِفُوهُ نَا عبد الله بن مُحَمَّد قَالَ نَا مَحْمُود بن غيلَان قَالَ قَالَ أَبُو نعيم سَمِعت الْأَعْمَش يَقُول لأبي مُعَاوِيَة اما أَنْت فقد ربطت رَأس كيسك"],[1264,"قَالَ يحيى مُحَمَّد بن الْفرج لَيْسَ بِهِ بَأْس وَهُوَ الَّذِي يحدث عَن مُحَمَّد بن الزبْرِقَان"],[1265,"وَمُحَمّد بن ثَوْر ثِقَة"],[1266,"وَمُحَمّد بن مَرْوَان الْعقيلِيّ شيخ بَصرِي لَيْسَ بِهِ بَأْس قَالَ يحيى قد كتبت عَنهُ"],[1267,"وَقَالَ مُحَمَّد بن إِسْمَاعِيل كُوفِي ثِقَة وَأَبوهُ اسْمه رَاشد"],[1268,"وَأَبُو مُوسَى مُحَمَّد بن الْمثنى الزَّمن ثِقَة"],[1269,"وَمُحَمّد بن حمير قَالَ احْمَد مَا علمت الا خيرا"],[1270,"وَقَالَ مُحَمَّد بن قيس الْأَسدي ثِقَة ثِقَة"],[1271,"وَمُحَمّد بن هِلَال قَالَ سَمِعت عمر بن عبد الْعَزِيز شيخ ثِقَة"],[1272,"مُحَمَّد بن مهْرَان الْجمال أَبُو جَعْفَر لَيْسَ بِهِ بَأْس قَالَه يحيى"],[1273,"قَالَ وَأَبُو الْأَحْوَص مُحَمَّد بن حَيَّان ثِقَة"],[1274,"وَمُحَمّد بن ربيعَة الْكلابِي صَدُوق ثِقَة"],[1275,"وَمُحَمّد بن كناسَة ثِقَة"],[1276,"وَأَبُو سُفْيَان المعمري ثِقَة واسْمه مُحَمَّد بن حميد قَالَه أَبُو خَيْثَمَة"],[1277,"مُحَمَّد بن عبد الله الطَّائِفِي لَيْسَ بِهِ باس قَالَه يحيى"],[1278,"وَقَالَ مُحَمَّد بن عبد الله الْعَدنِي"],[1279,"وَمُحَمّد بن أبي عُبَيْدَة الَّذِي يحدث أَبوهُ عَن الْأَعْمَش ثِقَة هُوَ وَأَبوهُ"],[1280,"وَمُحَمّد بن الْقَاسِم الْأَسدي ثِقَة قَالَ يحيى وَقد كتبت عَنهُ"],[1281,"وَمُحَمّد بن عبد الله أَبُو احْمَد الزبيرِي ثِقَة"],[1282,"قَالَ بن معِين مُحَمَّد بن الْمُبَارك شيخ الشَّام بعد أبي مسْهر رَوَاهُ أَبُو زرْعَة الدِّمَشْقِي عَن مَحْمُود بن خَالِد عَن يحيى"],[1283,"قَالَ وَمُحَمّد بن إِبْرَاهِيم بن الْحَرْث ثِقَة"],[1284,"وَمُحَمّد بن قيس الْهَمدَانِي ثِقَة"],[1285,"وَمُحَمّد بن رَاشد أَبُو نَضْلَة الْقرشِي صَالح"],[1286,"وَمُحَمّد بن عبد الرَّحْمَن الطفَاوِي صَالح"],[1287,"وَمُحَمّد بن إِبْرَاهِيم صَالح"],[1288,"وَمُحَمّد بن أبي الْمليح الْهُذلِيّ لَا بَأْس بِهِ"],[1289,"وَمُحَمّد بن عمرَان بن طَلْحَة لَا بَأْس بِهِ"],[1290,"وَمُحَمّد بن عمار مديني ثِقَة"],[1291,"وَمُحَمّد بن قيس الْأَسدي ثِقَة"],[1292,"وَمُحَمّد بن مهزم الرمام ثِقَة"],[1293,"وَمُحَمّد بن عقبَة الرِّفَاعِي ثِقَة"],[1294,"وَمُحَمّد بن أبي حرَّة ثِقَة"],[1295,"وَمُحَمّد بن تَمِيم الرَّاسِبِي ثِقَة"],[1296,"وَمُحَمّد بن سُلَيْمَان الْمَكِّيّ ثِقَة"],[1297,"وَمُحَمّد بن ذكْوَان ثِقَة روى عَنهُ شُعْبَة"],[1298,"وَأَبُو عون الثَّقَفِيّ ثِقَة"],[1299,"وَمُحَمّد بن عبيد"],[1300,"وَمُحَمّد بن مرّة ثِقَة روى عَنهُ شُعْبَة"],[1301,"وَمُحَمّد بن ربيعَة ثِقَة"],[1302,"وَمُحَمّد بن مُسلم ثِقَة"],[1303,"وَمُحَمّد بن أبي الْفُرَات ثِقَة"],[1304,"وَمُحَمّد بن أبي الرازقي ثِقَة"],[1305,"وَمُحَمّد بن دِينَار ثِقَة"],[1306,"وَمُحَمّد بن رَاشد قَالَ فِيهِ بن الْمُبَارك صَدُوق اللِّسَان واراه اتهمَ بِالْقدرِ"],[1307,"حَدثنِي عبد الْكَرِيم بن احْمَد بن الرواس بِالْبَصْرَةِ قَالَ نَا مُحَمَّد بن يحيى الْأَزْدِيّ قَالَ حَدثنِي عَليّ بن عَاصِم قَالَ خرجت الى مَنْصُور بن الْمُعْتَمِر فَدخلت الْكُوفَة يَوْم مَاتَ فَقَعَدت أبْكِي فَقَالَ لي شيخ قَاعد يَا فَتى مَالك تبْكي قلت خرجت من وَاسِط الى هَذَا شيخ فَوَجَدته قد مَاتَ فَقَالَ أَلا أدلك على من شهد عرس أمه قلت بلَى قَالَ فَأَنا هُوَ فَإِذا هُوَ حُصَيْن بن عبد الرَّحْمَن فَكتبت عَنهُ نَا مُحَمَّد بن مخلد نَا الْعَبَّاس بن مُحَمَّد قَالَ نَا أَبُو بكر بن أبي الْأسود قَالَ سَمِعت عبد الرَّحْمَن بن مهْدي يَقُول لم يكن بِالْكُوفَةِ اثْبتْ من أَرْبَعَة مَنْصُور وَأَبُو حَفْص وَسَلَمَة بن كهيل وَعَمْرو بن مرّة وَكَانَ مَنْصُور اثْبتْ أهل الْكُوفَة"],[1308,"قَالَ يحيى مَنْصُور بن أبي الْأسود ثِقَة"],[1309,"مَنْصُور بن سعد روى عَن بديل بن ميسرَة روى عَنهُ عبد الرَّحْمَن بن مهْدي وَمَنْصُور بن سعد شيخ بَصرِي صَاحب لولو لم يكن بِهِ بَأْس"],[1310,"مَنْصُور بن حَيَّان كُوفِي روى عَنهُ يزِيد بن هَارُون ومروان الْفَزارِيّ وَهُوَ ثِقَة قَالَه يحيى"],[1311,"قَالَ وَمَنْصُور بن عبد الرَّحْمَن الغداني صَالح روى عَنهُ شُعْبَة وَإِسْمَاعِيل وَهُوَ الأشل وَقَالَ احْمَد ثِقَة"],[1312,"قَالَ وَمَنْصُور بن زَاذَان ثِقَة"],[1313,"أَبُو سَلمَة مَنْصُور بن سَلمَة ثِقَة قَالَه يحيى مَاتَ بِالْمصِّيصَةِ"],[1314,"قَالَ بن عُيَيْنَة حَدثنِي مسعر بن كدام وَكَانَ من معادن الصدْق"],[1315,"وَقَالَ احْمَد مسعر بن حبيب الْجرْمِي ثِقَة حدث عَنهُ يزِيد بن هَارُون"],[1316,"نَا احْمَد بن مسعر بن عَمْرو الزبيرِي بِمصْر قَالَ نَا مُحَمَّد بن عبد الله بن عبد الحكم قَالَ نَا أَيُّوب بن سُوَيْد قَالَ حَدثنِي الصدوق مَالك بن أنس نامكرم قَالَ نايزيد بن الْهَيْثَم قَالَ سَمِعت يحيى بن معِين يَقُول أوثق النَّاس فِي الزُّهْرِيّ مَالك بن أنس"],[1317,"وَقَالَ يحيى مَالك بن مغول ثِقَة"],[1318,"أَبُو غَسَّان مَالك بن إِسْمَاعِيل صَدُوق ثَبت متقن امام من الْأَئِمَّة وَلَوْلَا كَلمته لما كَانَ يفوقه بِالْكُوفَةِ أحد قَالَه عُثْمَان بن أبي شيبَة"],[1319,"وَقَالَ يحيى الْمُغيرَة بن نعْمَان ثِقَة"],[1320,"وَقَالَ احْمَد الْمُغيرَة بن مُسلم أَبُو سَلمَة السراج مَا أرى بِهِ بَأْسا روى عَنهُ الثَّوْريّ وَهُوَ اخو عبد الْعَزِيز بن مُسلم"],[1321,"والمغيرة بن عبد الرَّحْمَن الْحزَامِي من ولد حَكِيم بن حزَام مَا أرى بِهِ بَأْسا حدث عَنهُ بن مهْدي وَكَانَ عِنْده كتاب عَن أبي الزِّنَاد"],[1322,"مُغيرَة بن زِيَاد الْموصِلِي لَيْسَ بِهِ بَأْس قَالَه يحيى وَقَالَ مرّة أُخْرَى ثِقَة"],[1323,"مُغيرَة بن مقسم ثِقَة يَقُولُونَ انه سمع من إِبْرَاهِيم ثَلَاث مائَة وَسبعين حَدِيثا اونحوه دون الأربعمائة وَلكنه يُدَلس عَن أبي معشر وَغَيره"],[1324,"مُعَاوِيَة بن عَمْرو بن غلاب ثِقَة يروي عَنهُ يحيى بن سعيد وَحَمَّاد بن سَلمَة وهوجد الْغلابِي قَالَ ذَلِك يحيى"],[1325,"وَقَالَ عُثْمَان مُعَاوِيَة بن هِشَام رجل صدق وَلَيْسَ بِحجَّة"],[1326,"مُعَاوِيَة بن إِسْحَاق ثِقَة قَالَه احْمَد"],[1327,"وَقَالَ يحيى مُعَاوِيَة بن صَالح صَالح"],[1328,"وَقَالَ أَبُو العبيدين اسْمه مُعَاوِيَة بن سُبْرَة بن الْحصين النميري كُوفِي ثِقَة"],[1329,"مُعَاوِيَة بن عبد الْكَرِيم لَيْسَ بِهِ بَأْس نَا الْحسن بن صَدَقَة قَالَ ناابن أبي خَيْثَمَة نَا فُضَيْل بن عبد الْوَهَّاب نَا مُعَاوِيَة بن عبد الْكَرِيم الضال مولى البكرات ثِقَة نَا الْحُسَيْن قَالَ قَالَ عَيَّاش سَمِعت سوارا قَاضِيا يَقُول إِنَّمَا سمي مُعَاوِيَة الضال لِأَنَّهُ ضل من اصحابه فِي طَرِيق مَكَّة"],[1330,"قَالَ يحيى مُعَاوِيَة بن عمار الدهني لَيْسَ بِهِ بَأْس"],[1331,"وَقَالَ احْمَد مُوسَى بن عَليّ ثِقَة ثِقَة"],[1332,"مُوسَى بن قيس الصَّغِير لَيْسَ بِهِ بَأْس قَالَه يحيى وَقَالَ احْمَد مَا أعلم الا خيرا"],[1333,"مُوسَى بن عقبَة لَيْسَ بِهِ بَأْس قَالَه يحيى"],[1334,"وَقَالَ احْمَد فِي مُوسَى بن عقبَة وَمُحَمّد بن عجلَان جَمِيعًا ثِقَة"],[1335,"وَقَالَ بن عمار فِي مُوسَى الطَّحَّان مَا سَمِعت أحدا يَقُول فِيهِ الا خيرا"],[1336,"ومُوسَى الْحزَامِي ثِقَة وَلَيْسَ هُوَ الطَّحَّان"],[1337,"وَقَالَ يحيى الْقطَّان فِي مُوسَى الْجُهَنِيّ كَانَ ثِقَة"],[1338,"وَقَالَ بن معِين مُوسَى بن يسَار عَم مُحَمَّد بن إِسْحَاق هُوَ ثِقَة"],[1339,"ومُوسَى بن يَعْقُوب الزمعِي ثِقَة"],[1340,"وَقَالَ بن نمير عَن مُوسَى بن قيس كَانَ ثِقَة روى عَنهُ النَّاس وَهُوَ حضرمي"],[1341,"وروى بن نمير عَن أبي شهَاب الْهُذلِيّ قَالَ بن عمار وَهُوَ مُوسَى بن نَافِع وَهُوَ ثِقَة"],[1342,"قَالَ يحيى مُوسَى بن يسَار أَبُو الطّيب وَكَانَ من أهل الْمَدَائِن روى عَنهُ شَبابَة وَهُوَ ثِقَة"],[1343,"وَقَالَ مُوسَى بن أبي كثير هُوَ أَبُو الصَّباح وَهُوَ ثِقَة وَهُوَ مرجئ"],[1344,"ومُوسَى بن سروان هُوَ بَصرِي معلم روى عَنهُ أَبُو عُبَيْدَة الْحداد وَهُوَ ثِقَة"],[1345,"قَالَ احْمَد مُوسَى بن الْمسيب هُوَ أَبُو جَعْفَر مَا أعلم الا خيرا"],[1346,"مُوسَى بن عبد الْعَزِيز ثِقَة قَالَه يحيى"],[1347,"أَبُو خلف مُوسَى بن خلف روى عَنهُ عَفَّان وَقَالَ كَانَ يعد من النبلاء"],[1348,"مُوسَى بن عبد الحميد قَالَ احْمَد بن حَنْبَل هُوَ جَار لنا حسن الْهَيْئَة كتبنَا عَنهُ قبل ان نكتب عَن يَعْقُوب بن إِبْرَاهِيم"],[1349,"وَفِي رِوَايَة عَبَّاس عَن يحيى قَالَ مُوسَى بن وردان قاص بِمصْر وَهُوَ صَالح الحَدِيث"],[1350,"مُوسَى بن عبد الْعَزِيز الْعَدنِي روى عَنهُ إِسْحَاق بن أبي إِسْرَائِيل"],[1351,"الْمسيب بن شريك ثِقَة انكر عَلَيْهِ حَدِيث رَوَاهُ عَن الْأَعْمَش قَالَه احْمَد نَا عُثْمَان بن احْمَد بن عبد الله بن السماك قَالَ سَأَلت عبد الله بن سُلَيْمَان بن الْأَشْعَث السجسْتانِي عَن الْمسيب بن شريك قَالَ ثِقَة قَالَ عُثْمَان وَسَأَلت بن صاعد فَقَالَ كلَاما مَعْنَاهُ كتبنَا عَن بن علوبة غرائب من حَدِيثه يَعْنِي الْمسيب بن شريك"],[1352,"قَالَ بن شاهين سَمِعت عبد الله بن سُلَيْمَان بن الْأَشْعَث يَقُول أصح حَدِيثا فِي التَّسْبِيح حَدِيث الْعَبَّاس"],[1353,"مطرف أَبُو بكر الشقري ثِقَة قَالَه يحيى"],[1354,"ومطرف بن طريف ثِقَة وَهُوَ الخارفي وَقَالَ عُثْمَان مطرف بن طريف ثِقَة صَدُوق وَلَيْسَ بثبت"],[1355,"وَقَالَ يحيى مطرف بن معقل الشقري بَصرِي ثِقَة يروي عَنهُ وَكِيع وَحدث عَن بن شَدَّاد"],[1356,"وَقَالَ احْمَد فِي مطرف بن معقل ثِقَة وَزِيَاد"],[1357,"المستمر بن الريان كَانَ ثِقَة قَالَه يحيى بن سعيد وَقَالَ بن معِين هُوَ ثِقَة وَقد رأى أنس بن مَالك"],[1358,"معرف بن وَاصل ثِقَة ثِقَة وثقة احْمَد وَيحيى"],[1359,"وَقَالَ يحيى مُجَاهِد بن أبي رَاشد ثِقَة وَهُوَ أَخُو ربيع بن أبي رَاشد"],[1360,"وَمُجاهد بن حُبَيْش بن يزِيد بن عَامر الْمَازِني ثِقَة"],[1361,"وَمصْعَب بن سليم ثِقَة وَقد حدث عَنهُ وَكِيع"],[1362,"وَمصْعَب بن سَلام قَالَ يحيى كتبت عَنهُ لَيْسَ بِهِ بَأْس"],[1363,"وَمصْعَب بن الْمِقْدَام كَانَ صَالحا لَا بَأْس بِهِ"],[1364,"ومرزوق أَبُو بكير مُؤذن لتيم ثِقَة"],[1365,"ومرزوق الشَّامي هُوَ مرزق أَبُو عبد الله بَصرِي وَلَيْسَ بِهِ بَأْس"],[1366,"قَالَ احْمَد مهْدي بن مَيْمُون ثِقَة ثِقَة حدث عَنهُ يحيى بن سعيد وَعبد الرَّحْمَن ووثقة يحيى أَيْضا"],[1367,"وَقَالَ مَكْحُول أزدي بَصرِي ثِقَة"],[1368,"مستلم بن سعيد صَالح قَالَه يحيى وَقَالَ يزِيد بن هَارُون كَانَ مستلم بن سعيد عندنَا هَاهُنَا بواسط وَكَانَ لَا يشرب المَاء إِلَّا كل جُمُعَة وَجعل يثني عَلَيْهِ"],[1369,"وَقَالَ يحيى المشمعل بن إِيَاس بَصرِي ثِقَة روى عَنهُ يحيى وَعبد الرَّحْمَن"],[1370,"والمشمعل بن ملْحَان صَالح الحَدِيث إِلَّا أَن المشمعل بن إِيَاس أوثق مِنْهُ كثيرا"],[1371,"وَقَالَ يحيى فِي رِوَايَة بن أبي خَيْثَمَة المشمعل الَّذِي روى عَنهُ يحيى الْقطَّان ثِقَة"],[1372,"قَالَ وَمُقَاتِل بن حَيَّان ثِقَة لَيْسَ بِهِ بَأْس رجل صَالح وَقَالَ عبد الله بن مَحْمُود الْمروزِي هُوَ من أهل بَلخ يعد فِي المراوزة وَكَانَ ثبتا فِي الحَدِيث وَيذكر بِالْعبَادَة"],[1373,"وَقَالَ يحيى بن سعيد مَسْعُود بن عَليّ لم يكن بِهِ بَأْس"],[1374,"ومسعود بن سعد الْجعْفِيّ ثِقَة مَأْمُون روى عَنهُ عبد الرَّحْمَن بن مهْدي قَالَه يحيى"],[1375,"وَقَالَ بن عمار مخول بن رَاشد كُوفِي نهدي ثِقَة"],[1376,"مُسلم بن أبي مُسلم الحناط مَا أرى بِهِ بَأْسا روى عَنهُ بن عُيَيْنَة وَابْن أبي ذِئْب قَالَه احْمَد"],[1377,"وَمُسلم القري حدث عَنهُ شُعْبَة قَالَ احْمَد وَمَا أرى بِهِ بَأْسا"],[1378,"قَالَ يحيى أَو فَرْوَة الْجُهَنِيّ الْكُوفِي اسْمه فَسلم بن سَالم وَهُوَ ثِقَة"],[1379,"وَمُسلم بن عبيد صَالح"],[1380,"وَمُسلم بن عبد الله أَبُو النَّضر ثِقَة"],[1381,"وسمل الْحَنَفِيّ الَّذِي حدث عَنهُ سُفْيَان قَالَ أَبُو نعيم كَانَ مُسلم أحد الثِّقَات المأمونين"],[1382,"وَقَالَ يحيى مُسلم النجار ثِقَة"],[1383,"وَمُسلم بن خَالِد الزنْجِي ثِقَة"],[1384,"وَمُسلم بن إِبْرَاهِيم ثِقَة مَأْمُون"],[1385,"وَالْمُخْتَار بن فلفل الَّذِي يروي عَن أنس بن مَالك ثِقَة"],[1386,"وَالْمُخْتَار بن عَمْرو ثِقَة"],[1387,"ومطر الْوراق قَالَ مرّة هُوَ ضَعِيف الحَدِيث وَكَانَ قَرِيبا من سنّ بن وهب وَكَانَ يُرْسل الْأَحَادِيث يَقُول عَن جُوَيْبِر وَلم يلق جويبرا وَنَحْو هَذَا هُوَ قَلِيل الحَدِيث إِلَّا أَن حَدِيثه الطَّوِيل عَن عَليّ بن سُلَيْمَان يُمكن أَن يكون قد لَقِي عَليّ بن سُلَيْمَان وَقد روى هَذَا الحَدِيث الطَّوِيل حَدِيث أبي ذَر الطَّوِيل غَيره وَهُوَ صَحِيح"],[1388,"نَا مُحَمَّد بن مخلد نَا الْعَبَّاس بن مُحَمَّد قَالَ سَمِعت يحيى بن معِين يَقُول مِسْكين بن مَيْمُون مُؤذن الرملة ثِقَة"],[1389,"مِسْكين بن بكير الْحذاء قَالَ بن عمار يَقُولُونَ أَنه ثِقَة وَلم أسمع مِنْهُ وَهُوَ حراني"],[1390,"الْمفضل بن مهلهل ثِقَة قَالَه عَليّ بن الْمَدِينِيّ"],[1391,"وَقَالَ يحيى الْمفضل بن لَاحق أَبُو بشر يحدث عَنهُ أَبُو عُبَيْدَة الْحداد ثِقَة"],[1392,"والمفضل بن يُونُس ثِقَة"],[1393,"ومفضل بن فضَالة مصري رجل صدق وَكَانَ إِذا جَاءَهُ رجل انْكَسَرت يَده أَو رجله جبرها وَكَانَ يصنع الأرحية"],[1394,"مَيْمُون بن مُوسَى الْمرَائِي قَالَ احْمَد مَا أرى بِهِ بَأْسا وَكَانَ يُدَلس وَكَانَ لَا يَقُول حَدثنَا الْحسن"],[1395,"وَمَيْمُون بن مهْرَان ثِقَة وَذكره أَحْمد بِخَير"],[1396,"وَأَبُو مَنْصُور اسْمه مَيْمُون ثِقَة قَالَه يحيى"],[1397,"وَأَبُو يحيى الْأَعْرَج ثِقَة اسْمه مصدع مولى عبد الله بن عَمْرو"],[1398,"معَاذ بن عفراء لَيْسَ بِهِ بَأْس ثِقَة"],[1399,"ومعاذ بن الْعَلَاء أَبُو غَسَّان بَصرِي ثِقَة"],[1400,"ومعاذ بن هِشَام صَدُوق وَلَيْسَ بِحجَّة"],[1401,"والمنهال بن خَليفَة صُوَيْلِح"],[1402,"والمنهال بن عَمْرو ثِقَة"],[1403,"مَحل الضَّبِّيّ لَيْسَ بِهِ بَأْس"],[1404,"وملازم بن عَمْرو وثقة أَحْمد وَيحيى"],[1405,"قَالَ أَحْمد محَارب بن دثار ثِقَة"],[1406,"مُؤَمل الْمَكِّيّ ثِقَة قَالَه يحيى"],[1407,"مطرح الْأَسدي قَالَ بن عمار روى عَنهُ أَبُو بكر بن عَيَّاش وَابْن نمير وَأَبُو مُعَاوِيَة وَالنَّاس قد رووا عَنهُ وماسمعت فِيهِ إِلَّا خيرا"],[1408,"وَقَالَ أَحْمد بن صَالح مقسم ثِقَة ثَبت لَا شكّ فِيهِ"],[1409,"قَالَ يحيى مرجى بن رَجَاء لَيْسَ بِهِ بَأْس وَقَالَ مرّة أُخْرَى لَيْسَ حَدِيثه بِشَيْء"],[1410,"ومروان بن مُحَمَّد الطاطري ثِقَة"],[1411,"ومروان بن شُجَاع ثِقَة"],[1412,"وَأَبُو لبَابَة الَّذِي يروي عَنهُ حَمَّاد بن زيد اسْمه مَرْوَان مولى عَائِشَة بَصرِي ثِقَة"],[1413,"مَرْوَان بن مُعَاوِيَة ثِقَة قَالَه أَحْمد"],[1414,"مطلب بن زِيَاد ثِقَة قَالَه أَحْمد"],[1415,"وَمُضر الْقَارِي ثِقَة قَالَه إِبْرَاهِيم بن عبد الله"],[1416,"مسلمة بن نَوْفَل يروي عَنهُ عِيسَى بن يُونُس ووكيع وَهُوَ ثِقَة قَالَه يحيى"],[1417,"مسلمة بن عَلْقَمَة يروي عَنهُ عبيد الله بن عمار وَكَانَ عَالما بِحَدِيث دَاوُد بن أبي هِنْد حَافِظًا وَكَانَ يُقَال فِي حفظَة شَيْء"],[1418,"نَا مُحَمَّد بن مُحَمَّد بن سُلَيْمَان الباغندي قَالَ حَدثنِي جَعْفَر بن عبد الْوَاحِد عَن مُحَمَّد بن عِيسَى عَن بن الْمُبَارك قَالَ لَو لم يُؤْتى مخلد بن حُسَيْن إِلَّا ليعلم مِنْهُ الْأَدَب كَانَ يَنْبَغِي أَن يُؤْتى"],[1419,"وَقَالَ مخلد بن يزِيد الْحَرَّانِي لَيْسَ بِهِ باس"],[1420,"وَمعمر بن سُلَيْمَان ثِقَة"],[1421,"وَمعمر بن قيس لَيْسَ بِهِ باس"],[1422,"مهْرَان بن أبي عمر الرَّازِيّ صَدُوق إِلَّا أَن أَكثر رِوَايَته عَن سُفْيَان خطأ قَالَه عُثْمَان"],[1423,"وَقَالَ يحيى مطعم شيخ من أهل الشَّام ثِقَة يروي عَنهُ الثَّوْريّ"],[1424,"معَان بن حمضة حدث عَن أَحْمد وَقَالَ كَانَ شَيخا صَدُوقًا وَكَانَ بن مهْدي حمل عَنهُ"],[1425,"مجَالد بن سعيد ثِقَة قَالَه يحيى"],[1426,"مُسَافر الْجَصَّاص قَالَ وَكِيع كَانَ ثبتا"],[1427,"ومبارك بن فضَالة ثِقَة"],[1428,"ومبارك بن حسان ثِقَة"],[1429,"مُبشر بن مكسر يكنى أَبَا بشر يحدث عَنهُ يُونُس بن مُحَمَّد لَيْسَ بِهِ بَأْس وَهُوَ بَصرِي"],[1430,"والمثنى بن سعيد ثِقَة والمثنى القسام بَصرِي لَيْسَ بِهِ باس سمع من أنس"],[1431,"ومرحوم بن عبد الْعَزِيز ثِقَة وَثَّقَهُ احْمَد وَقَالَ هُوَ الْعَطَّار"],[1432,"أَبُو نَضرة اسْمه الْمُنْذر بن قِطْعَة ثِقَة"],[1433,"الْمُنْذر بن ثَعْلَبَة روى عَنهُ أَبُو قطن وَكَانَ خيرا"],[1434,"وَأَبُو الْخَيْر مرْثَد بن عبد الله رجل صدق وَكَانَ عِنْد أهل بصر مثل عَلْقَمَة عِنْد أهل الْكُوفَة قَالَه يحيى"],[1435,"مُخَارق بن خَليفَة الأحمسي ثِقَة ثِقَة قَالَه أَحْمد"],[1436,"الْمِقْدَام بن شُرَيْح بن هاني ثِقَة قَالَه يحيى"],[1437,"مهلب بن أبي حَبِيبَة شيخ ثِقَة قَالَه أَحْمد"],[1438,"مُحرز بن عون ثِقَة لَيْسَ بِهِ بَأْس"],[1439,"قَالَ نَا عبد الله بن مُحَمَّد الْبَغَوِيّ نَا أَحْمد بن مُحَمَّد بن حَنْبَل نَا أَبُو سعيد مولى بني هَاشم وَعبد الصَّمد قَالَا ثَنَا مُحَرر بن قعنب قَالَ أَبُو عبد الله وَهُوَ ثِقَة قَالَ سَمِعت الضَّحَّاك يَقُول كل مُسكر حرَام"],[1440,"وَقَالَ احْمَد أَبُو خازم ميسرَة روى عَنهُ الثَّوْريّ"],[1441,"وَقَالَ يحيى مكي بن إِبْرَاهِيم صَالح نَا عبد الله بن عَمْرو العمركي الْبَلْخِي قَالَ سَمِعت عبد الصَّمد بن الْفضل يَقُول سَمِعت مكي يَقُول حججْت سِتِّينَ حجَّة وَتَزَوَّجت سِتِّينَ امْرَأَة وجاورت بِالْبَيْتِ عشر سِنِين وكتبت عَن سَبْعَة عشر نفسا من التَّابِعين وَلَو علمت أَن النَّاس يَحْتَاجُونَ إِلَى علمي لما كتبت دون التَّابِعين عَن أحد"],[1442,"وَقَالَ يحيى مهَاجر أَبُو خَالِد مولى البكرات صَالح"],[1443,"ومنبوذ ثِقَة"],[1444,"ومحبوب بن الْحسن الَّذِي يحدث عَن خَالِد الْحذاء لَيْسَ بِهِ بَأْس"],[1445,"وَمجمع بن يحيى صَالح"],[1446,"ومزاحم بن زفر ثِقَة صَالح"],[1447,"ومعن بن عبد الرَّحْمَن ثِقَة"],[1448,"ومعبد بن خَالِد ثِقَة"],[1449,"وَأَبُو شيبَة مورع كُوفِي لَيْسَ بِهِ باس"],[1450,"ومهند بن عَليّ ثِقَة"],[1451,"وَأَبُو صَالح الَّذِي روى عَنهُ التَّيْمِيّ اسْمه ميزَان وَهُوَ بَصرِي ثِقَة"],[1452,"وَأَبُو خلدَة خَالِد"],[1453,"وَأَبُو صَالح الَّذِي روى عَنهُ إِسْمَاعِيل بن سَالم اسْمه ماهان كُوفِي ثِقَة قَالَ احْمَد أَبُو صَالح ماهان وَقَالَ بَعضهم اسْمه عبد الرَّحْمَن بن قيس أَخُوهُ طليق بن قيس"],[1454,"وَقَالَ احْمَد بن يُونُس كَانَ الْمعَافي بن عمرَان صَدُوق اللهجة وَكَانَ سُفْيَان يُسمى الْمعَافى بن عمرَان الياقوتة"],[1455,"نَا عمرَان بن الْحسن بن عَليّ بن مَالك قَالَ سَمِعت أَبَا عبد الله مُحَمَّد بن أَحْمد بن أبي خَيْثَمَة يَقُول وَذكر أَبَا بكر مُحَمَّد بن مُحَمَّد بن سُلَيْمَان بن الْحَارِث الباغندي فَقَالَ ثِقَة كثير الحَدِيث لَو كَانَ بالموصل لخرجتم إِلَيْهِ وَلكنه يتطرح عَلَيْكُم وَلَا تريدونه"],[1456,"نَا عمرَان بن الْحسن بن عَليّ بن مَالك قَالَ سَأَلت مُوسَى بن هَارُون الْبَزَّاز عَن أبي الْقَاسِم بن منيع فَقَالَ ثِقَة صَدُوق لَو جَازَ لإِنْسَان أَن يُقَال لَهُ فَوق الثِّقَة لقيل لَهُ قلت يَا أَبَا عمرَان فَإِن هَؤُلَاءِ يَتَكَلَّمُونَ فِيهِ فَقَالَ يحسدونه سمع بن عَائِشَة وَلم نسْمع وَذهب بِهِ إِلَيْهِ وَلم يذهب بِنَا بن منيع لَا يَقُول إِلَّا الْحق"],[1457,"نَا عثان بن عبدويه جَار إِبْرَاهِيم الْحَرْبِيّ قَالَ سَمِعت إِبْرَاهِيم الْحَرْبِيّ يَقُول ولد صاعد ثَلَاثَة أوثقهم يحيى بن مُحَمَّد بن صاعد بن كَاتب"],[1458,"سَمِعت أَبَا حَامِد بن أَسد الْمكتب يَقُول مَا رَأَيْت مثل عبد الله بن سُلَيْمَان بن الْأَشْعَث يَعْنِي فِي الْعلم وَذكر كلَاما كثيرا مَا ضَبطه الا إِبْرَاهِيم الْحَرْبِيّ واحسب انه قَالَ مَا رَأَيْت بعد إِبْرَاهِيم الْحَرْبِيّ مثله أَو كلَاما يشبه هَذَا"],[1459,"كَانَ سَالم يَقُول سلوا هَذَا يَعْنِي نَافِعًا وَقَالَ سُفْيَان بن عُيَيْنَة أَي حَدِيث أوثق من حَدِيث نَافِع وَقَالَ احْمَد بن صَالح الْمصْرِيّ كَانَ نَافِع حَافِظًا ثبتا لَهُ شَأْن روى عَنهُ صَفْوَان بن سليم وَزيد بن أسلم وَنَافِع أكبر من عِكْرِمَة عِنْد أهل الْمَدِينَة وأكثرهما وَعِكْرِمَة أعلمهما وأشدهما تبحرا فِي أَمر النَّاس وَالتَّفْسِير وَغير ذَلِك"],[1460,"قَالَ يحيى نَافِع بن أبي نعيم الْقَارِي ثِقَة"],[1461,"نَافِع مولى أبي قَتَادَة مَعْرُوف روى عَنهُ صَالح بن كيسَان قَالَه أَحْمد"],[1462,"وَقَالَ نَافِع بن عمر الجُمَحِي من الثِّقَات ثِقَة"],[1463,"وَنَافِع بن مَالك بن أبي عَامر يكنى أَبَا سُهَيْل وَهُوَ عَم مَالك بن أنس من الثِّقَات"],[1464,"وَنَافِع بن سرجس روى عَنهُ بن جشم لَا أَقُول إِلَّا خيرا"],[1465,"نَافِع أَبُو غَالب الْبَاهِلِيّ صَالح قَالَه يحيى"],[1466,"والنعمان بن رَاشد ثِقَة"],[1467,"وَأَبُو يُوسُف أوثق من أبي حنيفَة فِي الحَدِيث وَكَانَ أَبُو حنيفَة أنبل فِي نَفسه من أَن يكذب وَاسم أبي حنيفَة النُّعْمَان بن ثَابت"],[1468,"قَالَ يحيى النُّعْمَان بن أبي شيبَة الصَّنْعَانِيّ الجندي روى عَنهُ معمر وَعبد الرَّزَّاق أَحَادِيث يسيرَة وَهُوَ ثِقَة مَأْمُون كيس دين"],[1469,"وَأَبُو جَمْرَة الَّذِي روى عَن بن عَبَّاس اسْمه نصر بن عمرَان الضبعِي بَصرِي ثِقَة قَالَه بن معِين وَأحمد بن حَنْبَل"],[1470,"وَأَبُو الْمنْهَال الطَّائِي اسْمه نصر بن آوس يروي عَنهُ وَكِيع وَهُوَ ثِقَة قَالَه يحيى"],[1471,"وَقَالَ أَحْمد نصر بن بَاب إِنَّمَا أنكر النَّاس عَنهُ حَدِيثا حدث بِهِ عَن إِبْرَاهِيم الصايغ وَمَا كَانَ بِهِ بَأْس قيل لِأَحْمَد إِن أَبَا خَيْثَمَة قَالَ نصر بن بَاب كَذَّاب قَالَ مَا اجترى على هَذَا أَن أقوله اسْتغْفر الله"],[1472,"قَالَ يحيى النَّضر بن عَرَبِيّ ثِقَة"],[1473,"وَأَبُو معبد مولى بن عَبَّاس اسْمه نَافِذ مديني ثِقَة وَقَالَ مُصعب بن عبد الله وَكَانَ أصدق موَالِي بن عَبَّاس"],[1474,"النهاس بن قهم لَيْسَ بِهِ باس قَالَه يحيى"],[1475,"وَقَالَ نوح بن أبي بِلَال ثِقَة من أهل الْمَدِينَة حدث عَنهُ عَليّ بن ثَابت وَوَثَّقَهُ أَيْضا أَحْمد وَقَالَ روى عَنهُ الثَّوْريّ وَغَيره"],[1476,"نوح بن قيس شويخ صَالح الحَدِيث قَالَه يحيى"],[1477,"ونوح بن قيس الطَّاحِي ثِقَة قَالَه أَحْمد وَيحيى"],[1478,"أَبُو مِسْكين بَصرِي اسْمه نوح بن يحيى بن ربيعَة وَهُوَ ثِقَة قَالَه يحيى"],[1479,"ونوح بن دراج لَيْسَ بِهِ بَأْس"],[1480,"وناصع أَبُو الْعَلَاء مولى بني هَاشم روى عَنهُ عَليّ بن الْمَدِينِيّ وَقَالَ كَانَ ثِقَة"],[1481,"نَاجِية بن كَعْب صَالح وَقَالَ شُعْبَة لقِيت نَاجِية الَّذِي روى عَنهُ أَبُو إِسْحَاق فرأيته يلْعَب بالشطرنج"],[1482,"الضَّبِّيّ ثِقَة وَقَالَ سُفْيَان أَخْبرنِي نهشل بن مجمع الضَّبِّيّ وَكَانَ مرضيا"],[1483,"وَأَبُو حَازِم نَبْتَل روى عَنهُ إِسْمَاعِيل بن أبي خَالِد ثِقَة مَا أعلم روى عَنهُ غَيره قَالَه أَحْمد"],[1484,"وَقَالَ أَبُو معشر نجيح كَانَ صَدُوقًا وَلكنه لَا يُقيم الْأَسَانِيد"],[1485,"نجم أَبُو مُحَمَّد الْعَطَّار ثِقَة روى عَنهُ إِبْرَاهِيم بن عبد الله"],[1486,"قَالَ احْمَد الْوَلِيد بن أبي هِشَام ثِقَة الحَدِيث جدا وَقَالَ يحيى الْوَلِيد بن أبي هِشَام مولى عُثْمَان بن عَفَّان ثِقَة وَأَخُوهُ هِشَام بن زِيَاد لَيْسَ بِثِقَة"],[1487,"والوليد بن كثير ثِقَة قَالَه يحيى"],[1488,"والوليد بن أبي الْوَلِيد ثِقَة يرْوى عَنهُ أهل مصر"],[1489,"قَالَ أَحْمد الْوَلِيد بن جَمِيع لَيْسَ بِهِ بَأْس"],[1490,"والوليد بن خَالِد بن صَخْر الْأَعرَابِي وَكَانَ من أَصْحَاب شُعْبَة الثِّقَات"],[1491,"وَقَالَ أَحْمد بن صَالح الْوَلِيد بن الْمُغيرَة ثِقَة"],[1492,"والوليد بن قيس السكونِي ثِقَة وَقَالَ أَحْمد بن حَنْبَل اكتبوا عَن أبي همام واسْمه الْوَلِيد بن شُجَاع وَقَالَ أَبُو كريب أَبُو همام يَعْنِي السكونِي أقدم سَمَاعا مني كَانَ يمر بِنَا وَنحن نلعب بالخشب وَعَلِيهِ صَالِحَة وَهُوَ يكْتب الحَدِيث وَكَانَ مذْهبه مَذْهَب الْمَشَايِخ فَمَا جِئْت إِلَى مُحدث قطّ بِالْكُوفَةِ فَقلت كتبت عِنْد أحد الا قَالَ مَا زَالَ يخْتَلف السكونِي إِلَيّ وَمَا أخرجُوا كتابا إِلَّا وَفِيه فرغ أَبُو همام ويوقفني على علامته وَأما يحيى بن حَمْزَة فَخرجت أُرِيد إفريقية وَكَانَ أَبُو همام قد خرج إِلَى الشَّام فَجئْت إِلَى دمشق فسالت عَنهُ فَقَالُوا قد كَانَ هَا هُنَا مُقيما وَسمع من يحيى بن حَمْزَة وَقد خرج وَرَأَيْت يحيى بن حَمْزَة وَعَلِيهِ سَواد للْقَضَاء فَلم أسمع مِنْهُ"],[1493,"وهيب بن الْورْد روى عَنهُ بن الْمُبَارك وَهُوَ ثِقَة وَكَانَ رجلا متحليا وَهُوَ أَخُو عبد الْجَبَّار بن الْورْد قَالَه يحيى قَالَ بن أبي خَيْثَمَة كَانَ اسْمه عبد الْوَهَّاب فصغر وَقَالَ فِيهِ أَحْمد بخ من أَصْحَاب الحَدِيث لَيْسَ بِهِ بَأْس"],[1494,"وهب بن كيسَان ثِقَة قَالَه أَحْمد وَيحيى"],[1495,"وهب بن عقبَة البكائي كُوفِي صَالح الحَدِيث"],[1496,"وروى عَن وَكِيع عَن وَرْقَاء بن عمر أبي بشر وَقَالَ كَانَ ثِقَة نَا عبد الله بن منيع الْبَغَوِيّ قَالَ نَا أَبُو أَحْمد مَحْمُود بن غيلَان يَعْنِي بقوله أفضل وَلَا أورع وَلَا خيرا مِنْهُ"],[1497,"وقاء بن إِيَاس كُوفِي قَالَه بن معِين وَقَالَ يحيى بن سعيد مَا كَانَ وقاء بِالَّذِي يعْتَمد عَلَيْهِ"],[1498,"قَالَ يحيى بن معِين أَبُو عوَانَة ثِقَة واسْمه الوضاح وَقَالَ فِيهِ شُعْبَة إِن حَدثكُمْ أَبُو عوَانَة عَن أبي هُرَيْرَة فصدقوه"],[1499,"قَالَ أَحْمد أَبُو حرَّة اسْمه وَاصل بن عبد الرَّحْمَن ثِقَة وَأَخُوهُ سعيد بن عبد الرَّحْمَن ثِقَة أَيْضا وَقَالَ شُعْبَة فِي أبي حرَّة ذَاك من أصدق النَّاس"],[1500,"قَالَ أَحْمد وَاصل مولى أبي عُيَيْنَة ثِقَة"],[1501,"نَا عبد الله بن سُلَيْمَان قَالَ نَا عبد الله بن أَحْمد قَالَ حَدثنِي أبي قَالَ نَا سُفْيَان قَالَ لم يُجَالس وَائِل الزُّهْرِيّ وجالس ابْنه الزُّهْرِيّ قَالَ أبي وَائِل ثِقَة سمع من إِبْرَاهِيم يحدث عَن ابْنه عَن الزُّهْرِيّ وَهُوَ ثِقَة"],[1502,"والان بن قرفة بَصرِي ثِقَة قَالَه يحيى"],[1503,"الْوَضِين بن عَطاء ثِقَة قَالَه أَحْمد"],[1504,"قَالَ يحيى وَاقد بن عبد الله لَيْسَ بِهِ بَأْس"],[1505,"قَالَ وَأَبُو يَعْفُور يروي عَنهُ بن الْمُبَارك واسْمه عبد الرَّحْمَن بن عبيد بن ثَابت بن نسطاس وَأَبُو يَعْفُور الصَّغِير قَالَ يحيى كِلَاهُمَا ثِقَة"],[1506,"نَا عبد الله بن سُلَيْمَان بن الْأَشْعَث نَا أَبُو حَاتِم السجسْتانِي قَالَ سَأَلت الْأَصْمَعِي عَن هَارُون بن مُوسَى النَّحْوِيّ مولى العتيك وَهُوَ هَارُون الْأَعْوَر فَقَالَ كَانَ ثِقَة مَأْمُونا"],[1507,"قَالَ يحيى هَارُون صَاحب الْقِرَاءَة ثِقَة روى عَنهُ حَمَّاد بن زيد"],[1508,"وَقَالَ هَارُون بن رِئَاب ثِقَة وَكَذَلِكَ قَالَ أَحْمد"],[1509,"هَارُون بن عنترة شيخ ثِقَة وَهُوَ هَارُون بن أبي وَكِيع ويكنى هَارُون بِأبي عَمْرو الشَّيْبَانِيّ"],[1510,"وَهَارُون بن سعد عَنهُ روى عَنهُ النَّاس وَهُوَ صَالح أَظُنهُ كَانَ يتشيع"],[1511,"وَهَارُون بن الْمُغيرَة الرَّازِيّ شيخ صَدُوق ثِقَة قَالَه يحيى بن معِين مَرَرْنَا بِهِ فِي بُسْتَان لَهُ بِالريِّ فكتبنا مِنْهُ نَحوا من خَمْسَة أَحَادِيث"],[1512,"وَقَالَ أَحْمد فِي هَارُون الْبَرْبَرِي ثِقَة ثِقَة وَهُوَ هَارُون بن أبي إِبْرَاهِيم"],[1513,"قَالَ بن معِين هَارُون بن أبي إِبْرَاهِيم الثَّقَفِيّ ثِقَة"],[1514,"أَبُو عقيل هَاشم بن بِلَال الْأسود يحدث عَنهُ شُعْبَة وهشيم قَالَه يحيى وَأحمد"],[1515,"هَاشم الْبَرِيد ثِقَة قَالَه يحيى وَقَالَ أَحْمد مَا أرى بِهِ بَأْسا"],[1516,"وَقَالَ يحيى الْقطَّان حدث هِشَام بن عُرْوَة عَن عبد الرَّحْمَن بن الْقَاسِم وَقَالَ مكي عَن مكي"],[1517,"هِشَام بن حسان ثِقَة قَالَه يحيى بن معِين وَعُثْمَان"],[1518,"وَقَالَ وَكِيع حَدثنَا هِشَام الدستوَائي وَكَانَ ثبتا"],[1519,"وَقَالَ بن معِين كَانَ يحيى الْقطَّان إِذا سمع الحَدِيث من هِشَام بن أبي عبد الله لم يُبَالِي أَلا يسمعهُ من غَيره"],[1520,"قَالَ يحيى هِشَام بن الْغَاز بن ربيعَة الجرشِي لَيْسَ بِهِ بَأْس وَقَالَ أَحْمد صَالح الحَدِيث"],[1521,"وَهِشَام بن عَائِذ بن نصيب ثِقَة روى عَنهُ يحيى الْقطَّان قَالَه أَحْمد وَيحيى"],[1522,"وَهِشَام أَبُو كُلَيْب روى عَنهُ الثَّوْريّ قَالَه أَحْمد"],[1523,"وَقَالَ يحيى هِشَام بن سلمَان بَصرِي لَيْسَ بِهِ باس وَهُوَ صَاحب بكرَة"],[1524,"وَهِشَام بن عَمْرو الْفَزارِيّ يروي عَنهُ حَمَّاد بن سَلمَة لَيْسَ يروي عَنهُ غير حَمَّاد وَهُوَ ثِقَة"],[1525,"وَقَالَ يحيى هِشَام بن عبد الْملك الطَّيَالِسِيّ بَصرِي ثِقَة"],[1526,"وَهِشَام بن حُجَيْر ثِقَة"],[1527,"وَقَالَ أَحْمد هِشَام بن لَاحق كَانَ يحدث عَن عَاصِم الْأَحول كتبنَا عَنهُ أَحَادِيث لم يكن بِهِ بَأْس وَرفع عَن عَاصِم أَحَادِيث لم ترفع أسندها إِلَى سُلَيْمَان"],[1528,"وَقَالَ يحيى همام بن مُنَبّه ثِقَة"],[1529,"وَقَالَ عَليّ بن الْمَدِينِيّ لَيْسَ بعد سعيد وَهِشَام أحد من أَصْحَاب قَتَادَة أحب إِلَيّ من همام وَهَمَّام اسندهم للْحَدِيث"],[1530,"أَبُو الْعَجْفَاء هرم وَهُوَ بَصرِي ثِقَة قَالَه يحيى"],[1531,"هريم بن سُفْيَان البَجلِيّ صَالح الحَدِيث أَبُو مُحَمَّد قَالَه أَحْمد وَقَالَ يحيى هُوَ ثِقَة وَقَالَ عُثْمَان هُوَ ثِقَة صَدُوق ثَبت"],[1532,"ثَنَا عبد الله بن مُحَمَّد الْبَغَوِيّ قَالَ ثَنَا شُجَاع بن مخلد نَا وهب بن جرير قَالَ قدم علينا هشيم بِالْبَصْرَةِ فِي أَيَّام شُعْبَة فسالنا شُعْبَة نكتب عَن هشيم فَقَالَ شُعْبَة إِن حَدثكُمْ هشيم عَن بن عمر فصدقوه ثَنَا عبد الله بن مُحَمَّد قَالَ ثَنَا يحيى بن أَيُّوب قَالَ سَمِعت أَبَا عُبَيْدَة الْحداد قَالَ قدم علينا هشيم الْبَصْرَة فذكرناه لشعبة فَقُلْنَا قدم صديقك هشيم نكتب عَنهُ فَقَالَ أَن حَدثكُمْ عَن بن عَبَّاس وَابْن عمر فصدقوه فأتينا هشيما فحدثنا برقائق مُغيرَة فاتينا شُعْبَة فَأَخْبَرنَاهُ فَأَعْرض بِوَجْهِهِ قَالَ أكبر أَبُو مُعَاوِيَة قَالَ عبد الله بن مُحَمَّد أخْبرت عَن هشيم قَالَ كَانَ جدي الْقَاسِم وَأَبُو شُعْبَة بن الْحجَّاج شَرِيكَيْنِ فِي بِنَاء قصر الْحجَّاج يَعْنِي بواسط ثَنَا عبد الله بن مُحَمَّد قَالَ ثَنَا يحيى بن أَيُّوب قَالَ حَدثنِي نصر بن بسام وَغَيره من أَصْحَابنَا قَالُوا أَتَيْنَا أَبَا مَحْفُوظ مَعْرُوف الْكَرْخِي فَقَالَ لنا رَأَيْت النَّبِي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْمَنَام وَهُوَ يَقُول لهشيم يَا هشيم جَزَاك الله عَن أمتِي خيرا قَالَ بن بسام فَقلت لَهُ يَا أَبَا مَحْفُوظ أَنْت رايته قَالَ نعم هشيم خير مِمَّا نظن خير مِمَّا نظن رَضِي الله عَن هشيم"],[1533,"هِلَال بن أبي حميد هُوَ هِلَال الْوزان وَهُوَ ثِقَة قَالَه يحيى"],[1534,"هِلَال بن خباب مدائني ثِقَة"],[1535,"وهلال بن أبي زَيْنَب ثِقَة يروي عَنهُ بن عون فَقَط"],[1536,"وهلال بن خباب ثِقَة"],[1537,"وهلال بن سلمَان أَبُو محلم ثِقَة لَيْسَ بِهِ باس قَالَه أَحْمد وَيحيى"],[1538,"والهيثم بن رَافع الطاطري ثِقَة بَصرِي قَالَه يحيى"],[1539,"والهيثم بن حميد مَا علمت الا خيرا قَالَه أَحْمد"],[1540,"وَقَالَ الْهَيْثَم بن جميل ثِقَة"],[1541,"قَالَ بن مسْهر لم يكن فِي أَصْحَاب الْأَوْزَاعِيّ مثل هِقْل بن زِيَاد ثِقَة"],[1542,"ثَنَا يحيى بن مُحَمَّد بن صاعد قَالَ ثَنَا أَحْمد بن مُحَمَّد بن هاني أَبُو بكر الْأَثْرَم الطَّائِي قَالَ قلت لأبي عبد الله أَحْمد بن حَنْبَل كَانَ هِشَام أكبر عنْدك من شَيبَان قَالَ هِشَام ارْفَعْ يَعْنِي هِشَام الدستوَائي هِشَام حَافظ وشيبان صَاحب كتاب قيل لَهُ حَرْب بن شَدَّاد كَيفَ هُوَ قَالَ لَا بَأْس بِهِ قيل لَهُ شَيبَان فَقَالَ شَيبَان ارْفَعْ عِنْدِي شَيبَان صَاحب كتاب صَحِيح قد روى شَيبَان عَن النَّاس فَحَدِيثه صَالح حرف الْيَاء"],[1543,"قَالَ أَحْمد يزِيد بن أبي الْجَعْد شيخ ثِقَة"],[1544,"وَقَالَ يحيى يزِيد بن هَارُون واسطي وَهُوَ ثِقَة"],[1545,"وَيزِيد بن الرشك لَيْسَ بِهِ بَأْس وَقَالَ يحيى مرّة أُخْرَى يزِيد الرشك ضَعِيف"],[1546,"وَقَالَ يحيى أَبُو خَالِد يزِيد بن عبد الرَّحْمَن الدالاني لَيْسَ بِهِ باس"],[1547,"وَيزِيد بن عبد الله بن قسيط ثِقَة"],[1548,"وَيزِيد بن خصيفَة ثِقَة"],[1549,"وَيزِيد بن حَازِم ثِقَة بَصرِي"],[1550,"وَيزِيد بن كيسَان كُوفِي ثِقَة وَقَالَ يحيى بن سعيد لَيْسَ يزِيد بن كيسَان مِمَّن يعْتَمد عَلَيْهِ وَهُوَ وسط صَالح"],[1551,"وَقَالَ أَحْمد بن صَالح يزِيد بن أبي زِيَاد ثِقَة لَا يُعجبنِي قَول من يتَكَلَّم فِيهِ"],[1552,"وَقَالَ بن معِين يزِيد النَّحْوِيّ خراساني ثِقَة"],[1553,"ثَنَا أَحْمد بن مُحَمَّد بن إِسْمَاعِيل السوطي قَالَ ثَنَا عَليّ بن أشكاب قَالَ ثَنَا أَبُو قطن قَالَ ثَنَا يزِيد بن إِبْرَاهِيم التسترِي الذَّهَب الْمُصَفّى الذَّهَب الْمُصَفّى"],[1554,"ثَنَا مُحَمَّد بن مخلد ثَنَا مُحَمَّد عبد الله الزهيري قَالَ سَمِعت عَفَّان يَقُول كنت أكون عِنْد شُعْبَة فَاكْتُبْ عَنهُ فِي ألواحي ثمَّ أَمر بِيَزِيد بن زُرَيْع وَهُوَ يحدث فامحوا حَدِيث شُعْبَة واكتب حَدِيث يزِيد وَهُوَ اثْبتْ النَّاس"],[1555,"قَالَ يحيى يزِيد بن خَلِيل النَّخعِيّ ثِقَة"],[1556,"وَيزِيد بن الْمِقْدَام بن شُرَيْح لَيْسَ بِهِ باس"],[1557,"وَأَبُو الْمُعْتَمِر يزِيد بن طهْمَان كَانَ بصريا نزل الْكُوفَة وَكَانَ يروي عَنهُ أَبُو نعيم وَكَانَ من أهل السّنة وَكَانَ ثِقَة"],[1558,"وَيزِيد بن مردانبة ثِقَة"],[1559,"وَيزِيد بن عبد الله الشَّيْبَانِيّ يروي عَن شهر بن حَوْشَب وَهُوَ كُوفِي ثِقَة"],[1560,"وَيزِيد وَجَرِير ابْنا حَازِم هما إخْوَان وهما ثقتان وَكَانَ يزِيد أكبرهما"],[1561,"يزِيد بن إِبْرَاهِيم ثِقَة قَالَه أَحْمد"],[1562,"وَيزِيد بن خمير صَالح الحَدِيث"],[1563,"وَيزِيد بن عبد الْعَزِيز بن سياه ثِقَة"],[1564,"وَيزِيد بن عَطاء لَيْسَ بِهِ بَأْس ثمَّ قَالَ حَدِيثه مقارب"],[1565,"وَيزِيد بن خصيفَة مَا أعلم إِلَّا خيرا وَقَالَ يحيى ثِقَة"],[1566,"وَأَبُو الْمُعْتَمِر الْحِيرِي يزِيد بن طهْمَان لَيْسَ بحَديثه بَأْس حدث عَنهُ عبد الرَّحْمَن ووكيع"],[1567,"أَبُو كثير الغبري يزِيد بن عبد الرَّحْمَن بن أذينة السحيمي يمامي ثِقَة قَالَه يحيى"],[1568,"وَأَبُو وجزة السَّعْدِيّ يزِيد بن عبيد مديني ثِقَة"],[1569,"وَيزِيد بن عبد الله بن الْهَاد ثِقَة"],[1570,"ثَنَا مُحَمَّد بن أَحْمد بن الْحسن ثَنَا مُحَمَّد بن عُثْمَان بن أبي شيبَة قَالَ سَمِعت أبي يَقُول لنا ثَنَا وَكِيع عَن يزِيد بن أبي زِيَاد الدِّمَشْقِي سَأَلت وكيعا عَنهُ فَقَالَ كَانَ هَذَا رفيعا فِي أهل الشَّام فِي الْفِقْه وَالصَّلَاح"],[1571,"يزِيد بن رُومَان ثِقَة قَالَه يحيى"],[1572,"وَيزِيد بن أبي صَالح أَبُو حبيب ثِقَة"],[1573,"وَيزِيد بن صُهَيْب الْفَقِير ثِقَة"],[1574,"وَيُونُس بن بكير ثِقَة إِلَّا أَنه يتشيع"],[1575,"يحيى بن عَتيق ثِقَة"],[1576,"ثَنَا عُثْمَان ثَنَا أَحْمد بن حَنْبَل بن إِسْحَاق قَالَ سَمِعت أَبَا عبد الله مُحَمَّد بن حَنْبَل قَالَ مَا رَأَيْت أحدا أقل خطأ من يحيى بن سعيد وَلَقَد أَخطَأ فِي أَحَادِيث ثمَّ قَالَ أَبُو عبد الله وَمن يعرى من الْخَطَأ والتصحيف"],[1577,"يحيى بن الْحَارِث الذمارِي لَيْسَ بِهِ بَأْس قَالَه يحيى"],[1578,"وَأَبُو تُمَيْلة يحيى بن وَاضح ثِقَة وَمَات بالعراق"],[1579,"وَيحيى بن الْمُهلب أَبُو كُدَيْنَة ثِقَة قَالَه أَحْمد وَيحيى"],[1580,"أَبُو الْمحيا يحيى بن يعلي بن حَرْمَلَة ثِقَة قَالَه يحيى"],[1581,"وَقَالَ يحيى بن سليم الطَّائِفِي ثِقَة"],[1582,"وَيحيى بن سعيد الْأمَوِي ثِقَة"],[1583,"وَيحيى بن أَيُّوب البَجلِيّ سمع مِنْهُ عبد الله بن الْمُبَارك وَلَيْسَ بِهِ بَأْس وَيحيى بن أَيُّوب البَجلِيّ صَالح الحَدِيث"],[1584,"وَيحيى بن أَيُّوب الْمصْرِيّ لَيْسَ بِهِ بَأْس قَالَ أَحْمد بن صَالح لَهُ أَشْيَاء يُخَالف فِيهَا"],[1585,"ثَنَا مُحَمَّد بن مخلد ثَنَا الْعَبَّاس بن مُحَمَّد نَا أَبُو بكر يَعْنِي بن الْأسود ثَنَا يحيى بن سعيد قَالَ كَانَ شُعْبَة يَقُول يحيى بن أبي كثير أحسن حَدِيثا من الزُّهْرِيّ"],[1586,"يحيى بن كثير الْكَاهِلِي روى عَنهُ صَالح بن إِسْحَاق الْجرْمِي وَقَالَ كَانَ ثِقَة لَا بَأْس بِهِ"],[1587,"يحيى بن زَكَرِيَّا قَالَ بن معِين ثِقَة قيل لَهُ أَن زَكَرِيَّا بن عدي لم يحدث عَنهُ فَقَالَ هُوَ خير من زَكَرِيَّا بن عدي وَمن أَبِيه وَمن أهل قريته"],[1588,"يحيى بن زَكَرِيَّا بن إِبْرَاهِيم بن سُوَيْد النَّخعِيّ مَا كَانَ بِهِ باس كَانَ صَدُوقًا"],[1589,"يحيى بن سليم كَانَ جَائِز الحَدِيث وَكَانَ رجلا صَالحا"],[1590,"أَبُو عقيل يحيى بن المتَوَكل الدَّوْرَقِي ثِقَة"],[1591,"يحيى بن سعيد الْأمَوِي من أهل الصدْق لَيْسَ بِهِ بَأْس قَالَه يحيى"],[1592,"يحيى بن مُحَمَّد بن طحلا ثِقَة"],[1593,"وَيحيى بن بشر الَّذِي حدث عَنهُ بن الْمُبَارك ثِقَة يكني أَبَا وهب من مرو الروذ"],[1594,"وَقَالَ أَحْمد بن حَنْبَل مَا أخرجت خُرَاسَان بعد بن الْمُبَارك مثل يحيى بن يحيى قَالَ وَكُنَّا نُسَمِّيه يحيى الشكاك يَعْنِي من كَثْرَة مَا كَانَ يشك فِي الحَدِيث"],[1595,"وَيحيى بن حسان ثِقَة"],[1596,"وَقَالَ عُثْمَان يحيى بن يمَان الْعجلِيّ كَانَ صَدُوقًا ثِقَة وَلَكِن فِي حفظه تَخْلِيط"],[1597,"قَالَ يحيى بن معِين يحيى بن عبد الرَّحْمَن بن عجلَان كُوفِي ثِقَة"],[1598,"وَأَبُو الْمِقْدَام يحيى ثِقَة"],[1599,"وَأَبُو الْمُعَلَّى الْعَطَّار اسْمه يحيى الْبَصْرِيّ حدث عَنهُ شُعْبَة وَحَمَّاد بن زيد وَابْن علية وَلَيْسَ بِهِ بَأْس"],[1600,"قَالَ احْمَد الْأَجْلَح الْكِنْدِيّ اسْمه يحيى بن عبد الله بن مُعَاوِيَة أَبُو حجية الْكِنْدِيّ"],[1601,"وَيحيى بن أبي عَمْرو السيباني ثِقَة ثِقَة"],[1602,"وَأَبُو هَاشم الرماني ثِقَة اسْمه يحيى بن دِينَار"],[1603,"قَالَ بن معِين أَبُو الْمُعَلَّى الْعَطَّار ثِقَة اسْمه يحيى"],[1604,"وَأَبُو حَيَّان التَّيْمِيّ يحيى بن سعيد"],[1605,"وَيحيى بن حَيَّان أَبُو هِلَال الطَّائِي ثِقَة"],[1606,"وَقَالَ أَبُو بكر بن عَيَّاش وَذكر يحيى بن يمَان فَقَالَ ذَاك رَاهِب"],[1607,"يحيى بن آدم ثِقَة صَدُوق ثَبت حجَّة مَا لم يُخَالِفهُ من هُوَ فَوْقه مثل جرير ووكيع قَالَه عُثْمَان بن أبي شيبَة"],[1608,"وَيحيى بن عقيل لَا بَأْس بِهِ قَالَه بن معِين"],[1609,"وَيحيى بن حسان روى عَنهُ الشَّافِعِي وَقَالَ أَنا الثِّقَة يحيى بن حسان"],[1610,"يُونُس بن عبيد روى عَنهُ سُفْيَان بن حُسَيْن وَقَالَ حَدثنِي الثِّقَة"],[1611,"يُونُس بن أبي إِسْحَاق ثِقَة لَيْسَ بِهِ بَأْس قَالَه بن معِين"],[1612,"وَقَالَ مُحَمَّد بن سِيرِين لقِيت أَبَا غلاب يُونُس بن جُبَير الْبَاهِلِيّ وَكَانَ ذَا ثَبت"],[1613,"وَقَالَ عُثْمَان يُونُس بن خباب ثِقَة صَدُوق"],[1614,"يُونُس بن أبي الْفُرَات قَالَ أَحْمد قد حَدثنَا عَنهُ البرْسَانِي أَرْجُو أَن يكون ثِقَة صَالح الحَدِيث"],[1615,"قَالَ وَيُونُس الْجرْمِي شيخ ثِقَة حَدثنَا عَنهُ بن عُيَيْنَة ومعتمر وَحدث عَنهُ شُعْبَة قَالَ بن معِين يُونُس الْجرْمِي كُوفِي ثِقَة"],[1616,"وَقَالَ يُونُس أَبُو قطامي ثِقَة"],[1617,"وَيُونُس بن بكير ثِقَة وَقَالَ بن عمار هُوَ الْيَوْم الثِّقَة عِنْد أَصْحَاب الحَدِيث"],[1618,"وَقَالَ عبيد بن يعِيش أَبُو بكر يُونُس بن بكير الشَّيْبَانِيّ وَكَانَ ثِقَة"],[1619,"وَقَالَ بن معِين أَبُو يُوسُف ثِقَة إِذا حدث عَن الثِّقَات"],[1620,"وَيَعْقُوب بن مُحَمَّد بن طحلاء ثِقَة"],[1621,"وَيَعْقُوب بن عبد الرَّحْمَن الْقَارِي ثِقَة كُوفِي حدث عَنهُ يحيى بن سعيد وَمُحَمّد بن عبيد الله قَالَه أَحْمد"],[1622,"يَعْقُوب بن الْقَعْقَاع خراساني ثِقَة قَالَه يحيى"],[1623,"وَيَعْقُوب بن حميد بن كاسب لَيْسَ بِثِقَة قَالَه بن معِين قيل لَهُ من أَيْن قلت ذَلِك قَالَ لِأَنَّهُ مَحْدُود قلت أَلَيْسَ هُوَ فِي سَمَاعه ثِقَة قَالَ بلَى قَالَ بن أبي خَيْثَمَة قلت لمصعب الزبيرِي إِن يحيى بن معِين يَقُول فِي بن كاسب إِن حَدِيثه لَا يجوز لِأَنَّهُ مَحْدُود قَالَ بئس مَا قَالَ إِنَّمَا حسده الطالبيون فِي التحامل وَلَيْسَ حُدُود الطالبين عندنَا بِشَيْء وَابْن كاسب ثِقَة مَأْمُون صَاحب حَدِيث أَبوهُ مولى الخيزران كَانَ من أُمَنَاء الْقُضَاة زَمَانا"],[1624,"ثَنَا مُحَمَّد بن الْحسن قَالَ ثَنَا حُسَيْن بن إِدْرِيس قَالَ سَأَلت مُحَمَّد بن عبد الله بن عمار عَن ولد عبيد أَيهمْ أثبت فَقَالَ كلهم ثَبت قَالَ أحفظهم يعلى بن عبيد وأبصرهم بِالْحَدِيثِ مُحَمَّد بن عبيد الأحدب وَعمر بن عبيد شيخهم وَكَانَ مُحَمَّد يروي عَن عمر أَخِيه هَذَا وَهُوَ بَين يَدَيْهِ وَلَا يعلم أحد انه عمر إِلَّا أَصْحَاب الحَدِيث يَقُول حَدثنِي أخي وَكَانَ الْأَخ الرَّابِع لَا يسحن قَلِيلا وَلَا كثيرا"],[1625,"ثَنَا عبد الله بن أَحْمد قَالَ قَالَ أبي يعلى بن حَكِيم ثِقَة"],[1626,"ثَنَا الْحسن بن أَحْمد قَالَ قرئَ على الْعَبَّاس بن مُحَمَّد قَالَ سَمِعت يحيى بن معِين يَقُول يعلى بن مُسلم الْمَكِّيّ ثِقَة"],[1627,"ثَنَا مُحَمَّد بن الْحسن ثَنَا حُسَيْن بن إِدْرِيس ثَنَا عُثْمَان بن أبي شيبَة قَالَ ثَنَا وَكِيع وَأَبُو دَاوُد الْحَفرِي عَن ياسين الْعجلِيّ قَالَ عُثْمَان وَكَانَ ثِقَة"],[1628,"ثَنَا الْحسن بن أَحْمد قَالَ قرئَ على الْعَبَّاس بن مُحَمَّد قَالَ سَمِعت يحيى بن معِين يَقُول يُوسُف بن صُهَيْب ثِقَة ثَنَا مُحَمَّد بن الْحسن ثَنَا حُسَيْن بن إِدْرِيس قَالَ سَمِعت عُثْمَان بن أبي شيبَة يَقُول يُوسُف بن صُهَيْب الَّذِي روى عَنهُ وَكِيع ثِقَة"],[1629,"ثَنَا الْحسن بن أَحْمد قَالَ قرئَ على الْعَبَّاس بن مُحَمَّد قَالَ سَمِعت يحيى بن معِين يَقُول يُوسُف بن عَبدة كنيته أَبُو عَبدة وَهُوَ بَصرِي ثِقَة"],[1630,"قَالَ وَسمعت يحيى يَقُول يُوسُف بن أَسْبَاط الَّذِي كَانَ بِالشَّام رجل صدق قلت لَهُ هُوَ بن أَسْبَاط بن مُحَمَّد قَالَ لَا"],[1631,"ثَنَا الْحُسَيْن بن أَحْمد بن صَدَقَة قَالَ ثَنَا أَحْمد بن أبي خَيْثَمَة قَالَ سَمِعت يحيى بن معِين يَقُول يُوسُف بن أبي المتئد كُوفِي ثِقَة ثَنَا الْحُسَيْن بن أَحْمد قَالَ قرئَ على الْعَبَّاس قَالَ سَمِعت يحيى يَقُول يُوسُف بن أبي المتئد ثِقَة كُوفِي يُوسُف بن أبي المتئد ثِقَة كُوفِي"],[1632,"ثَنَا الْحُسَيْن بن أَحْمد بن صَدَقَة ثَنَا أَحْمد بن أبي خَيْثَمَة قَالَ سَمِعت يحيى بن معِين يَقُول يُوسُف بن مبارك ثِقَة"],[1633,"ثَنَا مُحَمَّد بن احْمَد بن الْحسن ثَنَا مُحَمَّد بن عُثْمَان بن أبي شيبَة قَالَ سَمِعت إِبْرَاهِيم بن أبي مُعَاوِيَة يَقُول كنت مَعَ أبي ذَات لَيْلَة فَذكر يُوسُف بن مَيْمُون فَقَالَ لي يَا إِبْرَاهِيم كَانَ يُوسُف بن مَيْمُون مِمَّن رَفعه الله بِالصّدقِ"],[1634,"ثَنَا عبد الله بن مُحَمَّد الْبَغَوِيّ ثَنَا يحيى بن سعيد الْأمَوِي ثَنَا الْأَعْمَش عَن أبي إِسْحَاق عَن الْبَراء قَالَ مَا كل مَا نقُول قَالَ رَسُول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سمعناه مِنْهُ وَلَكِن مِنْهُ مَا سمعناه مِنْهُ مَا حَدثنَا أَصْحَابنَا وَلَا نكذب"],[1635,"ثَنَا عبد الله بن مُحَمَّد ثَنَا سعيد بن يحيى ثَنَا وَكِيع ثَنَا الْأَعْمَش عَن أبي إِسْحَاق عَن الْبَراء قَالَ مَا كل مَا نقُول قَالَ رَسُول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سمعناه مِنْهُ فَذكر مثله يَعْنِي وَلَكِن مِنْهُ مَا سمعناه وَمِنْه مَا حَدثنَا أَصْحَابنَا وَلَا نكذب"],[1636,"ثَنَا عبد الله بن سُلَيْمَان بن الْأَشْعَث قَالَ ثَنَا أَيُّوب بن مُحَمَّد الْوزان قَالَ ثَنَا مَرْوَان بن مُعَاوِيَة الْفَزارِيّ ثَنَا مُعَاوِيَة بن أبي الْعَبَّاس الْقَيْسِي عَن عَليّ بن ربيعَة الْأَسدي عَن أَسمَاء بن الحكم الْفَزارِيّ قَالَ قَالَ عَليّ بن أبي طَالب رضي الله عنه كَانَ الرجل إِذا حَدثنِي عَن رَسُول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِحَدِيث اسْتَحْلَفته فَإِذا حلف لي صدقته وحَدثني أَبُو بكر وَصدق أَبُو بكر"],[1637,"ثَنَا الْحُسَيْن بن أَحْمد بن صَدَقَة ثَنَا أَحْمد بن أبي خَيْثَمَة قَالَ ثَنَا مُوسَى بن إِسْمَاعِيل ثَنَا أَبُو هِلَال الرَّاسِبِي ثَنَا عبد الله بن صبيح عَن مُحَمَّد بن سِيرِين قَالَ إِن كَانَ سَمُرَة مَا عَلمته لصدوق الحَدِيث"],[1638,"ثَنَا عبد الله بن سُلَيْمَان ومكرم بن احْمَد قَالَا ثَنَا عبد الله بن احْمَد بن حَنْبَل قَالَ حَدثنِي أبي قَالَ ثَنَا عبد الصَّمد قَالَ ثَنَا أَبُو هِلَال قَالَ ثَنَا عبد الله بن صبيح عَن بن سِيرِين قَالَ كَانَ سَمُرَة مَا علمت عَظِيم الْأَمَانَة صَدُوق الحَدِيث يحب الْإِسْلَام واهله"],[1639,"ثَنَا مُحَمَّد بن عَمْرو بن البخْترِي ثَنَا يحيى بن أبي طَالب انا زيد بن الْحباب أَنا بن لَهِيعَة انا خَالِد بن يزِيد عَن عَامر بن سعد عَن عقبَة بن نَافِع الْقرشِي وَكَانَ اسْتشْهد بأفريقية وانه أوصى وَلَده فَقَالَ لَا تقبلُوا الحَدِيث عَن رَسُول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَّا عَن ثِقَة وَلَا تدينوا وَإِن لبستم العباء وَلَا يكتبن أحدكُم شعرًا يشغل قلبه عَن الْقُرْآن"],[1640,"ثَنَا عمر بن الْحُسَيْن بن عَليّ بن مَالك قَالَ ثَنَا أَبُو إِسْمَاعِيل التِّرْمِذِيّ قَالَ سَمِعت الْحميدِي يَقُول سَمِعت بن عُيَيْنَة يَقُول سَمِعت مسعرا يَقُول سَمِعت سعد بن إِبْرَاهِيم يَقُول لَا يحدث عَن رَسُول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَّا الثِّقَات"],[1641,"ثَنَا مُحَمَّد بن احْمَد بن محبوبة العسكري قَالَ انا أَبُو زرْعَة الدِّمَشْقِي قَالَ سَمِعت أَبَا مسْهر يسْأَل يحيى بن معِين فِي سنة أَربع عشرَة وَمِائَتَيْنِ عَن سنه فَقَالَ أَنا بن خمس وَسِتِّينَ سنة قلت لَهُ فَمن أسن أَنْت أَو أَحْمد بن حَنْبَل قَالَ انا"],[1642,"ثَنَا مُحَمَّد قَالَ ثَنَا أَبُو زرْعَة قَالَ حدثت عَن يحيى بن معِين قَالَ ولدت سنة ثَمَان وَخمسين وَمِائَة"],[1643,"ثَنَا الْحُسَيْن بن احْمَد بن صَدَقَة قَالَ ثَنَا بن أبي خَيْثَمَة قَالَ قلت ليحيى بن معِين إِنَّك تَقول فلَان لَيْسَ بِهِ بَأْس وَفُلَان ضَعِيف قَالَ إِذا قلت لَك لَيْسَ بِهِ بَأْس فَهُوَ ثِقَة وَإِذا قلت هُوَ ضَعِيف فَلَيْسَ هُوَ بِثِقَة لَا تكْتب حَدِيثه"],[1644,"ثَنَا الْحسن بن احْمَد الأصطخري قَالَ قرئَ على الْعَبَّاس بن مُحَمَّد قَالَ سَمِعت يحيى بن معِين يَقُول قَالَ يحيى بن سعيد الْقطَّان لَو لم أرو الا عَن كل من أرْضى أَو كلمة نَحْوهَا مَا رويت الا عَن خمس"],[1645,"ثَنَا مُحَمَّد بن مُحَمَّد بن سُلَيْمَان الباغندي قَالَ حَدثنِي مُحَمَّد بن بشار بنْدَار قَالَ سَمِعت يحيى بن سعيد يَقُول وَقلت لَهُ عَن ثِقَة فَقَالَ لَا تقل عَن ثِقَة لَو حققت لَك مَا حدثتك إِلَّا عَن أَرْبَعَة بن عون وَشعْبَة ومسعر وَهِشَام الدستوَائي"],[1646,"ثَنَا الْحُسَيْن بن صَدَقَة ثَنَا احْمَد بن أبي خَيْثَمَة قَالَ ثَنَا عَليّ بن الْمَدِينِيّ قَالَ حَدثنِي أَيُّوب بن المتَوَكل عَن عبد الرَّحْمَن بن مهْدي قَالَ لَا يكون إِمَامًا فِي الْعلم من أَخذ بالشاذ من الْعلم وَلَا يكون إِمَامًا فِي الْعلم من روى كل مَا سمع قَالَ وَالْحِفْظ والإتقان"],[1647,"حَدثنِي عمر بن أبي السّري الْحَافِظ قَالَ سَمِعت عبد الله بن مُحَمَّد بن منيع يَقُول كُنَّا على بَاب يحيى بن عبد الحميد الْحمانِي فجَاء يحيى بن معِين على بغلته فَسَأَلَهُ أَصْحَاب الحَدِيث فَأبى وَقَالَ جِئْت مُسلما على أبي زَكَرِيَّا فَدخل ثمَّ خرج فَسَأَلُوهُ عَنهُ فَقَالَ ثِقَة ثِقَة"],[1648,"ثَنَا إِسْمَاعِيل بن عَليّ بن إِسْمَاعِيل قَالَ بَلغنِي ان بن الْمُبَارك حضر عِنْد حَمَّاد بن زيد مُسلما عَلَيْهِ فَقَالَ أَصْحَاب الحَدِيث لحماد بن زيد يَا أَبَا إِسْمَاعِيل تسْأَل أَبَا عبد الرَّحْمَن ان يحدثنا فَقَالَ يَا أَبَا عبد الرَّحْمَن تحدثهم قَالَ سُبْحَانَ الله يَا أَبَا إِسْمَاعِيل أحدث وَأَنت حَاضر فَقَالَ أَقْسَمت عَلَيْك لتفعلن أَو نَحوه قَالَ فَقَالَ بن الْمُبَارك خُذُوا ثَنَا أَبُو إِسْمَاعِيل حَمَّاد بن زيد فَمَا حدث بِحرف إِلَّا عَن حَمَّاد بن زيد"],[1649,"ثَنَا احْمَد بن عبد الله بن سَالم قَالَ ثَنَا عَليّ بن سهل قَالَ سَمِعت أَحْمد بن حَنْبَل فِي دهليز عَفَّان يَقُول لعبد الله الرُّومِي لَيْت أَبَا زَكَرِيَّا قد قدم يَعْنِي بن معِين فَقَالَ اليمامي مَا تصنع بقدومه يُعِيد علينا مَا قد سمعناه فَقَالَ لَهُ احْمَد اسْكُتْ هُوَ يعرف خطأ الحَدِيث"],[1650,"ثَنَا إِسْمَاعِيل بن عَليّ بن مُوسَى بن إِسْحَاق نَا منْجَاب أَنا بن مسْهر عَن زَكَرِيَّا بن أبي زَائِدَة عَن سعد بن إِبْرَاهِيم قَالَ كَانَ يُقَال خُذُوا الحَدِيث من الثِّقَات"]]);
